CREATE OR REPLACE FUNCTION public.admin_settle_savings_request(p_request_id uuid, p_capital_amount numeric, p_yield_amount numeric, p_reason text, p_client_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_request record;v_balance record;v_capital numeric:=coalesce(p_capital_amount,0);v_yield numeric:=coalesce(p_yield_amount,0);v_existing record;
begin
  if auth.uid() is null or not public.has_admin_permission('savings.approve') then raise exception 'SAVINGS_APPROVE_DENIED' using errcode='42501'; end if;
  if p_client_action_id is null or length(btrim(coalesce(p_reason,'')))<3 or v_capital<0 or v_yield<0 or v_capital+v_yield<=0 then raise exception 'SAVINGS_SETTLEMENT_INVALID' using errcode='22023'; end if;
  select * into v_existing from public.savings_audit_events where client_action_id=p_client_action_id;
  if found then return v_existing.after_data; end if;
  select * into v_request from public.savings_requests where id=p_request_id for update;
  if not found or v_request.status<>'APPROVED' or v_request.request_type not in ('WITHDRAW','EXTRAORDINARY_WITHDRAWAL','TERMINATE') then raise exception 'SAVINGS_REQUEST_NOT_SETTLEABLE' using errcode='P0001'; end if;
  select * into v_balance from public.savings_participant_balance(v_request.participant_id);
  if v_request.component='CAPITAL' and v_yield<>0 or v_request.component='YIELD' and v_capital<>0 then raise exception 'SAVINGS_SETTLEMENT_COMPONENT_MISMATCH' using errcode='22023'; end if;
  if v_request.request_type='EXTRAORDINARY_WITHDRAWAL' and v_yield<>0 then raise exception 'SAVINGS_EXTRAORDINARY_CAPITAL_ONLY' using errcode='22023'; end if;
  if v_capital>greatest(v_balance.capital-v_balance.held_capital,0) or v_yield>greatest(v_balance.yield_amount-v_balance.held_yield,0) then raise exception 'SAVINGS_AVAILABLE_BALANCE_EXCEEDED' using errcode='22023'; end if;
  if v_request.request_type<>'TERMINATE' and v_request.requested_amount is distinct from v_capital+v_yield then raise exception 'SAVINGS_SETTLEMENT_BREAKDOWN_MISMATCH' using errcode='22023'; end if;
  if v_request.request_type='TERMINATE' and (v_capital<>greatest(v_balance.capital-v_balance.held_capital,0) or v_yield<>greatest(v_balance.yield_amount-v_balance.held_yield,0)) then raise exception 'SAVINGS_TERMINATION_REQUIRES_FULL_AVAILABLE' using errcode='22023'; end if;
  if v_capital>0 then insert into public.savings_transactions(participant_id,enrollment_id,transaction_type,component,direction,amount,effective_date,idempotency_key,created_by_auth_user_id)
    values(v_request.participant_id,v_request.enrollment_id,'WITHDRAWAL','CAPITAL','DEBIT',v_capital,current_date,'SAVINGS_SETTLEMENT:'||p_request_id||':CAPITAL',auth.uid()); end if;
  if v_yield>0 then insert into public.savings_transactions(participant_id,enrollment_id,transaction_type,component,direction,amount,effective_date,idempotency_key,created_by_auth_user_id)
    values(v_request.participant_id,v_request.enrollment_id,'WITHDRAWAL','YIELD','DEBIT',v_yield,current_date,'SAVINGS_SETTLEMENT:'||p_request_id||':YIELD',auth.uid()); end if;
  update public.savings_requests set status='SETTLED',settled_at=now(),requested_capital_amount=v_capital,requested_yield_amount=v_yield,
    reason=case when reason='' then btrim(p_reason) else reason||E'\nLiquidaci�n: '||btrim(p_reason) end where id=p_request_id returning * into v_request;
  if v_request.request_type='TERMINATE' then update public.savings_enrollments set status='TERMINATED',continue_saving=false,terminated_at=now() where id=v_request.enrollment_id; end if;
  insert into public.savings_audit_events(actor_real_auth_user_id,usuario_contexto_affiliate_id,participant_id,resource,action,target_id,after_data,reason,client_action_id)
  values(auth.uid(),v_request.usuario_contexto_affiliate_id,v_request.participant_id,'savings_requests','SETTLE',v_request.id::text,to_jsonb(v_request),btrim(p_reason),p_client_action_id);
  return to_jsonb(v_request);
end $function$

CREATE OR REPLACE FUNCTION public.approve_financial_program_request(p_request_id uuid, p_snapshot jsonb, p_approved_by uuid, p_comment text)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.program_requests%rowtype;
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_actor_label text;
  v_from_status text;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then
    raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023';
  end if;
  select status into v_from_status from public.program_requests where id=p_request_id for update;
  v_row:=public.approve_financial_program_request(p_request_id,p_snapshot,p_approved_by);
  select coalesce(
    nullif(btrim(raw_user_meta_data->>'display_name'),''),
    nullif(btrim(raw_user_meta_data->>'full_name'),''),
    nullif(btrim(raw_user_meta_data->>'name'),''),
    'Personal autorizado'
  ) into v_actor_label from auth.users where id=p_approved_by;
  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,created_at
  ) values(
    v_row.id,p_approved_by,left(coalesce(v_actor_label,'Personal autorizado'),160),'APPROVE',coalesce(v_from_status,'in_review'),'approved',
    v_comment,extensions.gen_random_uuid(),coalesce(v_row.financial_approved_at,now())
  ) on conflict(request_id) where action='APPROVE' do nothing;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.approve_financial_program_request(p_request_id uuid, p_snapshot jsonb, p_approved_by uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.program_requests%rowtype; v_required text[]:=array[
  'affiliate_id','numero_control','financial_union','financial_employee_category','affiliation_status','fund','rate','term',
  'maxAmount','requestedAmount','administrativeFee','financialResult','google_export'];
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  select * into v_row from public.program_requests where id=p_request_id for update;
  if v_row.id is null or v_row.financial_processing_status is null then raise exception 'FINANCIAL_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_row.financial_approval_snapshot is not null then return v_row; end if;
  if v_row.status not in ('requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_NOT_APPROVABLE' using errcode='P0001'; end if;
  if jsonb_typeof(p_snapshot)<>'object' or exists(select 1 from unnest(v_required) k where not(p_snapshot?k)) then raise exception 'FINANCIAL_APPROVAL_SNAPSHOT_INCOMPLETE' using errcode='22023'; end if;
  if p_snapshot->>'affiliate_id'<>v_row.affiliate_id::text or p_snapshot->>'numero_control'<>v_row.numero_control then raise exception 'FINANCIAL_SNAPSHOT_IDENTITY_MISMATCH' using errcode='22023'; end if;
  if jsonb_typeof(p_snapshot->'administrativeFee')<>'object' or not((p_snapshot->'administrativeFee')?'rule') or not((p_snapshot->'administrativeFee')?'version') then raise exception 'ADMINISTRATIVE_FEE_CONTRACT_INCOMPLETE' using errcode='22023'; end if;
  if jsonb_typeof(p_snapshot->'google_export')<>'object' or jsonb_typeof(p_snapshot->'google_export'->'row')<>'array'
     or jsonb_array_length(p_snapshot->'google_export'->'row')<>38
     or p_snapshot->'google_export'->>'contract_version'<>'FINAL_APPROVED_LOAN_EXPORT_V1'
  then raise exception 'GOOGLE_EXPORT_CONTRACT_INCOMPLETE' using errcode='22023'; end if;
  if p_approved_by is null or not exists(select 1 from auth.users where id=p_approved_by) then raise exception 'APPROVAL_ACTOR_REQUIRED' using errcode='22023'; end if;
  update public.program_requests set status='approved',financial_processing_status='ready_for_handoff',financial_approval_snapshot=p_snapshot,
    financial_approved_at=now(),financial_approved_by=p_approved_by,updated_at=now() where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.approve_program_product_payment_request(p_request_id uuid, p_comment text, p_client_action_id uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.program_requests%rowtype;
  v_existing public.program_request_admin_events%rowtype;
  v_actor_label text;
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_from_status text;
begin
  if auth.uid() is null or not public.has_admin_permission('program_requests.write') then
    raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501';
  end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then
    raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023';
  end if;
  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or v_existing.action<>'APPROVE' then
      raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505';
    end if;
    select * into v_row from public.program_requests where id=p_request_id;
    return v_row;
  end if;
  select * into v_row from public.program_requests where id=p_request_id for update;
  if v_row.id is null or v_row.financial_processing_status is null
     or v_row.program_id='prestamo'
     or v_row.financial_submission_snapshot->>'contract_version'<>'PROGRAM_PRODUCT_PAYMENT_V1' then
    raise exception 'PROGRAM_PRODUCT_PAYMENT_REQUEST_NOT_FOUND' using errcode='P0001';
  end if;
  if v_row.financial_approval_snapshot is not null and v_row.status='approved' and v_row.financial_processing_status='completed' then
    return v_row;
  end if;
  if v_row.status not in('requires_financial_processing','in_review') then
    raise exception 'FINANCIAL_REQUEST_NOT_APPROVABLE' using errcode='P0001';
  end if;
  if not v_row.terms_accepted or nullif(btrim(coalesce(v_row.signature_data,'')),'') is null
     or v_row.terms_version_id is null or jsonb_typeof(v_row.financial_submission_snapshot)<>'object'
     or jsonb_typeof(v_row.financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(v_row.financial_submission_snapshot->'payment_schedule')<>'object' then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  v_from_status:=v_row.status;
  update public.program_requests set
    status='approved',financial_processing_status='completed',financial_approval_snapshot=
      v_row.financial_submission_snapshot||jsonb_build_object(
        'approval_contract_version','PROGRAM_PRODUCT_PAYMENT_APPROVAL_V1',
        'approved_at',now(),'approved_by',auth.uid(),'comment',v_comment
      ),
    financial_approved_at=now(),financial_approved_by=auth.uid(),updated_at=now()
  where id=v_row.id returning * into v_row;
  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),
    nullif(btrim(raw_user_meta_data->>'full_name'),''),nullif(btrim(raw_user_meta_data->>'name'),''),
    'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id
  ) values(v_row.id,auth.uid(),left(v_actor_label,160),'APPROVE',v_from_status,'approved',v_comment,p_client_action_id);
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_row.affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_APPROVED',v_row.id,
    jsonb_build_object('program_item_id',v_row.program_item_id,'processing_status','completed','google_handoff',false));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.archive_admin_affiliate(p_affiliate_id uuid, p_expected_updated_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.affiliates%rowtype;v_new public.affiliates%rowtype;v_reason text:=btrim(coalesce(p_reason,''));
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'AFFILIATE_ARCHIVE_REASON_REQUIRED' using errcode='22023'; end if;
  select * into v_old from public.affiliates where id=p_affiliate_id for update;
  if v_old.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.updated_at is distinct from p_expected_updated_at then raise exception 'AFFILIATE_VERSION_CONFLICT' using errcode='PT409'; end if;
  if v_old.is_archived then raise exception 'AFFILIATE_ALREADY_ARCHIVED' using errcode='22023'; end if;
  update public.affiliates set is_archived=true,archived_at=now(),archived_by_auth_user_id=auth.uid(),
    archive_reason=v_reason,archive_previous_status_raw=coalesce(affiliate_status_raw,'Sin estado'),
    restored_at=null,restored_by_auth_user_id=null,restore_reason=null
  where id=p_affiliate_id returning * into v_new;
  update public.impersonation_sessions set ended_at=now(),ended_by_auth_user_id=auth.uid()
   where usuario_contexto_affiliate_id=p_affiliate_id and ended_at is null;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(p_affiliate_id,auth.uid(),'ARCHIVE',
    jsonb_build_object('is_archived',false,'affiliate_status_raw',v_old.affiliate_status_raw),
    jsonb_build_object('is_archived',true,'archived_at',v_new.archived_at,'archive_previous_status_raw',v_new.archive_previous_status_raw),
    array['is_archived','archived_at','archived_by_auth_user_id','archive_reason','archive_previous_status_raw'],v_reason);
  return public.get_admin_affiliate_workbench(p_affiliate_id);
end $function$

CREATE OR REPLACE FUNCTION public.assert_document_requirement_scope(p_scope_type text, p_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_type text:=upper(btrim(coalesce(p_scope_type,'')));v_key text:=btrim(coalesce(p_scope_key,''));v_row jsonb;
begin
  if auth.uid() is null and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;
  if v_type='PROGRAM' and v_key='prestamo' then
    return jsonb_build_object('scope_type',v_type,'scope_key',v_key,'label','Suti Prestamo','parent_scope_type',null,'parent_scope_key',null);
  elsif v_type='PROGRAM' then
    select jsonb_build_object('scope_type',v_type,'scope_key',i.id::text,'label',i.name,'parent_scope_type',null,'parent_scope_key',null)
      into v_row from public.program_catalog_items i where i.id::text=v_key and i.enabled;
  elsif v_type='MEMBERSHIP' then
    select jsonb_build_object('scope_type',v_type,'scope_key',m.id::text,'label',m.company_raw||' - '||m.concept,'parent_scope_type',null,'parent_scope_key',null)
      into v_row from public.membership_offerings m where m.id::text=v_key and m.enabled;
  elsif v_type='COMPANY' then
    select jsonb_build_object('scope_type',v_type,'scope_key',c.id::text,'label',c.display_name,'parent_scope_type',null,'parent_scope_key',null)
      into v_row from public.companies c where c.id::text=v_key and c.enabled;
  elsif v_type='PRODUCT' then
    select jsonb_build_object('scope_type',v_type,'scope_key',p.id::text,'label',p.name,'parent_scope_type','COMPANY','parent_scope_key',p.company_id::text)
      into v_row from public.marketplace_products p join public.companies c on c.id=p.company_id and c.enabled
      where p.id::text=v_key and p.enabled;
  elsif v_type='SERVICE' then
    raise exception 'DOCUMENT_SCOPE_NOT_AVAILABLE' using errcode='22023';
  else
    raise exception 'INVALID_DOCUMENT_SCOPE' using errcode='22023';
  end if;
  if v_row is null then raise exception 'DOCUMENT_SCOPE_NOT_AVAILABLE' using errcode='22023'; end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.assign_admin_role(p_auth_user_id uuid, p_role_id uuid, p_enabled boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();v_id uuid;v_permissions text[];v_before jsonb;v_after jsonb;
begin
  if v_actor is null or not public.has_admin_permission('authorization.write') then
    raise exception 'AUTHORIZATION_DENIED' using errcode='42501';
  end if;
  if p_auth_user_id=v_actor then raise exception 'SELF_ASSIGNMENT_DENIED' using errcode='42501'; end if;
  if not exists(select 1 from auth.users where id=p_auth_user_id and email_confirmed_at is not null) then
    raise exception 'CONFIRMED_AUTH_USER_NOT_FOUND' using errcode='P0001';
  end if;
  if not exists(select 1 from public.admin_roles where id=p_role_id and enabled) then
    raise exception 'ROLE_NOT_FOUND' using errcode='P0001';
  end if;
  select to_jsonb(a) into v_before from public.admin_assignments a where a.auth_user_id=p_auth_user_id for update;
  if coalesce((v_before->>'protected_assignment')::boolean,false) and
     (not p_enabled or (v_before->>'role_id')::uuid is distinct from p_role_id) then
    raise exception 'PROTECTED_SUPERADMIN' using errcode='42501';
  end if;
  select array_agg(permission order by permission) into v_permissions
  from public.admin_role_permissions where role_id=p_role_id;
  insert into public.admin_assignments(
    auth_user_id,role,role_id,permissions,enabled,assigned_at,assigned_by_auth_user_id,
    revoked_at,revoked_by_auth_user_id,protected_assignment
  ) values(
    p_auth_user_id,'visual_admin',p_role_id,coalesce(v_permissions,'{}'),p_enabled,now(),v_actor,
    case when p_enabled then null else now() end,case when p_enabled then null else v_actor end,false
  )
  on conflict(auth_user_id) do update set
    role_id=excluded.role_id,permissions=excluded.permissions,enabled=excluded.enabled,
    assigned_at=case when excluded.enabled then now() else admin_assignments.assigned_at end,
    assigned_by_auth_user_id=case when excluded.enabled then v_actor else admin_assignments.assigned_by_auth_user_id end,
    revoked_at=excluded.revoked_at,revoked_by_auth_user_id=excluded.revoked_by_auth_user_id,updated_at=now()
  returning id into v_id;
  select to_jsonb(a) into v_after from public.admin_assignments a where a.id=v_id;
  if not exists(
    select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id
    where a.enabled and r.code='principal_admin'
  ) then raise exception 'LAST_PRINCIPAL_ADMIN_REQUIRED' using errcode='23514'; end if;
  if not p_enabled or not ('affiliates.impersonate'=any(coalesce(v_permissions,'{}'))) then
    with closed as (
      update public.impersonation_sessions s set ended_at=now(),ended_by_auth_user_id=v_actor
      where s.actor_real_auth_user_id=p_auth_user_id and s.ended_at is null returning s.*
    ) insert into public.identity_audit_log(actor_real_auth_user_id,usuario_contexto_affiliate_id,action,result,details)
      select v_actor,c.usuario_contexto_affiliate_id,'IMPERSONATION_STOPPED','SUCCESS',jsonb_build_object(
        'session_id',c.id,'reason',c.reason,'automatic',true,'cause','ADMIN_ASSIGNMENT_REVOKED','session_actor_auth_user_id',c.actor_real_auth_user_id)
      from closed c;
  end if;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'admin_assignments',case when p_enabled then 'UPSERT' else 'REVOKE' end,v_id::text,'SUCCESS',
    jsonb_build_object('subject_auth_user_id',p_auth_user_id,'before',v_before,'after',v_after,'assigned_by_auth_user_id',v_actor));
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.audit_admin_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data jsonb; target text; ctx public.impersonation_sessions%rowtype;
begin
  if (select auth.uid()) is null then return coalesce(new, old); end if;
  row_data := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target := coalesce(row_data->>'id', row_data->>'company_id', row_data->>'asset_id', row_data->>'asset_key');
  select * into ctx from public.impersonation_sessions where actor_real_auth_user_id=(select auth.uid()) and ended_at is null and expires_at>now() limit 1;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,usuario_contexto_affiliate_id,impersonation_session_id,reason)
  values ((select auth.uid()),tg_table_name,tg_op,target,'SUCCESS',ctx.usuario_contexto_affiliate_id,ctx.id,ctx.reason);
  return coalesce(new, old);
end;
$function$

