CREATE OR REPLACE FUNCTION public.audit_section_row_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
