CREATE OR REPLACE FUNCTION public.capture_savings_process_change_from_affiliate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_process text;v_new_process text;v_participant record;v_enrollment record;v_plan jsonb;
begin
  v_old_process:=case old.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then 'PROCESS_3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then 'PROCESS_1' when 'EVENTUALES' then 'PROCESS_1' when 'BASE' then 'PROCESS_1' else null end;
  v_new_process:=case new.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then 'PROCESS_3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then 'PROCESS_1' when 'EVENTUALES' then 'PROCESS_1' when 'BASE' then 'PROCESS_1' else null end;
  if v_new_process is null or v_new_process is not distinct from v_old_process then return new; end if;
  select * into v_participant from public.savings_participants where affiliate_id=new.id;
  if not found then return new; end if;
  select * into v_enrollment from public.savings_enrollments
    where participant_id=v_participant.id and status in ('ACTIVE','TERMINATION_PENDING')
    order by sequence_number desc limit 1;
  if found then
    select to_jsonb(p) into v_plan from public.savings_contribution_plans p
      where p.enrollment_id=v_enrollment.id order by p.effective_from desc limit 1;
  end if;
  insert into public.savings_process_change_events(
    participant_id,affiliate_id,legacy_folio,old_process,new_process,status,current_plan_snapshot,reason,actor_real_auth_user_id
  ) values(
    v_participant.id,new.id,v_participant.legacy_folio,coalesce(v_participant.current_process,v_old_process),v_new_process,
    case when v_enrollment.id is null then 'NO_ACTIVE_ENROLLMENT' else 'SAVINGS_PROCESS_CHANGE_REVIEW_REQUIRED' end,
    coalesce(v_plan,'{}'::jsonb),'Cambio detectado desde Admin Afiliados',auth.uid()
  );
  update public.savings_participants set current_process=v_new_process,process_source='SHADOW' where id=v_participant.id;
  insert into public.savings_audit_events(actor_real_auth_user_id,usuario_contexto_affiliate_id,participant_id,resource,action,target_id,before_data,after_data,reason)
  values(auth.uid(),new.id,v_participant.id,'affiliates.financial_employee_category_code','PROCESS_CHANGE_DETECTED',new.id::text,
    jsonb_build_object('category',old.financial_employee_category_code,'process',coalesce(v_participant.current_process,v_old_process)),
    jsonb_build_object('category',new.financial_employee_category_code,'process',v_new_process),'Plan hist�rico sin modificar; revisi�n futura requerida');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.change_admin_affiliate_status(p_affiliate_id uuid, p_expected_updated_at timestamp with time zone, p_new_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.affiliates%rowtype;v_new public.affiliates%rowtype;v_status text:=btrim(coalesce(p_new_status,''));v_reason text:=btrim(coalesce(p_reason,''));
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'AFFILIATE_REASON_REQUIRED' using errcode='22023'; end if;
  if v_status='' or not exists(select 1 from public.affiliates where affiliate_status_raw=v_status) then raise exception 'AFFILIATE_STATUS_INVALID' using errcode='22023'; end if;
  select * into v_old from public.affiliates where id=p_affiliate_id for update;
  if v_old.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.updated_at is distinct from p_expected_updated_at then raise exception 'AFFILIATE_VERSION_CONFLICT' using errcode='PT409'; end if;
  if v_old.affiliate_status_raw is not distinct from v_status then raise exception 'AFFILIATE_STATUS_NO_CHANGE' using errcode='22023'; end if;
  update public.affiliates set affiliate_status_raw=v_status where id=p_affiliate_id returning * into v_new;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(p_affiliate_id,auth.uid(),'STATUS_CHANGE',jsonb_build_object('affiliate_status_raw',v_old.affiliate_status_raw),jsonb_build_object('affiliate_status_raw',v_new.affiliate_status_raw),array['affiliate_status_raw'],v_reason);
  return public.get_admin_affiliate_workbench(p_affiliate_id);
end $function$

CREATE OR REPLACE FUNCTION public.claim_affiliate_identity()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  principal uuid := (select auth.uid());
  principal_email text;
  confirmed timestamptz;
  candidate public.affiliates%rowtype;
  matches integer;
  updated_rows integer;
begin
  if principal is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'P0001';
  end if;

  select lower(btrim(u.email)), u.email_confirmed_at
    into principal_email, confirmed
  from auth.users u
  where u.id = principal;

  if principal_email is null or principal_email = '' or confirmed is null then
    raise exception 'VERIFIED_EMAIL_REQUIRED' using errcode = 'P0001';
  end if;

  select a.* into candidate
  from public.affiliates a
  where a.auth_user_id = principal
    and public.has_certified_affiliate_auth_link(principal, a.id, principal_email);

  if candidate.id is not null then
    if candidate.is_archived then
      raise exception 'AFFILIATE_ARCHIVED' using errcode = '42501';
    end if;
    return candidate.id;
  end if;

  select count(*) into matches
  from public.affiliates a
  where a.historical_email_normalized = principal_email;

  if matches <> 1 then
    raise exception 'AFFILIATE_IDENTITY_AMBIGUOUS' using errcode = '42501';
  end if;

  select * into candidate
  from public.affiliates a
  where a.historical_email_normalized = principal_email
  for update;

  if candidate.is_archived then
    raise exception 'AFFILIATE_ARCHIVED' using errcode = '42501';
  end if;
  if candidate.auth_eligibility <> 'eligible' then
    raise exception 'AFFILIATE_NOT_ELIGIBLE' using errcode = '42501';
  end if;
  if exists(
    select 1
    from public.affiliates a
    where a.auth_user_id = principal
      and a.id <> candidate.id
  ) then
    raise exception 'AUTH_IDENTITY_LINK_CONFLICT' using errcode = '42501';
  end if;
  if candidate.auth_user_id is not null and candidate.auth_user_id <> principal then
    raise exception 'AFFILIATE_ALREADY_LINKED' using errcode = '42501';
  end if;

  update public.affiliates
  set auth_user_id = principal,
      updated_at = now()
  where id = candidate.id
    and not is_archived
    and auth_eligibility = 'eligible'
    and historical_email_normalized = principal_email
    and (auth_user_id is null or auth_user_id = principal);
  get diagnostics updated_rows = row_count;

  if updated_rows <> 1 then
    raise exception 'AUTH_IDENTITY_LINK_CONFLICT' using errcode = '42501';
  end if;

  insert into public.identity_audit_log(
    actor_real_auth_user_id,
    usuario_contexto_affiliate_id,
    action,
    result
  ) values (
    principal,
    candidate.id,
    'AFFILIATE_CLAIMED',
    'SUCCESS'
  );

  return candidate.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_financial_request_export(p_request_id uuid, p_payload_sha256 text, p_google_row integer, p_legacy_reference text, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_request public.program_requests%rowtype; v_audit public.financial_request_export_audit%rowtype;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  select * into v_request from public.program_requests where id=p_request_id for update;
  select * into v_audit from public.financial_request_export_audit where program_request_id=p_request_id for update;
  if v_request.financial_processing_status='handed_off' and v_audit.export_status='exported' then
    if v_audit.payload_sha256<>p_payload_sha256 then raise exception 'EXPORT_PAYLOAD_HASH_MISMATCH' using errcode='22023'; end if;
    return jsonb_build_object('idempotent',true,'google_row',v_audit.google_row,'legacy_reference',v_audit.legacy_reference);
  end if;
  if v_request.status<>'approved' or v_request.financial_processing_status<>'in_progress' or v_audit.export_status<>'in_progress'
     or v_audit.payload_sha256<>p_payload_sha256 then raise exception 'EXPORT_COMPLETION_STATE_INVALID' using errcode='P0001'; end if;
  if p_google_row<=1 or btrim(coalesce(p_legacy_reference,''))<>('Historial de solicitudes!A'||p_google_row::text)
     or p_actor is null then raise exception 'EXPORT_RESULT_INVALID' using errcode='22023'; end if;
  update public.program_requests set financial_processing_status='handed_off',legacy_reference=p_legacy_reference,updated_at=now() where id=p_request_id;
  update public.financial_request_export_audit set export_status='exported',exported_at=now(),google_row=p_google_row,
    legacy_reference=p_legacy_reference,error_code=null,error_message=null,last_actor_auth_user_id=p_actor,updated_at=now()
  where program_request_id=p_request_id;
  return jsonb_build_object('idempotent',false,'google_row',p_google_row,'legacy_reference',p_legacy_reference);
end $function$

CREATE OR REPLACE FUNCTION public.create_admin_affiliate(p_values jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.affiliates%rowtype;v_duplicates jsonb;v_email text;v_eligibility text;v_reason text:=btrim(coalesce(p_reason,''));
  v_status text:=nullif(btrim(p_values->>'affiliate_status_raw'),'');
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if jsonb_typeof(p_values)<>'object' then raise exception 'AFFILIATE_VALUES_REQUIRED' using errcode='22023'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'AFFILIATE_REASON_REQUIRED' using errcode='22023'; end if;
  if length(btrim(coalesce(p_values->>'numero_control',''))) not between 1 and 80 then raise exception 'AFFILIATE_CONTROL_REQUIRED' using errcode='22023'; end if;
  if length(btrim(coalesce(p_values->>'full_name',''))) not between 3 and 240 then raise exception 'AFFILIATE_NAME_REQUIRED' using errcode='22023'; end if;
  if v_status is null or not exists(select 1 from public.affiliates where affiliate_status_raw=v_status) then raise exception 'AFFILIATE_STATUS_INVALID' using errcode='22023'; end if;
  if nullif(btrim(p_values->>'financial_union_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='union' and code=p_values->>'financial_union_code' and enabled) then raise exception 'AFFILIATE_UNION_INVALID' using errcode='22023'; end if;
  if nullif(btrim(p_values->>'financial_employee_category_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='employment_category' and code=p_values->>'financial_employee_category_code' and enabled) then raise exception 'AFFILIATE_CATEGORY_INVALID' using errcode='22023'; end if;
  v_duplicates:=public.find_admin_affiliate_duplicates(p_values,null);
  if exists(select 1 from jsonb_array_elements(v_duplicates) d(value) where (d.value->'matches') ?| array['numero_control','rfc','curp']) then
    raise exception 'AFFILIATE_DUPLICATE_REVIEW_REQUIRED' using errcode='23505';
  end if;
  v_email:=nullif(lower(btrim(p_values->>'historical_email_raw')),'');
  v_eligibility:=case when v_email is null then 'missing_email' when v_email!~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then 'invalid_email'
    when exists(select 1 from public.affiliates where historical_email_normalized=v_email) then 'duplicate_email' else 'eligible' end;
  insert into public.affiliates(
    numero_control,full_name,display_name,affiliate_status_raw,historical_email_raw,historical_email_normalized,phone_raw,address_raw,
    birth_date_raw,gender_raw,marital_status_raw,children_count_raw,rfc_raw,curp_raw,unit_raw,city_raw,employment_position_raw,
    employment_entry_date_raw,occupation_raw,institute_entry_date_raw,employment_area_raw,employment_level_raw,pension_raw,subdirectorate_raw,
    union_enrollment_date_raw,capture_date_raw,affiliation_raw,union_position_raw,termination_date_raw,financial_union_code,
    financial_employee_category_code,financial_employee_type,financial_affiliation_status,financial_employment_status,
    auth_eligibility,auth_ineligibility_reason,record_origin,source_row_ordinal,source_file_hash
  ) values(
    btrim(p_values->>'numero_control'),btrim(p_values->>'full_name'),nullif(btrim(p_values->>'display_name'),''),v_status,
    nullif(btrim(p_values->>'historical_email_raw'),''),v_email,nullif(btrim(p_values->>'phone_raw'),''),nullif(btrim(p_values->>'address_raw'),''),
    nullif(btrim(p_values->>'birth_date_raw'),''),nullif(btrim(p_values->>'gender_raw'),''),nullif(btrim(p_values->>'marital_status_raw'),''),nullif(btrim(p_values->>'children_count_raw'),''),
    nullif(upper(btrim(p_values->>'rfc_raw')),''),nullif(upper(btrim(p_values->>'curp_raw')),''),nullif(btrim(p_values->>'unit_raw'),''),nullif(btrim(p_values->>'city_raw'),''),
    nullif(btrim(p_values->>'employment_position_raw'),''),nullif(btrim(p_values->>'employment_entry_date_raw'),''),nullif(btrim(p_values->>'occupation_raw'),''),nullif(btrim(p_values->>'institute_entry_date_raw'),''),
    nullif(btrim(p_values->>'employment_area_raw'),''),nullif(btrim(p_values->>'employment_level_raw'),''),nullif(btrim(p_values->>'pension_raw'),''),nullif(btrim(p_values->>'subdirectorate_raw'),''),
    nullif(btrim(p_values->>'union_enrollment_date_raw'),''),nullif(btrim(p_values->>'capture_date_raw'),''),nullif(btrim(p_values->>'affiliation_raw'),''),nullif(btrim(p_values->>'union_position_raw'),''),
    nullif(btrim(p_values->>'termination_date_raw'),''),nullif(btrim(p_values->>'financial_union_code'),''),nullif(btrim(p_values->>'financial_employee_category_code'),''),
    nullif(btrim(p_values->>'financial_employee_type'),''),nullif(btrim(p_values->>'financial_affiliation_status'),''),nullif(btrim(p_values->>'financial_employment_status'),''),
    v_eligibility,case when v_eligibility='eligible' then null else v_eligibility end,'ADMIN_AFFILIATES',null,null
  ) returning * into v_row;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(v_row.id,auth.uid(),'CREATE',null,to_jsonb(v_row)-array['auth_user_id','historical_email_normalized','source_file_hash']::text[],
    array['numero_control','full_name','affiliate_status_raw'],v_reason);
  return public.get_admin_affiliate_workbench(v_row.id);
end $function$

CREATE OR REPLACE FUNCTION public.create_first_cirugias_program_catalog_item(p_payload jsonb, p_asset_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=(select auth.uid());
  v_after public.program_catalog_items%rowtype;
  v_id uuid;
  v_program text:=btrim(coalesce(p_payload->>'program_key',''));
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_description text:=nullif(btrim(coalesce(p_payload->>'description','')),'');
  v_category text:=nullif(btrim(coalesce(p_payload->>'category_raw','')),'');
  v_price numeric;v_quote boolean;v_mode text;v_sold boolean;v_enabled boolean;v_sort integer;
  v_link jsonb;v_link_id uuid;v_public_asset_id uuid;v_kept uuid[]:='{}'::uuid[];v_position integer:=0;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then
    raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object'
     or p_asset_links is null or jsonb_typeof(p_asset_links)<>'array' then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_payload) k
    where k not in('program_key','name','description','category_raw','price_cash','requires_quote','commercial_mode','sold','enabled','sort_order')
  ) then
    raise exception 'PROGRAM_CATALOG_FIELD_NOT_EDITABLE' using errcode='22023';
  end if;
  begin
    v_price:=nullif(p_payload->>'price_cash','')::numeric;
    v_quote:=(p_payload->>'requires_quote')::boolean;
    v_mode:=coalesce(nullif(btrim(coalesce(p_payload->>'commercial_mode','')),''),case when v_quote then 'PAYROLL_QUOTE' else 'PAYROLL_FIXED' end);
    v_sold:=case when p_payload ? 'sold' then (p_payload->>'sold')::boolean else false end;
    v_enabled:=(p_payload->>'enabled')::boolean;
    v_sort:=(p_payload->>'sort_order')::integer;
  exception when others then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end;
  if v_quote is null or v_enabled is null or v_sold is null or v_sort is null then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_program<>'cirugias' then raise exception 'PROGRAM_CATALOG_PROGRAM_INVALID' using errcode='22023'; end if;
  if length(v_name) not between 2 and 180 then raise exception 'PROGRAM_CATALOG_NAME_INVALID' using errcode='22023'; end if;
  if length(coalesce(v_description,''))>12000 then raise exception 'PROGRAM_CATALOG_DESCRIPTION_TOO_LONG' using errcode='22023'; end if;
  if length(coalesce(v_category,''))>240 then raise exception 'PROGRAM_CATALOG_CATEGORY_TOO_LONG' using errcode='22023'; end if;
  if v_sort not between 1 and 10000 then raise exception 'PROGRAM_CATALOG_ORDER_INVALID' using errcode='22023'; end if;
  if v_price<0 then raise exception 'PROGRAM_CATALOG_PRICE_INVALID' using errcode='22023'; end if;
  if v_mode not in('PAYROLL_FIXED','PAYROLL_QUOTE','DIRECT_CONTACT') then raise exception 'PROGRAM_CATALOG_MODE_INVALID' using errcode='22023'; end if;
  if (v_mode='PAYROLL_QUOTE')<>v_quote then raise exception 'PROGRAM_CATALOG_MODE_QUOTE_MISMATCH' using errcode='22023'; end if;
  if v_mode='PAYROLL_FIXED' and (v_price is null or v_price<=0) then raise exception 'PROGRAM_CATALOG_PRICE_REQUIRED' using errcode='22023'; end if;
  if jsonb_array_length(p_asset_links)>8 then raise exception 'PROGRAM_CATALOG_IMAGE_LIMIT_EXCEEDED' using errcode='22023'; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('program_catalog_items:cirugias',0));
  if exists(select 1 from public.program_catalog_items where program_key='cirugias') then
    raise exception 'CIRUGIAS_PROGRAM_ALREADY_BOOTSTRAPPED' using errcode='P0001';
  end if;
  insert into public.program_catalog_items(
    program_key,name,description,category_raw,price_cash,requires_quote,commercial_mode,sold,sold_at,sold_by,
    request_mode,legacy_boundary,enabled,sort_order,record_origin,source_sheet,source_row_ordinal,source_snapshot_hash,source_payload
  ) values(
    'cirugias',v_name,v_description,v_category,v_price,v_quote,v_mode,v_sold,
    case when v_sold then now() else null end,case when v_sold then v_actor else null end,
    'supabase',false,v_enabled,v_sort,'ADMIN_PROGRAM_CATALOG',null,null,null,'{}'::jsonb
  ) returning * into v_after;
  v_id:=v_after.id;
  for v_link in select value from jsonb_array_elements(p_asset_links) loop
    v_position:=v_position+1;
    begin
      v_link_id:=nullif(v_link->>'link_id','')::uuid;
      v_public_asset_id:=nullif(v_link->>'public_asset_id','')::uuid;
    exception when others then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end;
    if v_link_id is not null or v_public_asset_id is null then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end if;
    if not exists(
      select 1 from public.app_assets
      where id=v_public_asset_id and status='READY' and storage_bucket='app-assets'
        and storage_path like 'program-products/%'
    ) then
      raise exception 'PROGRAM_CATALOG_PUBLIC_ASSET_INVALID' using errcode='22023';
    end if;
    v_link_id:=extensions.gen_random_uuid();
    insert into public.program_catalog_item_assets(
      id,item_id,public_asset_id,private_asset_id,role,sort_order,source_column,source_column_letter,enabled
    ) values(
      v_link_id,v_id,v_public_asset_id,null,case when v_position=1 then 'cover' else 'gallery' end,
      v_position,'ADMIN_UPLOAD','ADMIN_'||replace(v_link_id::text,'-',''),true
    );
    if v_link_id=any(v_kept) then raise exception 'PROGRAM_CATALOG_ASSET_DUPLICATE' using errcode='22023'; end if;
    v_kept:=array_append(v_kept,v_link_id);
  end loop;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'program_catalog_items','INSERT',v_id::text,'SUCCESS',jsonb_build_object(
    'program_key','cirugias','before',null,
    'after',jsonb_build_object(
      'name',v_after.name,'price_cash',v_after.price_cash,'requires_quote',v_after.requires_quote,
      'commercial_mode',v_after.commercial_mode,'sold',v_after.sold,'sold_at',v_after.sold_at,
      'sold_by',v_after.sold_by,'enabled',v_after.enabled,'sort_order',v_after.sort_order
    ),'asset_count',v_position,'asset_limit',8,'bootstrap',true,'delta_aware',true
  ));
  return (to_jsonb(v_after)-'source_payload'-'sold_by');
end $function$

CREATE OR REPLACE FUNCTION public.create_marketplace_benefit_request(p_product_id uuid, p_quantity integer, p_message text, p_signature_data text, p_terms_accepted boolean)
 RETURNS marketplace_benefit_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_product public.marketplace_products%rowtype;v_affiliate uuid;v_row public.marketplace_benefit_requests%rowtype;
begin
  v_affiliate:=public.get_effective_affiliate_id();if v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='P0001';end if;
  if not coalesce(p_terms_accepted,false) or nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  select * into v_product from public.marketplace_products where id=p_product_id and enabled and not requires_quote and exists(select 1 from public.companies c where c.id=company_id and c.enabled);if v_product.id is null then raise exception 'PRODUCT_NOT_REQUESTABLE' using errcode='P0001';end if;
  insert into public.marketplace_benefit_requests(actor_real_auth_user_id,affiliate_id,product_id,company_id,quantity,message,signature_data,terms_accepted)
  values((select auth.uid()),v_affiliate,v_product.id,v_product.company_id,greatest(1,least(coalesce(p_quantity,1),999)),left(coalesce(p_message,''),2000),p_signature_data,true) returning * into v_row;return v_row;
end $function$

