  if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='22023'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then
    raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo' and membership_offering_id is null and published) then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023';
  end if;
  if p_financial_submission_snapshot is null
     or jsonb_typeof(p_financial_submission_snapshot)<>'object'
     or not(p_financial_submission_snapshot ?& array[
       'affiliate_id','actor_real_auth_user_id','profile_version','profile_fingerprint',
       'criteria_source_fingerprint','term_policy_fingerprint','calculation_contract_version',
       'criterion_identity','financialResult','confirmed_at','deposit_selection'
     ])
     or jsonb_typeof(p_financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(p_financial_submission_snapshot->'deposit_selection')<>'object'
     or nullif(btrim(coalesce(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id','')),'') is not null
     or p_financial_submission_snapshot->>'affiliate_id'<>p_affiliate_id::text
     or p_financial_submission_snapshot->>'actor_real_auth_user_id'<>p_actor_real_auth_user_id::text
     or coalesce(p_financial_submission_snapshot->>'impersonation_session_id','')<>coalesce(p_impersonation_session_id::text,'')
     or (p_financial_submission_snapshot->>'profile_version')::integer<>p_expected_profile_version
     or (p_financial_submission_snapshot->'financialResult'->>'amount')::numeric<>p_amount
     or (p_financial_submission_snapshot->'financialResult'->>'paymentCount')::integer<>p_term then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  v_phone:=p_financial_submission_snapshot->'deposit_selection'->>'notification_phone';
  if coalesce(v_phone,'') !~ '^[0-9]{10}$' then raise exception 'INVALID_NOTIFICATION_PHONE' using errcode='22023'; end if;

  v_submission:=(p_financial_submission_snapshot-'deposit_selection') || jsonb_build_object('deposit',jsonb_build_object(
    'bank_account_id',null,'bank_name',null,'masked_card',null,'masked_clabe',null,
    'masked_phone','••• ••• '||right(v_phone,4)
  ));

  select count(*) into v_missing from public.program_document_requirements r
   where r.program_id='prestamo' and r.membership_offering_id is null and r.enabled and r.required and not exists(
     select 1 from public.affiliate_documents d where d.id=any(coalesce(p_document_ids,array[]::uuid[]))
       and d.affiliate_id=p_affiliate_id and d.document_type_id=r.document_type_id
       and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;

  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;

  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,'prestamo',v_item.id,'quote','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','financial_confirmation','SUPABASE_REVALIDATED','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,p_amount,p_term,btrim(p_term_semantics),v_submission
  ) returning * into v_row;

  insert into public.loan_request_deposit_snapshots(request_id,affiliate_id,notification_phone)
  values(v_row.id,p_affiliate_id,v_phone);
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','LOAN_DEPOSIT_CONFIRMED',v_row.id,
    jsonb_build_object('has_bank_account',false,'phone_last4',right(v_phone,4)));

  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_program_product_payment_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_down_payment numeric, p_term integer, p_expected_profile_version integer, p_schedule_anchor_date date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_quote public.program_requests%rowtype;
  v_row public.program_requests%rowtype;
  v_policy public.loan_term_policy%rowtype;
  v_rules jsonb;
  v_rule jsonb;
  v_rule_count integer;
  v_price numeric(14,2);
  v_amount numeric(14,2);
  v_source text;
  v_result jsonb;
  v_schedule jsonb;
  v_process text;
  v_period text;
  v_union_label text;
  v_category_label text;
  v_missing integer;
  v_snapshot jsonb;
  v_business_date date:=(now() at time zone 'America/Hermosillo')::date;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled
         where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items where id=p_program_item_id and enabled and request_mode='supabase' for share;
  if v_item.id is null or v_item.program_key='prestamo' then raise exception 'PROGRAM_PRODUCT_NOT_FINANCEABLE' using errcode='22023'; end if;
  if v_item.requires_quote then
    select * into v_quote from public.program_requests
    where affiliate_id=p_affiliate_id and program_item_id=v_item.id and request_type='quote' and status='approved'
      and quoted_amount>0 and (valid_until is null or valid_until>=v_business_date)
    order by responded_at desc nulls last,created_at desc,id desc limit 1 for share;
    if v_quote.id is null then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_quote.quoted_amount;v_source:='APPROVED_QUOTE';
  else
    if v_item.price_cash is null or v_item.price_cash<=0 then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_item.price_cash;v_source:='PRICE_CASH';
  end if;
  if p_down_payment is null or p_down_payment<0 or p_down_payment>=v_price then raise exception 'DOWN_PAYMENT_OUT_OF_RANGE' using errcode='22023'; end if;
  v_amount:=round(v_price-p_down_payment,2);
  select * into v_policy from public.loan_term_policy where id='primary' and enabled;
  if v_policy.id is null then raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001'; end if;
  select u.label,c.label into v_union_label,v_category_label
  from public.affiliates a
  left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
  left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
  where a.id=v_affiliate.id;
  if v_union_label is null or v_category_label is null then raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001'; end if;
  v_rules:=public.get_financial_runtime_rules();
  select count(*) into v_rule_count
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end;
  if v_rule_count<>1 then raise exception 'CAJA_CHICA_RULE_NOT_ELIGIBLE' using errcode='P0001'; end if;
  select value into v_rule
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end
  limit 1;
  v_rule:=v_rule||jsonb_build_object('status','AVAILABLE');
  v_result:=public.resolve_suti_loan_quote_contract(
    jsonb_build_array(v_rule),v_union_label,v_category_label,
    v_rule->>'id',v_amount,p_term,jsonb_build_object(
      'source','SUPABASE_LOAN_TERM_POLICY','standardTerms',v_policy.standard_terms,
      'customMinTerm',v_policy.custom_min_term,'customStep',v_policy.custom_step,
      'decisionReference',v_policy.decision_reference
    )
  );
  v_process:=case v_affiliate.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then '3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then '1' when 'EVENTUALES' then '1' when 'BASE' then '1'
    else null end;
  if v_process is null then raise exception 'PAYROLL_PROCESS_UNRESOLVED' using errcode='P0001'; end if;
  v_period:=case when v_process='JUB' then 'mensual' else 'quincenal' end;
  v_result:=(v_result||jsonb_build_object('paymentPeriod',v_period,'ratePeriod',v_period,'source','SUPABASE_FINANCIAL_CRITERIA'));
  if p_schedule_anchor_date is distinct from v_business_date then raise exception 'SCHEDULE_ANCHOR_CHANGED' using errcode='PT409'; end if;
  v_schedule:=public.generate_program_product_payment_schedule(
    p_schedule_anchor_date,v_process,(v_result->>'paymentCount')::integer,
    (v_result->>'total')::numeric,(v_result->>'paymentPerPeriod')::numeric
  );
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo'
    and membership_offering_id is null and published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing
  from public.resolve_effective_document_requirements('PROGRAM','prestamo') requirement
  where requirement.required and not exists(
    select 1 from public.affiliate_documents d
    left join public.affiliate_files af on af.id=d.affiliate_file_id
    join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id) and pa.status='READY'
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
      and d.document_type_id=requirement.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
      and not exists(select 1 from public.affiliate_documents newer where newer.affiliate_id=d.affiliate_id
        and newer.document_type_id=d.document_type_id and (newer.created_at,newer.id)>(d.created_at,d.id))
  );
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  v_snapshot:=jsonb_build_object(
    'contract_version','PROGRAM_PRODUCT_PAYMENT_V1','calculation_contract_version','SUTI_LOAN_QUOTE_V1',
    'calendar_contract_version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','affiliate_id',p_affiliate_id,
    'actor_real_auth_user_id',p_actor_real_auth_user_id,'impersonation_session_id',p_impersonation_session_id,
    'profile_version',v_affiliate.financial_profile_version,'product',jsonb_build_object(
      'program_item_id',v_item.id,'program_key',v_item.program_key,'name',v_item.name
    ),'authorized_price',v_price,'price_source',v_source,'quote_request_id',v_quote.id,
    'down_payment',round(p_down_payment,2),'financed_amount',v_amount,'fund_program_id','caja',
    'fund_rule_id',v_rule->>'rule_id','criterion_identity',v_rule->>'criterion_identity',
    'financial_authority','SUPABASE','financial_rules_source_hash',v_rule->>'source_snapshot_hash',
    'financialResult',v_result,'payment_schedule',v_schedule,'terms_version_id',p_terms_version_id,
    'confirmed_at',now()
  );
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_item_id<>p_program_item_id
       or v_row.requested_amount<>v_amount or v_row.requested_term<>p_term
       or (v_row.financial_submission_snapshot->>'down_payment')::numeric<>round(p_down_payment,2)
       or v_row.financial_submission_snapshot->>'price_source'<>v_source
       or coalesce(v_row.financial_submission_snapshot->>'quote_request_id','')<>coalesce(v_quote.id::text,'') then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,v_item.program_key,v_item.id,'benefit','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','flow','PROGRAM_PRODUCT_PAYMENT_V1','price_source',v_source,
      'quote_request_id',v_quote.id,'fund_program_id','caja','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,v_amount,p_term,v_period,v_snapshot
  ) returning * into v_row;
  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_CONFIRMED',v_row.id,
    jsonb_build_object('program_item_id',v_item.id,'price_source',v_source,'quote_request_id',v_quote.id,
      'payment_count',p_term,'payment_period',v_period,'assisted',v_ctx.id is not null));
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null and v_row.program_item_id=p_program_item_id and v_row.requested_amount=v_amount
     and v_row.requested_term=p_term and (v_row.financial_submission_snapshot->>'down_payment')::numeric=round(p_down_payment,2) then
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.delete_admin_role(p_role_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
  if not public.has_admin_permission('authorization.write') then raise exception 'AUTHORIZATION_DENIED'; end if;
  if exists(select 1 from public.admin_roles where id=p_role_id and system_role) then raise exception 'SYSTEM_ROLE_IMMUTABLE'; end if;
  if exists(select 1 from public.admin_assignments where role_id=p_role_id) then raise exception 'ROLE_IN_USE'; end if;
  delete from public.admin_roles where id=p_role_id;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result) values(auth.uid(),'admin_roles','DELETE',p_role_id::text,'SUCCESS');
end $function$

CREATE OR REPLACE FUNCTION public.delete_affiliate_bank_account(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_affiliate uuid;v_deleted uuid; begin
  v_affiliate:=public.get_effective_affiliate_id();if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  delete from public.affiliate_bank_accounts where id=p_id and affiliate_id=v_affiliate returning id into v_deleted;
  if v_deleted is null then raise exception 'BANK_ACCOUNT_NOT_FOUND' using errcode='P0001'; end if;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id) values(auth.uid(),v_affiliate,'affiliate_bank_accounts','BANK_ACCOUNT_DELETED',v_deleted);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.discard_unlinked_program_catalog_asset(p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=(select auth.uid()); v_asset public.app_assets%rowtype;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501'; end if;
  select * into v_asset from public.app_assets where id=p_asset_id for update;
  if v_asset.id is null or v_asset.storage_bucket<>'app-assets' or v_asset.storage_path not like 'program-products/'||v_actor::text||'/%' then
    raise exception 'PROGRAM_CATALOG_ASSET_NOT_OWNED' using errcode='42501';
  end if;
  if exists(select 1 from public.program_catalog_item_assets where public_asset_id=p_asset_id and enabled) then
    raise exception 'PROGRAM_CATALOG_ASSET_IN_USE' using errcode='P0001';
  end if;
  delete from public.program_catalog_item_assets
  where public_asset_id=p_asset_id and not enabled and source_column='ADMIN_UPLOAD';
  delete from public.app_assets where id=p_asset_id;
  return jsonb_build_object('bucket',v_asset.storage_bucket,'path',v_asset.storage_path);
end $function$

CREATE OR REPLACE FUNCTION public.enforce_financial_rule_program_fund()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if not exists(select 1 from public.financial_funds f where f.id=new.fund_id and f.program_id=new.program_id) then
    raise exception 'FINANCIAL_FUND_PROGRAM_MISMATCH' using errcode='23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_news_section_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actions text[]; v_action text;
begin
  if auth.role()='service_role' or public.has_admin_permission('news.write') then return coalesce(new,old); end if;
  v_actions:=public.news_article_required_actions(old,new,tg_op);
  foreach v_action in array v_actions loop
    if not public.has_section_action('news',v_action) then
      raise exception 'NEWS_ACTION_DENIED: %',v_action using errcode='42501';
    end if;
  end loop;
  if tg_op='DELETE' and old.record_origin<>'ADMIN_PHASE2' then
    raise exception 'NEWS_HISTORICAL_DELETE_DENIED' using errcode='42501';
  end if;
  return coalesce(new,old);
end
$function$

CREATE OR REPLACE FUNCTION public.enforce_personalized_financial_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.program_id='prestamo' then
    if coalesce(auth.role(),'')<>'service_role' then
      raise exception 'FINANCIAL_CONFIRMATION_REQUIRED' using errcode='42501';
    end if;
    if new.financial_submission_snapshot is null
       or not(new.financial_submission_snapshot?'financialResult')
       or not(new.financial_submission_snapshot?'criteria_source_fingerprint')
       or not(new.financial_submission_snapshot?'profile_fingerprint')
       or not(new.financial_submission_snapshot?'confirmed_at') then
      raise exception 'FINANCIAL_SUBMISSION_SNAPSHOT_REQUIRED' using errcode='22023';
    end if;
  elsif tg_op='UPDATE' and new.financial_submission_snapshot is distinct from old.financial_submission_snapshot then
    raise exception 'FINANCIAL_SUBMISSION_SNAPSHOT_IMMUTABLE' using errcode='P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_program_catalog_requestability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item public.program_catalog_items%rowtype;
begin
  if new.program_item_id is null then return new; end if;
  select * into v_item from public.program_catalog_items where id=new.program_item_id;
  if v_item.id is null then raise exception 'PROGRAM_PRODUCT_NOT_FOUND' using errcode='P0001'; end if;
  if v_item.sold then raise exception 'PROGRAM_PRODUCT_SOLD' using errcode='P0001'; end if;
  if v_item.commercial_mode='DIRECT_CONTACT' then
    raise exception 'PROGRAM_PRODUCT_DIRECT_CONTACT_ONLY' using errcode='P0001';
  end if;
  if v_item.program_key='prestamo' then return new; end if;
  if v_item.commercial_mode='PAYROLL_QUOTE' and new.request_type='quote'
     and new.financial_submission_snapshot is null then return new; end if;
  if new.request_type='benefit'
     and new.financial_submission_snapshot->>'contract_version'='PROGRAM_PRODUCT_PAYMENT_V1' then return new; end if;
  raise exception 'PROGRAM_PRODUCT_PAYMENT_FLOW_REQUIRED' using errcode='P0001';
end $function$

CREATE OR REPLACE FUNCTION public.enforce_request_document_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_doc public.affiliate_documents%rowtype;
  v_asset_id uuid;
begin
  select * into v_doc from public.affiliate_documents where id=new.affiliate_document_id;
  if v_doc.id is null or v_doc.document_type_id<>new.document_type_id then
    raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023';
  end if;
  if exists(
    select 1 from public.affiliate_documents newer
    where newer.affiliate_id=v_doc.affiliate_id
      and newer.document_type_id=v_doc.document_type_id
      and (newer.created_at,newer.id)>(v_doc.created_at,v_doc.id)
  ) then
    raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023';
  end if;
  select coalesce(v_doc.private_asset_id,af.private_asset_id) into v_asset_id
  from public.affiliate_files af where af.id=v_doc.affiliate_file_id;
  v_asset_id:=coalesce(v_doc.private_asset_id,v_asset_id);
  if v_asset_id is null or v_asset_id<>new.private_asset_id or not exists(
    select 1 from public.private_assets pa
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where pa.id=v_asset_id and pa.status='READY'
  ) then
    raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_section_row_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
  v_new jsonb:=case when tg_op='DELETE' then '{}'::jsonb else to_jsonb(new) end;
  v_section text:=tg_argv[0];v_technical text:=tg_argv[1];v_actions text[];v_action text;
  v_origin_col text:=tg_argv[5];v_admin_origin text:=tg_argv[6];v_company uuid;
begin
  if tg_table_name='educational_resources' then
    v_section:=case when coalesce(v_new->>'resource_kind',v_old->>'resource_kind')='tutorial' then 'tutorials' else 'education' end;
    if tg_op='UPDATE' and v_old->>'resource_kind' is distinct from v_new->>'resource_kind' then
      if not public.has_section_action(case when v_old->>'resource_kind'='tutorial' then 'tutorials' else 'education' end,'update')
         or not public.has_section_action(case when v_new->>'resource_kind'='tutorial' then 'tutorials' else 'education' end,'create') then
        raise exception 'SECTION_BOUNDARY_CHANGE_DENIED';
      end if;
    end if;
  end if;
  if auth.role()='service_role' or public.has_admin_permission(v_technical) then return coalesce(new,old);end if;
  -- Preserve the existing company-tenant Marketplace writer without granting it section ownership.
  if tg_table_name in('marketplace_products','marketplace_promotions') then
    v_company:=coalesce((v_new->>'company_id')::uuid,(v_old->>'company_id')::uuid);
    if public.is_marketplace_company_member(v_company,'write') then return coalesce(new,old);end if;
  elsif tg_table_name='marketplace_product_assets' then
    select p.company_id into v_company from public.marketplace_products p where p.id=coalesce((v_new->>'product_id')::uuid,(v_old->>'product_id')::uuid);
    if public.is_marketplace_company_member(v_company,'write') then return coalesce(new,old);end if;
  end if;
  v_actions:=public.section_row_required_actions(v_old,v_new,tg_op,tg_argv[2],tg_argv[3],string_to_array(tg_argv[4],','));
  foreach v_action in array v_actions loop
    if not public.has_section_action(v_section,v_action) then raise exception 'SECTION_ACTION_DENIED:%:%',v_section,v_action;end if;
  end loop;
  if tg_op='INSERT' and v_origin_col<>'' and coalesce(v_new->>v_origin_col,'')<>v_admin_origin then
    raise exception 'ADMIN_ORIGIN_REQUIRED';
  end if;
  if tg_op='DELETE' and v_origin_col<>'' and coalesce(v_old->>v_origin_col,'')<>v_admin_origin then
    raise exception 'HISTORICAL_DELETE_DENIED';
  end if;
  if tg_op='UPDATE' and v_origin_col<>'' and (v_old->v_origin_col) is distinct from (v_new->v_origin_col) then
    raise exception 'RECORD_ORIGIN_IMMUTABLE';
  end if;
  return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION public.fail_financial_request_export(p_request_id uuid, p_payload_sha256 text, p_error_code text, p_error_message text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_audit public.financial_request_export_audit%rowtype;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_error_code,''))) not between 3 and 100 then raise exception 'EXPORT_ERROR_CODE_INVALID' using errcode='22023'; end if;
  if p_actor is null or not exists(select 1 from auth.users where id=p_actor) then raise exception 'EXPORT_ACTOR_REQUIRED' using errcode='22023'; end if;
  select * into v_audit from public.financial_request_export_audit where program_request_id=p_request_id for update;
  if v_audit.program_request_id is null or v_audit.payload_sha256<>p_payload_sha256 or v_audit.export_status<>'in_progress' then
    raise exception 'EXPORT_FAILURE_STATE_INVALID' using errcode='P0001';
  end if;
  update public.program_requests set financial_processing_status='failed',updated_at=now()
  where id=p_request_id and status='approved' and financial_processing_status='in_progress';
  if not found then raise exception 'EXPORT_FAILURE_REQUEST_STATE_INVALID' using errcode='P0001'; end if;
  update public.financial_request_export_audit set export_status='failed',error_code=btrim(p_error_code),
    error_message=left(btrim(coalesce(p_error_message,'')),500),last_actor_auth_user_id=p_actor,updated_at=now()
  where program_request_id=p_request_id;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_program_request_context(p_request_id uuid, p_terms_version_id uuid, p_document_ids uuid[])
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.program_requests%rowtype;v_missing integer; begin
  select * into v_row from public.program_requests where id=p_request_id and affiliate_id=public.get_effective_affiliate_id() and actor_real_auth_user_id=auth.uid() for update;
  if v_row.id is null then raise exception 'REQUEST_ACCESS_DENIED' using errcode='42501'; end if;
  if not exists(select 1 from public.program_terms_versions t where t.id=p_terms_version_id and t.program_id=v_row.program_id and t.membership_offering_id is not distinct from v_row.membership_offering_id and t.published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing from public.program_document_requirements r where r.program_id=v_row.program_id and r.membership_offering_id is not distinct from v_row.membership_offering_id and r.enabled and r.required and not exists(
    select 1 from public.affiliate_documents d where d.id=any(p_document_ids) and d.affiliate_id=v_row.affiliate_id and d.document_type_id=r.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  update public.program_requests set terms_version_id=p_terms_version_id,updated_at=now() where id=v_row.id returning * into v_row;
  perform public.attach_request_documents(v_row.id,p_document_ids);return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.generate_program_product_payment_schedule(p_start_date date, p_process_code text, p_number_of_payments integer, p_total numeric, p_regular_payment numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_process text:=upper(btrim(coalesce(p_process_code,'')));
  v_min_date date;
  v_cursor date;
  v_candidate date;
  v_dates date[]:=array[]::date[];
  v_rows jsonb:='[]'::jsonb;
  v_index integer;
  v_payment numeric(14,2);
  v_paid numeric(14,2):=0;
  v_remaining numeric(14,2);
begin
  if p_start_date is null or v_process not in('1','3','JUB') or p_number_of_payments not between 1 and 240
     or p_total is null or p_total<=0 or p_regular_payment is null or p_regular_payment<=0 then
    raise exception 'PAYMENT_SCHEDULE_INPUT_INVALID' using errcode='22023';
  end if;
  v_min_date:=p_start_date+30;
  v_cursor:=date_trunc('month',v_min_date)::date;
  while cardinality(v_dates)<p_number_of_payments loop
    if v_process='JUB' then
      v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,5);
      if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
    else
      v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,15);
      if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
      if cardinality(v_dates)<p_number_of_payments then
        v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,
          case when extract(month from v_cursor)::integer=2 then 28 else 30 end);
        if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
      end if;
    end if;
    v_cursor:=(v_cursor+interval '1 month')::date;
    if v_cursor>p_start_date+interval '30 years' then raise exception 'PAYMENT_SCHEDULE_GENERATION_FAILED'; end if;
  end loop;
  for v_index in 1..p_number_of_payments loop
    v_payment:=case when v_index=p_number_of_payments then round(p_total-v_paid,2) else round(p_regular_payment,2) end;
    if v_payment<=0 then raise exception 'PAYMENT_SCHEDULE_TOTAL_INVALID' using errcode='22023'; end if;
    v_paid:=round(v_paid+v_payment,2);
    v_remaining:=greatest(0,round(p_total-v_paid,2));
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
      'number',v_index,'date',v_dates[v_index],'payment',v_payment,'remaining_total',v_remaining,
      'final_payment',v_index=p_number_of_payments
    ));
  end loop;
  if v_paid<>round(p_total,2) then raise exception 'PAYMENT_SCHEDULE_RECONCILIATION_FAILED'; end if;
  return jsonb_build_object(
    'version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','process',v_process,
    'frequency',case when v_process='JUB' then 'mensual' else 'quincenal' end,
    'anchor_date',p_start_date,'minimum_first_payment_date',v_min_date,
    'first_payment_date',v_dates[1],'last_payment_date',v_dates[p_number_of_payments],
    'payment_count',p_number_of_payments,'rows',v_rows,'total',round(p_total,2)
  );
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_affiliate_workbench(p_affiliate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile jsonb;v_options jsonb;v_documents jsonb;v_requests jsonb;v_audit jsonb;
  v_can_documents boolean;v_can_requests boolean;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  v_can_documents:=public.has_admin_permission('documents.read') or public.has_admin_permission('assets.read');
  v_can_requests:=public.has_admin_permission('program_requests.read');
  select (to_jsonb(a)-array['auth_user_id','historical_email_normalized','source_file_hash','source_row_ordinal','financial_profile_updated_by','financial_profile_seed_source_hash','financial_profile_seed_row_ordinal']::text[])
    || jsonb_build_object('auth_linked',a.auth_user_id is not null)
  into v_profile from public.affiliates a where a.id=p_affiliate_id;
  if v_profile is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  select coalesce(jsonb_object_agg(catalog_type,items),'{}'::jsonb) into v_options from (
    select catalog_type,jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) items
    from public.segmentation_catalog_entries where enabled and catalog_type in('union','employment_category') group by catalog_type
  ) q;
  if v_can_documents then
    select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'type_id',d.document_type_id,'type_code',t.code,'type_label',t.label,
      'required',t.required_by_default,'status',d.status,'observation',d.review_observation,'created_at',d.created_at,'updated_at',d.updated_at)
      order by d.created_at desc),'[]'::jsonb) into v_documents
    from public.affiliate_documents d join public.document_types t on t.id=d.document_type_id where d.affiliate_id=p_affiliate_id;
  end if;
  if v_can_requests then
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'folio',x.folio,'program_id',x.program_id,'request_type',x.request_type,
      'status',x.status,'financial_processing_status',x.financial_processing_status,'created_at',x.created_at,'updated_at',x.updated_at)
      order by x.created_at desc),'[]'::jsonb) into v_requests
    from (select * from public.program_requests where affiliate_id=p_affiliate_id order by created_at desc limit 50) x;
  end if;
  select coalesce(jsonb_agg(event order by event_at desc),'[]'::jsonb) into v_audit from (
    select e.created_at event_at,jsonb_build_object('id',e.event_id,'at',e.created_at,'action',e.action,'reason',e.reason,
      'actor',e.actor_auth_user_id,'changed_fields',e.changed_fields,'before',e.before_values,'after',e.after_values) event
    from public.affiliate_admin_events e where e.affiliate_id=p_affiliate_id
    union all
    select l.changed_at,jsonb_build_object('id',l.id,'at',l.changed_at,'action','PROFILE_FIELD_CHANGE','reason',l.reason,
      'actor',l.changed_by,'changed_fields',array[l.field_name],'before',jsonb_build_object(l.field_name,l.old_value),
      'after',jsonb_build_object(l.field_name,l.new_value))
    from public.affiliate_profile_audit_log l where l.affiliate_id=p_affiliate_id
  ) q;
  return jsonb_build_object('profile',v_profile,'options',v_options,'documents',v_documents,'requests',v_requests,'audit',v_audit,
    'capabilities',jsonb_build_object('documents',v_can_documents,'requests',v_can_requests));
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_panel_detail(p_record_id uuid, p_history_limit integer DEFAULT 6, p_history_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;r public.savings_review_records;person jsonb;withdrawals jsonb;withdrawn_total numeric;begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501'; end if;
 if p_history_limit is null or p_history_limit not between 1 and 50 or p_history_offset is null or p_history_offset<0 then raise exception 'SAVINGS_PANEL_INVALID'; end if;
 select * into r from public.savings_review_records where id=p_record_id and source_sheet='Ahorro';
 if not found then raise exception 'SAVINGS_PANEL_NOT_FOUND';end if;
 select a into person from public.savings_panel_people(p_record_id) a;
 withdrawals:=public.get_admin_savings_review_withdrawals(p_record_id);
 select case when count(distinct w->'batch'->>'id')<=1
  and count(*) filter(where w->'source_data'->>'H'='Completado')=count(public.savings_panel_number(w->'source_data'->'G')) filter(where w->'source_data'->>'H'='Completado')
  then coalesce(sum(public.savings_panel_number(w->'source_data'->'G')) filter(where w->'source_data'->>'H'='Completado'),0) end
 into withdrawn_total from jsonb_array_elements(withdrawals->'records') w;
 with dates as materialized (
  select f->>'key' key,left(f->>'label',10)::date fecha,f->>'label' label,r.source_data->(f->>'key') original,
   case when person->>'identity_pending'='true' then r.source_data->(f->>'key') else (r.source_data||r.proposed_data)->(f->>'key') end monto,
   coalesce(r.proposed_data ? (f->>'key') and r.proposed_data->(f->>'key') is distinct from r.source_data->(f->>'key'),false) corregido
  from jsonb_array_elements(r.field_defs) f where f->>'label' ~ '^\d{4}-\d{2}-\d{2}' and f->>'label' like '%Descuento registrado%'
 ), page as (select * from dates order by fecha desc,key offset p_history_offset limit p_history_limit)
 select jsonb_build_object('person',person,'record',public.get_admin_savings_review(p_record_id),'dates',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'::jsonb),'date_count',(select count(*) from dates),'withdrawals',withdrawals,'withdrawn_total',withdrawn_total,'can_write',public.savings_review_edit_allowed(),'can_identity',public.savings_review_identity_allowed()) into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_panel_neighbor(p_record_id uuid, p_tab text, p_search text, p_filter text, p_direction integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare anchor jsonb;result jsonb;begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501';end if;
 if p_record_id is null or p_direction is null or p_direction not in (-1,1) or p_tab is null or p_tab not in ('padron','revision','cobranza') or p_filter is null or p_filter not in ('todos','ahorrando','pausado','baja','pendientes','resueltas') or length(coalesce(p_search,''))>200 then raise exception 'SAVINGS_PANEL_INVALID';end if;
 if (select count(distinct batch_id) from public.savings_review_records where source_sheet='Ahorro')>1 then raise exception 'SAVINGS_PANEL_MULTIPLE_BASELINES';end if;
 select a into anchor from public.savings_panel_people(p_record_id) a;
 if anchor is null then raise exception 'SAVINGS_PANEL_NOT_FOUND';end if;
 with filtered as materialized (
  select a from public.savings_panel_people() a where
   (coalesce(p_search,'')='' or position(lower(p_search) in lower(coalesce(a->>'nombre','')))>0 or position(p_search in coalesce(a->>'folio',''))>0)
   and (p_tab<>'revision' or ((a->>'needs_review')::boolean or a->>'status'='RESOLVED'))
   and (p_tab<>'cobranza' or a->>'zero_recorded'='true')
   and (p_filter='todos' or p_filter='pendientes' and a->>'status'<>'RESOLVED' or p_filter='resueltas' and a->>'status'='RESOLVED' or p_filter='pausado' and a->>'zero_recorded'='true' or a->>'estado'=p_filter)
 ), numbered as (
  select a,row_number() over(order by a->>'nombre',a->>'folio',(a->>'source_row')::int,a->>'id') n,count(*) over() total from filtered
 ), candidates as (
  select * from numbered where case when p_direction=1 then
   row(a->>'nombre',a->>'folio' is null,coalesce(a->>'folio',''),(a->>'source_row')::int,a->>'id')>
   row(anchor->>'nombre',anchor->>'folio' is null,coalesce(anchor->>'folio',''),(anchor->>'source_row')::int,anchor->>'id')
  else
   row(a->>'nombre',a->>'folio' is null,coalesce(a->>'folio',''),(a->>'source_row')::int,a->>'id')<
   row(anchor->>'nombre',anchor->>'folio' is null,coalesce(anchor->>'folio',''),(anchor->>'source_row')::int,anchor->>'id') end
 ) select jsonb_build_object('id',a->>'id','has_prev',n>1,'has_next',n<total) into result from candidates order by case when p_direction=1 then n end,case when p_direction=-1 then n end desc limit 1;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_panel_request(p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.savings_review_records;begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501';end if;
 select * into r from public.savings_review_records where id=p_record_id and source_sheet in ('Solicitud de retiro','Solicitud Cambio ahorro');
 if not found then raise exception 'SAVINGS_PANEL_NOT_FOUND';end if;
 return (public.get_admin_savings_review(p_record_id)-'raw_source')||jsonb_build_object('identity',public.savings_review_identity(r.source_folio),'identity_pending',(r.source_data||r.proposed_data)->>'A' is distinct from r.source_folio);
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_panel(p_tab text DEFAULT 'padron'::text, p_search text DEFAULT ''::text, p_filter text DEFAULT 'todos'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; k jsonb; cut timestamptz; collection jsonb;
begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501'; end if;
 if p_tab is null or p_tab not in ('padron','cobranza','solicitudes','revision') or p_filter is null or p_filter not in ('todos','ahorrando','pausado','baja','pendientes','resueltas') or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 or length(coalesce(p_search,''))>200 then raise exception 'SAVINGS_PANEL_INVALID'; end if;
 if (select count(distinct batch_id) from public.savings_review_records where source_sheet='Ahorro')>1 then raise exception 'SAVINGS_PANEL_MULTIPLE_BASELINES';end if;
 select max(observed_at) into cut from public.savings_review_batches;
 with people as materialized (select value a from public.savings_panel_people() value), next_day as (select min((a->>'prox')::date) d from people)
 select jsonb_build_object('total',case when count(*)=count(a->>'saldo') then coalesce(sum((a->>'saldo')::numeric),0) end,'activos',count(*) filter(where a->>'estado'='ahorrando'),
  'padron',count(*),'afiliados',(select count(*) from public.affiliates where not coalesce(is_archived,false)),
  'prox',(select d from next_day),'porRecibir',sum((a->>'porRecibir')::numeric) filter(where (a->>'prox')::date=(select d from next_day)),
  'altas',count(*) filter(where date_trunc('month',(a->>'inicio')::date)=date_trunc('month',cut at time zone 'America/Hermosillo')),
  'bajas',count(*) filter(where date_trunc('month',(a->>'bajaAt')::date)=date_trunc('month',cut at time zone 'America/Hermosillo')),
  'incidencias',count(*) filter(where (a->>'needs_review')::boolean and a->>'status'<>'RESOLVED'),
  'pendientes',(select count(*) from public.savings_review_records r where r.status<>'RESOLVED' and r.source_sheet in ('Solicitud Cambio ahorro','Solicitud de retiro')),
  'solicitudes_estado_pendiente',(select count(*) from public.savings_review_records r where r.status<>'RESOLVED' and (r.source_sheet='Solicitud Cambio ahorro' and (r.source_data||r.proposed_data)->>'E' is distinct from 'TRUE' or r.source_sheet='Solicitud de retiro' and (r.source_data||r.proposed_data)->>'H' is distinct from 'Completado')),
  'cobranza',jsonb_build_object('pct',null,'esperado',null,'recibido',null,'fecha',null)) into k from people;
 with dates as materialized (
  select left(f->>'label',10)::date fecha,public.savings_panel_number(r.source_data->(f->>'key')) amount
  from public.savings_review_records r cross join lateral jsonb_array_elements(r.field_defs) f
  where r.source_sheet='Ahorro' and f->>'label' ~ '^\d{4}-\d{2}-\d{2}' and f->>'label' like '%Descuento registrado%'
 ), last_day as(select max(fecha) d from dates)
 select jsonb_build_object('fecha',(select d from last_day),'recibido',sum(amount),'esperado',null,'pct',null,'sin_importe',count(*) filter(where amount is null)) into collection from dates where fecha=(select d from last_day);
 k:=jsonb_set(k,'{cobranza}',collection);
 if p_tab in ('padron','revision','cobranza') then
  with people as materialized (select value a from public.savings_panel_people() value), filtered as materialized (
   select a from people where
    (coalesce(p_search,'')='' or position(lower(p_search) in lower(coalesce(a->>'nombre','')))>0 or position(p_search in coalesce(a->>'folio',''))>0)
    and (p_tab<>'revision' or ((a->>'needs_review')::boolean or a->>'status'='RESOLVED'))
    and (p_tab<>'cobranza' or a->>'zero_recorded'='true')
    and (p_filter='todos' or p_filter='pendientes' and a->>'status'<>'RESOLVED' or p_filter='resueltas' and a->>'status'='RESOLVED' or p_filter='pausado' and a->>'zero_recorded'='true' or a->>'estado'=p_filter)
  ), page as (select a from filtered order by a->>'nombre',a->>'folio',(a->>'source_row')::int,a->>'id' offset p_offset limit p_limit)
  select jsonb_build_object('rows',coalesce((select jsonb_agg(a) from page),'[]'::jsonb),'total',(select count(*) from filtered),'saldo_total',(select case when count(*)=count(a->>'saldo') then coalesce(sum((a->>'saldo')::numeric),0) end from filtered)) into result;
 else
  with requests as materialized (
   select r.id,r.source_sheet,r.source_row,r.source_folio,
    coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(r.source_data) e where e.key=any(case when r.source_sheet='Solicitud de retiro' then array['A','D','E','F','G','H'] else array['A','B','C','D','E'] end)),'{}'::jsonb) source_data,
    coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(r.proposed_data) e where e.key=any(case when r.source_sheet='Solicitud de retiro' then array['A','D','E','F','G','H'] else array['A','B','C','D','E'] end)),'{}'::jsonb) proposed_data,
    r.status,r.version,r.issues,
    (r.source_data||r.proposed_data)->>'A' is distinct from r.source_folio identity_pending,
    public.savings_review_identity(r.source_folio) identity,
    case when r.source_sheet='Solicitud de retiro' then public.savings_panel_date(r.source_data->>'D') else public.savings_panel_date(r.source_data->>'B') end fecha
   from public.savings_review_records r where r.source_sheet in ('Solicitud de retiro','Solicitud Cambio ahorro')
    and (coalesce(p_search,'')='' or position(p_search in coalesce(r.source_folio,''))>0 or position(lower(p_search) in lower(public.savings_review_identity(r.source_folio)->>'name'))>0)
    and (p_filter='todos' or p_filter='resueltas' and r.status='RESOLVED' or p_filter='pendientes' and r.status<>'RESOLVED')
  ), page as(select * from requests order by fecha desc nulls last,source_sheet,source_row,id offset p_offset limit p_limit)
  select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'::jsonb),'total',(select count(*) from requests)) into result;
 end if;
 return result||jsonb_build_object('kpis',k,'cutoff',cut,'publication','PRIVATE_REVIEW_ONLY','can_write',public.savings_review_edit_allowed(),'can_identity',public.savings_review_identity_allowed(),'collection_status','EXPECTED_HISTORY_UNCERTIFIED');
end $function$

CREATE OR REPLACE FUNCTION public.get_affiliate_activation_status(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_count integer;
  v_candidate public.affiliates%rowtype;
begin
  if length(v_email) > 320 or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    return jsonb_build_object('status', 'INVALID_EMAIL');
  end if;

  if exists(
    select 1
    from public.affiliate_csv_auth_link_repairs r
    join public.affiliate_csv_auth_link_repair_batches b
      on b.id = r.batch_id
     and b.status = 'APPLIED'
    join auth.users u
      on u.id = r.auth_user_id
     and u.email_confirmed_at is not null
     and lower(btrim(u.email)) = r.auth_email_normalized
    join public.affiliates a
      on a.id = r.to_affiliate_id
     and a.auth_user_id = r.auth_user_id
     and a.numero_control = r.to_numero_control
    where r.recovered_at is null
      and r.auth_email_normalized = v_email
  ) then
    return jsonb_build_object('status', 'ALREADY_ACTIVATED');
  end if;

  select count(*) into v_count
  from public.affiliates a
  where a.historical_email_normalized = v_email;

  if v_count = 0 then
    return jsonb_build_object('status', 'NOT_REGISTERED');
  end if;
  if v_count <> 1 then
    return jsonb_build_object('status', 'AMBIGUOUS');
  end if;

  select * into v_candidate
  from public.affiliates a
  where a.historical_email_normalized = v_email;

  if v_candidate.is_archived or v_candidate.auth_eligibility <> 'eligible' then
    return jsonb_build_object('status', 'NOT_ELIGIBLE');
  end if;
  if v_candidate.auth_user_id is not null then
    return jsonb_build_object('status', 'ALREADY_ACTIVATED');
  end if;

  return jsonb_build_object('status', 'ELIGIBLE');
end;
$function$

CREATE OR REPLACE FUNCTION public.get_affiliate_admin_profile(p_affiliate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_profile jsonb; v_options jsonb;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  select to_jsonb(a) - array['historical_email_raw','historical_email_normalized','source_file_hash','source_row_ordinal']::text[] into v_profile
  from public.affiliates a where a.id=p_affiliate_id;
  if v_profile is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
