  return jsonb_build_object(
    'notification_phone',coalesce(v_affiliate.notification_phone,v_suggested),
    'source',case when v_affiliate.notification_phone is not null then 'CURRENT_NOTIFICATION_PHONE'
      when v_suggested is not null then 'HISTORICAL_SUGGESTION' else 'NONE' end
  );
end $function$

CREATE OR REPLACE FUNCTION public.get_document_requirement_impact(p_scope_type text, p_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_scope jsonb;v_type text;v_key text;v_active bigint:=0;v_requirements bigint:=0;
begin
  if not public.has_admin_permission('documents.read') then raise exception 'DOCUMENT_CONFIG_DENIED' using errcode='42501'; end if;
  v_scope:=public.assert_document_requirement_scope(p_scope_type,p_scope_key);v_type:=v_scope->>'scope_type';v_key:=v_scope->>'scope_key';
  select count(*) into v_requirements from public.resolve_effective_document_requirements(v_type,v_key);
  if v_type='MEMBERSHIP' then select count(*) into v_active from public.program_requests where membership_offering_id::text=v_key and status in('submitted','in_review');
  elsif v_type='PRODUCT' then select count(*) into v_active from public.program_requests where product_id::text=v_key and status in('submitted','in_review');
  elsif v_type='PROGRAM' and v_key='prestamo' then select count(*) into v_active from public.program_requests where program_id='prestamo' and status in('submitted','in_review','requires_financial_processing');
  elsif v_type='PROGRAM' then select count(*) into v_active from public.program_requests where program_item_id::text=v_key and status in('submitted','in_review');
  elsif v_type='COMPANY' then select count(*) into v_active from public.program_requests where company_id::text=v_key and status in('submitted','in_review'); end if;
  return v_scope||jsonb_build_object('effective_requirements',v_requirements,'active_requests',v_active);
end $function$

CREATE OR REPLACE FUNCTION public.get_financial_admin_catalog()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_result jsonb;
begin
  if not(public.has_admin_permission('financial_programs.read') or public.has_admin_permission('financial_rules.read') or public.has_admin_permission('financial_criteria.visibility.read')) then
    raise exception 'ADMIN_READ_REQUIRED' using errcode='42501';
  end if;
  select jsonb_build_object(
    'authority',(select authority from public.financial_criteria_authority where id='primary'),
    'programs',(select coalesce(jsonb_agg(to_jsonb(p) order by p.sort_order,p.name),'[]'::jsonb) from public.financial_programs p),
    'funds',(select coalesce(jsonb_agg(to_jsonb(f) order by f.program_id,f.sort_order,f.name),'[]'::jsonb) from public.financial_funds f),
    'rules',(select coalesce(jsonb_agg(to_jsonb(r) order by r.legacy_sheet_row nulls last,r.created_at),'[]'::jsonb) from public.financial_rules r
      where r.lifecycle_status in('DRAFT','PUBLISHED','SCHEDULED') and (r.imported_batch_id is null or r.imported_batch_id=(select active_import_batch_id from public.financial_criteria_authority where id='primary')))
  ) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.get_financial_runtime_rules()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_authority public.financial_criteria_authority%rowtype; v_result jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'FINANCIAL_RUNTIME_RULES_DENIED' using errcode='42501'; end if;
  select * into v_authority from public.financial_criteria_authority where id='primary';
  if v_authority.authority<>'SUPABASE' or v_authority.active_import_batch_id is null then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  v_result:=public.financial_runtime_rules_for_batch(v_authority.active_import_batch_id);
  if jsonb_array_length(v_result)<>146 then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.get_program_request_admin_events(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if not public.has_admin_permission('program_requests.read') then
    raise exception 'PROGRAM_REQUEST_READ_DENIED' using errcode='42501';
  end if;
  if not exists(select 1 from public.program_requests where id=p_request_id) then
    raise exception 'REQUEST_NOT_FOUND' using errcode='P0001';
  end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id',e.id,'request_id',e.request_id,'action',e.action,'from_status',e.from_status,
    'to_status',e.to_status,'comment',e.comment,'actor_label',e.actor_label,'created_at',e.created_at,
    'from_stage_id',e.from_stage_id,'to_stage_id',e.to_stage_id,
    'from_stage_label',(select s->>'label' from jsonb_array_elements(r.workflow_snapshot->'stages') s where s->>'id'=e.from_stage_id::text),
    'to_stage_label',(select s->>'label' from jsonb_array_elements(r.workflow_snapshot->'stages') s where s->>'id'=e.to_stage_id::text)
  )) order by e.created_at,e.id),'[]'::jsonb) into v_result
  from public.program_request_admin_events e
  join public.program_requests r on r.id=e.request_id
  where e.request_id=p_request_id;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.get_request_submission_backend_contract()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_writer text;
  v_constraint text;
  v_ready boolean;
  v_writer_ready boolean;
  v_constraint_ready boolean;
  v_wrapper_ready boolean;
  v_idempotency_ready boolean;
begin
  select pg_get_functiondef(p.oid) into v_writer
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.oid=to_regprocedure(
    'public.create_validated_financial_program_request_bank_required(uuid,uuid,uuid,uuid,text,text,uuid,uuid[],uuid,numeric,integer,text,integer,jsonb)');
  select pg_get_constraintdef(c.oid,true) into v_constraint
  from pg_constraint c
  where c.conrelid='public.loan_request_deposit_snapshots'::regclass
    and c.conname='loan_deposit_optional_bank_coherence';
  v_writer_ready:=coalesce(v_writer like '%card_number is null or card_number ~%'
    and v_writer like '%clabe is null or public.is_valid_clabe(clabe)%',false);
  v_constraint_ready:=coalesce(v_constraint like '%card_number IS NULL OR card_number ~%'
    and v_constraint like '%clabe IS NULL OR%is_valid_clabe(clabe)%',false);
  v_wrapper_ready:=to_regprocedure('public.create_validated_financial_program_request(uuid,uuid,uuid,uuid,text,text,uuid,uuid[],uuid,numeric,integer,text,integer,jsonb)') is not null;
  v_idempotency_ready:=exists(
      select 1 from pg_index i
      where i.indrelid='public.program_requests'::regclass and i.indisunique
        and pg_get_indexdef(i.indexrelid) like '%(affiliate_id, idempotency_key)%'
    );
  v_ready:=v_writer_ready and v_constraint_ready and v_wrapper_ready and v_idempotency_ready;
  return jsonb_build_object(
    'contract_version','SUTI_REQUEST_SUBMISSION_V2',
    'ready',v_ready,
    'checks',jsonb_build_object('writer',v_writer_ready,'snapshot',v_constraint_ready,'wrapper',v_wrapper_ready,'idempotency',v_idempotency_ready),
    'writer','create_validated_financial_program_request',
    'edge_action','loanSessionConfirm',
    'deposit_contract','BANK_AND_CARD_OR_CLABE',
    'idempotency_scope','affiliate_id+idempotency_key',
    'response_fields',jsonb_build_array('request_id','folio','status','confirmed_amount','correlation_id')
  );
end $function$

CREATE OR REPLACE FUNCTION public.get_self_savings_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate uuid:=public.get_effective_affiliate_id();
  v_participant public.savings_participants%rowtype;
  v_enrollment public.savings_enrollments%rowtype;
  v_plan public.savings_contribution_plans%rowtype;
  v_balance record;
  v_actions jsonb;
  v_certified boolean:=false;
begin
  if auth.uid() is null or v_affiliate is null then raise exception 'SAVINGS_AFFILIATE_REQUIRED' using errcode='42501'; end if;
  select * into v_participant from public.savings_participants where affiliate_id=v_affiliate;
  v_actions:=jsonb_build_object(
    'JOIN',public.savings_effective_action('JOIN',v_participant.id),
    'CHANGE_AMOUNT',public.savings_effective_action('CHANGE_AMOUNT',v_participant.id),
    'WITHDRAW',public.savings_effective_action('WITHDRAW',v_participant.id),
    'TERMINATE',public.savings_effective_action('TERMINATE',v_participant.id)
  );
  if v_participant.id is null then
    return jsonb_build_object('authority','SHADOW','cutover_status','NOT_CUTOVER','participant',null,'enrollment',null,
      'balances',null,'annual','[]'::jsonb,'history','[]'::jsonb,'upcoming','[]'::jsonb,'beneficiaries','[]'::jsonb,'requests','[]'::jsonb,'actions',v_actions);
  end if;
  v_certified:=v_participant.certification_status='CERTIFIED';
  select * into v_enrollment from public.savings_enrollments where participant_id=v_participant.id order by sequence_number desc limit 1;
  if v_enrollment.id is not null then
    select * into v_plan from public.savings_contribution_plans where enrollment_id=v_enrollment.id
      and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1;
  end if;
  v_actions:=jsonb_build_object(
    'JOIN',public.savings_effective_action('JOIN',v_participant.id) and (v_enrollment.id is null or v_enrollment.status in ('TERMINATED','REJECTED')),
    'CHANGE_AMOUNT',public.savings_effective_action('CHANGE_AMOUNT',v_participant.id) and v_enrollment.status='ACTIVE',
    'WITHDRAW',public.savings_effective_action('WITHDRAW',v_participant.id) and v_enrollment.status='ACTIVE',
    'TERMINATE',public.savings_effective_action('TERMINATE',v_participant.id) and v_enrollment.status='ACTIVE'
  );
  select * into v_balance from public.savings_participant_balance(v_participant.id);
  return jsonb_build_object(
    'authority','SHADOW','cutover_status','NOT_CUTOVER','certified',v_certified,
    'participant',jsonb_build_object('id',v_participant.id,'participant_type',v_participant.participant_type,'identity_status',v_participant.identity_status,
      'certification_status',v_participant.certification_status,'current_process',v_participant.current_process,'data_classification',v_participant.data_classification),
    'enrollment',case when v_enrollment.id is null then null else jsonb_build_object('id',v_enrollment.id,'sequence_number',v_enrollment.sequence_number,'status',v_enrollment.status,
      'enrollment_started_at',v_enrollment.enrollment_started_at,'requested_at',v_enrollment.requested_at,'approved_at',v_enrollment.approved_at,
      'first_expected_contribution_date',v_enrollment.first_expected_contribution_date,'first_actual_contribution_date',v_enrollment.first_actual_contribution_date,
      'process_snapshot',v_enrollment.process_snapshot,'continue_saving',v_enrollment.continue_saving,
      'current_contribution_amount',v_plan.amount,'frequency',case when v_plan.process_snapshot='JUB' then 'MONTHLY' when v_plan.process_snapshot in ('PROCESS_1','PROCESS_3') then 'TWICE_MONTHLY' else null end,
      'yield_eligibility','NOT_ENABLED') end,
    'balances',case when not v_certified then null else jsonb_build_object('capital',v_balance.capital,'yield',v_balance.yield_amount,'total',v_balance.total,
      'held_capital',v_balance.held_capital,'held_yield',v_balance.held_yield,'held',v_balance.held,'available',v_balance.available) end,
    'annual',case when not v_certified then '[]'::jsonb else coalesce((select jsonb_agg(row_to_json(a) order by a."year" desc) from(
      select extract(year from effective_date)::integer as "year",
        sum(case when component='CAPITAL' then case direction when 'CREDIT' then amount else -amount end else 0 end)::numeric capital,
        sum(case when component='YIELD' then case direction when 'CREDIT' then amount else -amount end else 0 end)::numeric yield,
        sum(case direction when 'CREDIT' then amount else -amount end)::numeric subtotal
      from public.savings_transactions where participant_id=v_participant.id group by extract(year from effective_date))a),'[]'::jsonb) end,
    'history',case when not v_certified then '[]'::jsonb else coalesce((select jsonb_agg(row_to_json(t) order by t.effective_date desc,t.created_at desc) from(
      select id,transaction_type,component,direction,amount,effective_date,contribution_date,expected_amount,actual_amount,difference_amount,data_classification,created_at
      from public.savings_transactions where participant_id=v_participant.id order by effective_date desc,created_at desc limit 250)t),'[]'::jsonb) end,
    'upcoming',case when v_enrollment.id is null or v_enrollment.status not in ('ACTIVE','TERMINATION_PENDING') then '[]'::jsonb else
      coalesce((select jsonb_agg(row_to_json(s) order by s.contribution_date) from(
        select contribution_date,expected_amount,process_snapshot from public.generate_savings_schedule(v_enrollment.id,current_date+1,(current_date+interval '12 months')::date) limit 40)s),'[]'::jsonb) end,
    'beneficiaries',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'full_name',b.full_name,'relationship',b.relationship,'percentage',b.percentage) order by b.id)
      from public.savings_beneficiary_versions v join public.savings_beneficiaries b on b.version_id=v.id where v.participant_id=v_participant.id and v.status='ACTIVE'),'[]'::jsonb),
    'requests',coalesce((select jsonb_agg(row_to_json(r) order by r.submitted_at desc) from(
      select id,folio,request_type,withdrawal_kind,component,requested_amount,new_contribution_amount,continue_saving,status,effective_from,reason,submitted_at,reviewed_at,settled_at
      from public.savings_requests where participant_id=v_participant.id order by submitted_at desc limit 50)r),'[]'::jsonb),
    'actions',v_actions
  );
end $function$

CREATE OR REPLACE FUNCTION public.import_savings_shadow_manifest(p_manifest jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text:=upper(coalesce(p_manifest->>'source_snapshot_sha256',''));v_cert_hash text:=upper(coalesce(p_manifest#>>'{certification,evidence_sha256}',''));
  v_certified boolean:=upper(coalesce(p_manifest#>>'{certification,status}',''))='CERTIFIED';v_batch uuid;v_row jsonb;v_participant uuid;v_enrollment uuid;
  v_counts jsonb:=jsonb_build_object('participants',jsonb_array_length(coalesce(p_manifest->'participants','[]'::jsonb)),
    'enrollments',jsonb_array_length(coalesce(p_manifest->'enrollments','[]'::jsonb)),'plans',jsonb_array_length(coalesce(p_manifest->'plans','[]'::jsonb)),
    'transactions',jsonb_array_length(coalesce(p_manifest->'transactions','[]'::jsonb)),'requests',jsonb_array_length(coalesce(p_manifest->'requests','[]'::jsonb)),
    'evidence',jsonb_array_length(coalesce(p_manifest->'evidence','[]'::jsonb)));
begin
  if auth.role()<>'service_role' then raise exception 'SAVINGS_IMPORT_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(p_manifest)<>'object' or v_hash!~'^[A-F0-9]{64}$' then raise exception 'SAVINGS_IMPORT_MANIFEST_INVALID' using errcode='22023'; end if;
  if not v_certified or v_cert_hash<>v_hash then raise exception 'SAVINGS_CERTIFIED_SNAPSHOT_REQUIRED' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(coalesce(p_manifest->'participants','[]'::jsonb))x
    where upper(x->>'identity_status') in ('AMBIGUOUS','ORPHAN') and nullif(x->>'affiliate_id','') is not null) then
    raise exception 'SAVINGS_UNRESOLVED_IDENTITY_MUST_BE_NULL' using errcode='22023';
  end if;
  if not p_apply then return jsonb_build_object('mode','DRY_RUN','authority','SHADOW','certified',true,'source_snapshot_sha256',v_hash,'counts',v_counts); end if;
  insert into public.savings_import_batches(source_workbook_id,source_workbook_name,source_snapshot_sha256,certification_status,status,row_counts,provenance,finished_at)
  values(coalesce(p_manifest->>'source_workbook_id','UNKNOWN'),coalesce(p_manifest->>'source_workbook_name','UNKNOWN'),v_hash,'CERTIFIED','APPLIED',v_counts,
    coalesce(p_manifest->'provenance','{}'::jsonb),now()) returning id into v_batch;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'participants','[]'::jsonb)) loop
    insert into public.savings_participants(participant_type,affiliate_id,legacy_folio,display_name,identity_status,certification_status,current_process,process_source,data_classification,legacy_reported_balance,legacy_balance_status,import_batch_id)
    values(upper(v_row->>'participant_type'),nullif(v_row->>'affiliate_id','')::uuid,nullif(v_row->>'legacy_folio',''),nullif(v_row->>'display_name',''),upper(v_row->>'identity_status'),'CERTIFIED',
      nullif(upper(coalesce(v_row->>'current_process','')),''),upper(coalesce(v_row->>'process_source','LEGACY')),'LEGACY',nullif(v_row->>'legacy_reported_balance','')::numeric,'PENDING_REVIEW',v_batch);
  end loop;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'enrollments','[]'::jsonb)) loop
    select id into strict v_participant from public.savings_participants where import_batch_id=v_batch and legacy_folio=v_row->>'legacy_folio';
    insert into public.savings_enrollments(participant_id,sequence_number,status,enrollment_started_at,requested_at,approved_at,first_expected_contribution_date,first_actual_contribution_date,terminated_at,continue_saving,process_snapshot,data_classification,import_batch_id)
    values(v_participant,(v_row->>'sequence_number')::integer,upper(v_row->>'status'),(v_row->>'enrollment_started_at')::timestamptz,nullif(v_row->>'requested_at','')::timestamptz,
      nullif(v_row->>'approved_at','')::timestamptz,nullif(v_row->>'first_expected_contribution_date','')::date,nullif(v_row->>'first_actual_contribution_date','')::date,
      nullif(v_row->>'terminated_at','')::timestamptz,coalesce((v_row->>'continue_saving')::boolean,true),nullif(upper(coalesce(v_row->>'process_snapshot','')),''),'LEGACY',v_batch);
  end loop;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'plans','[]'::jsonb)) loop
    select e.id into strict v_enrollment from public.savings_enrollments e join public.savings_participants p on p.id=e.participant_id
      where p.import_batch_id=v_batch and p.legacy_folio=v_row->>'legacy_folio' and e.sequence_number=(v_row->>'enrollment_sequence')::integer;
    insert into public.savings_contribution_plans(enrollment_id,amount,process_snapshot,effective_from,effective_to,data_classification,import_batch_id)
    values(v_enrollment,(v_row->>'amount')::numeric,upper(v_row->>'process_snapshot'),(v_row->>'effective_from')::date,nullif(v_row->>'effective_to','')::date,'LEGACY',v_batch);
  end loop;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'evidence','[]'::jsonb)) loop
    select id into v_participant from public.savings_participants where import_batch_id=v_batch and legacy_folio=v_row->>'legacy_folio';
    insert into public.savings_legacy_evidence(import_batch_id,participant_id,source_workbook_id,source_sheet,source_column,source_row,legacy_folio,observed_on,numeric_value,record_type,data_classification,source_row_sha256,raw_payload)
    values(v_batch,v_participant,coalesce(v_row->>'source_workbook_id',p_manifest->>'source_workbook_id'),v_row->>'source_sheet',v_row->>'source_column',(v_row->>'source_row')::integer,
      nullif(v_row->>'legacy_folio',''),nullif(v_row->>'observed_on','')::date,nullif(v_row->>'numeric_value','')::numeric,upper(v_row->>'record_type'),upper(v_row->>'data_classification'),
      upper(v_row->>'source_row_sha256'),coalesce(v_row->'raw_payload','{}'::jsonb));
  end loop;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'transactions','[]'::jsonb)) loop
    select id into strict v_participant from public.savings_participants where import_batch_id=v_batch and legacy_folio=v_row->>'legacy_folio';
    v_enrollment:=null;
    if nullif(v_row->>'enrollment_sequence','') is not null then select e.id into strict v_enrollment from public.savings_enrollments e where e.participant_id=v_participant and e.sequence_number=(v_row->>'enrollment_sequence')::integer; end if;
    insert into public.savings_transactions(participant_id,enrollment_id,transaction_type,component,direction,amount,effective_date,contribution_date,expected_amount,actual_amount,difference_amount,idempotency_key,data_classification,import_batch_id)
    values(v_participant,v_enrollment,upper(v_row->>'transaction_type'),upper(v_row->>'component'),upper(v_row->>'direction'),(v_row->>'amount')::numeric,(v_row->>'effective_date')::date,
      nullif(v_row->>'contribution_date','')::date,nullif(v_row->>'expected_amount','')::numeric,nullif(v_row->>'actual_amount','')::numeric,nullif(v_row->>'difference_amount','')::numeric,
      'LEGACY:'||v_hash||':'||coalesce(v_row->>'source_key',extensions.gen_random_uuid()::text),'LEGACY',v_batch);
  end loop;
  for v_row in select value from jsonb_array_elements(coalesce(p_manifest->'requests','[]'::jsonb)) loop
    select id into strict v_participant from public.savings_participants where import_batch_id=v_batch and legacy_folio=v_row->>'legacy_folio';
    insert into public.savings_requests(folio,participant_id,request_type,withdrawal_kind,component,requested_amount,new_contribution_amount,continue_saving,status,effective_from,reason,idempotency_key,submitted_at,reviewed_at,settled_at,data_classification,metadata)
    values(coalesce(v_row->>'folio','LEGACY-'||upper(substr(replace(extensions.gen_random_uuid()::text,'-',''),1,12))),v_participant,upper(v_row->>'request_type'),nullif(upper(coalesce(v_row->>'withdrawal_kind','')),''),
      nullif(upper(coalesce(v_row->>'component','')),''),nullif(v_row->>'requested_amount','')::numeric,nullif(v_row->>'new_contribution_amount','')::numeric,nullif(v_row->>'continue_saving','')::boolean,
      upper(coalesce(v_row->>'status','SETTLED')),nullif(v_row->>'effective_from','')::date,coalesce(v_row->>'reason','Legacy certificado'),extensions.gen_random_uuid(),
      (v_row->>'submitted_at')::timestamptz,nullif(v_row->>'reviewed_at','')::timestamptz,nullif(v_row->>'settled_at','')::timestamptz,'LEGACY',coalesce(v_row->'metadata','{}'::jsonb));
  end loop;
  insert into public.savings_audit_events(resource,action,target_id,after_data,reason)
  values('savings_import_batches','IMPORT_CERTIFIED_SHADOW',v_batch::text,jsonb_build_object('hash',v_hash,'counts',v_counts),'No cutover; Google remains productive authority');
  return jsonb_build_object('mode','APPLY','authority','SHADOW','batch_id',v_batch,'source_snapshot_sha256',v_hash,'counts',v_counts);
exception when unique_violation then raise exception 'SAVINGS_IMPORT_ALREADY_APPLIED_OR_DUPLICATE' using errcode='23505';
end $function$

CREATE OR REPLACE FUNCTION public.issue_credential_qr()
 RETURNS TABLE(token text, destination_path text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_affiliate uuid;v_raw text;v_ttl integer; begin
  v_affiliate:=public.get_effective_affiliate_id();if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  select s.destination_path,s.ttl_seconds into destination_path,v_ttl from public.credential_qr_settings s where s.id;
  v_raw:=replace(extensions.gen_random_uuid()::text,'-','')||replace(extensions.gen_random_uuid()::text,'-','');expires_at:=now()+make_interval(secs=>v_ttl);
  delete from public.credential_qr_tokens q where q.affiliate_id=v_affiliate or q.expires_at<now();
  insert into public.credential_qr_tokens(affiliate_id,token_hash,destination_path,expires_at) values(v_affiliate,upper(encode(extensions.digest(v_raw,'sha256'),'hex')),destination_path,expires_at);
  token:=v_raw;return next;
end $function$

CREATE OR REPLACE FUNCTION public.list_admin_affiliates(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_auth_linked boolean DEFAULT NULL::boolean, p_document_state text DEFAULT NULL::text, p_has_pending_documents boolean DEFAULT NULL::boolean, p_union_code text DEFAULT NULL::text, p_category_code text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_sort text DEFAULT 'name'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_query text:=lower(btrim(coalesce(p_query,'')));v_page integer:=greatest(coalesce(p_page,1),1);v_page_size integer:=least(greatest(coalesce(p_page_size,25),10),100);v_result jsonb;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  if p_document_state is not null and upper(p_document_state) not in('COMPLETE','INCOMPLETE','NOT_CONFIGURED') then raise exception 'AFFILIATE_DOCUMENT_FILTER_INVALID' using errcode='22023'; end if;
  if coalesce(p_sort,'name') not in('name','control','recent') then raise exception 'AFFILIATE_SORT_INVALID' using errcode='22023'; end if;
  with required as(select count(*)::integer required_count from public.document_types where enabled and required_by_default),
  docs as(select d.affiliate_id,count(*) filter(where d.status<>'REJECTED')::integer document_count,count(*) filter(where d.status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED'))::integer pending_document_count,count(distinct d.document_type_id) filter(where d.status='VERIFIED' and t.enabled and t.required_by_default)::integer verified_required_count from public.affiliate_documents d join public.document_types t on t.id=d.document_type_id group by d.affiliate_id),
  requests as(select r.affiliate_id,count(*)::integer request_count,count(*) filter(where r.status in('submitted','in_review','requires_financial_processing'))::integer pending_request_count from public.program_requests r group by r.affiliate_id),
  base as(select a.id,a.numero_control,a.full_name,a.display_name,a.historical_email_raw,a.phone_raw,a.rfc_raw,a.curp_raw,a.affiliate_status_raw,a.affiliation_raw,a.financial_union_code,a.financial_employee_category_code,a.financial_affiliation_status,a.financial_employment_status,a.updated_at,a.record_origin,(a.auth_user_id is not null) auth_linked,coalesce(d.document_count,0) document_count,coalesce(d.pending_document_count,0) pending_document_count,coalesce(d.verified_required_count,0) verified_required_count,required.required_count,case when required.required_count=0 then 'NOT_CONFIGURED' when coalesce(d.verified_required_count,0)>=required.required_count then 'COMPLETE' else 'INCOMPLETE' end document_state,coalesce(r.request_count,0) request_count,coalesce(r.pending_request_count,0) pending_request_count,lower(coalesce(a.full_name,a.display_name,'')) sort_name from public.affiliates a cross join required left join docs d on d.affiliate_id=a.id left join requests r on r.affiliate_id=a.id where not a.is_archived),
  filtered as(select * from base b where (v_query='' or position(v_query in lower(concat_ws(' ',b.full_name,b.display_name,b.numero_control,b.historical_email_raw,b.phone_raw,b.rfc_raw,b.curp_raw)))>0) and (p_status is null or b.affiliate_status_raw=p_status) and (p_auth_linked is null or b.auth_linked=p_auth_linked) and (p_document_state is null or b.document_state=upper(p_document_state)) and (p_has_pending_documents is null or (b.pending_document_count>0)=p_has_pending_documents) and (p_union_code is null or b.financial_union_code=p_union_code) and (p_category_code is null or b.financial_employee_category_code=p_category_code)),
  page_rows as(select * from filtered order by case when p_sort='control' then coalesce(numero_control,'') end,case when p_sort='recent' then updated_at end desc,case when p_sort='name' then sort_name end,sort_name,id offset (v_page-1)*v_page_size limit v_page_size)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(x)-'sort_name') from(select * from page_rows)x),'[]'::jsonb),'total',(select count(*) from filtered),'page',v_page,'page_size',v_page_size,'filter_options',jsonb_build_object('statuses',coalesce((select jsonb_agg(value order by value) from(select distinct affiliate_status_raw value from public.affiliates where not is_archived and affiliate_status_raw is not null and btrim(affiliate_status_raw)<>'')s),'[]'::jsonb),'unions',coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) from public.segmentation_catalog_entries where catalog_type='union' and enabled),'[]'::jsonb),'categories',coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) from public.segmentation_catalog_entries where catalog_type='employment_category' and enabled),'[]'::jsonb))) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.list_admin_archived_affiliates(p_query text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_sort text DEFAULT 'recent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_query text:=lower(btrim(coalesce(p_query,'')));v_page integer:=greatest(coalesce(p_page,1),1);v_page_size integer:=least(greatest(coalesce(p_page_size,25),10),100);v_result jsonb;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  if coalesce(p_sort,'recent') not in('name','control','recent') then raise exception 'AFFILIATE_SORT_INVALID' using errcode='22023'; end if;
  with docs as(select affiliate_id,count(*)::integer document_count from public.affiliate_documents group by affiliate_id),requests as(select affiliate_id,count(*)::integer request_count from public.program_requests group by affiliate_id),base as(
    select a.id,a.numero_control,a.full_name,a.display_name,a.historical_email_raw,a.rfc_raw,a.curp_raw,a.affiliate_status_raw,a.archive_previous_status_raw,a.archived_at,a.archived_by_auth_user_id,a.archive_reason,a.updated_at,a.record_origin,(a.auth_user_id is not null) auth_linked,coalesce(d.document_count,0) document_count,coalesce(r.request_count,0) request_count,lower(coalesce(a.full_name,a.display_name,'')) sort_name
    from public.affiliates a left join docs d on d.affiliate_id=a.id left join requests r on r.affiliate_id=a.id where a.is_archived
  ),filtered as(select * from base b where v_query='' or position(v_query in lower(concat_ws(' ',b.full_name,b.display_name,b.numero_control,b.historical_email_raw,b.rfc_raw,b.curp_raw)))>0),page_rows as(
    select * from filtered order by case when p_sort='control' then coalesce(numero_control,'') end,case when p_sort='recent' then archived_at end desc,case when p_sort='name' then sort_name end,sort_name,id offset (v_page-1)*v_page_size limit v_page_size)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(x)-'sort_name') from(select * from page_rows)x),'[]'::jsonb),'total',(select count(*) from filtered),'page',v_page,'page_size',v_page_size,'filter_options','{}'::jsonb) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.list_current_deposit_accounts()
 RETURNS SETOF affiliate_bank_accounts
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_affiliate uuid;
begin
  if auth.uid() is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  v_affiliate:=public.get_effective_affiliate_id();
