CREATE OR REPLACE FUNCTION public.mark_marketplace_quote_seen(p_quote_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_affiliate uuid;
begin
  v_affiliate:=public.get_effective_affiliate_id();
  if v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;

  update public.program_requests
  set seen_at=coalesce(seen_at,now()),updated_at=now()
  where id=p_quote_id and affiliate_id=v_affiliate and request_type='quote' and status='approved';
  if found then return; end if;

  -- Historical pre-cutover quotes retain their original authority and writer.
  update public.marketplace_quote_requests
  set seen_at=coalesce(seen_at,now()),updated_at=now()
  where id=p_quote_id and affiliate_id=v_affiliate and status='quoted';
  if not found then raise exception 'QUOTE_DENIED' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.materialize_savings_contributions(p_as_of date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row record;v_actual numeric;v_inserted integer:=0;
begin
  if auth.role()<>'service_role' then raise exception 'SAVINGS_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_as_of is null or p_as_of>current_date then raise exception 'SAVINGS_AS_OF_INVALID' using errcode='22023'; end if;
  for v_row in
    select e.id enrollment_id,e.participant_id,s.contribution_date,s.expected_amount
    from public.savings_enrollments e cross join lateral public.generate_savings_schedule(e.id,e.first_expected_contribution_date,p_as_of)s
    where e.status in ('ACTIVE','TERMINATION_PENDING') and e.first_expected_contribution_date<=p_as_of
  loop
    select actual_amount into v_actual from public.savings_contribution_overrides
    where enrollment_id=v_row.enrollment_id and contribution_date=v_row.contribution_date order by version_number desc limit 1;
    v_actual:=coalesce(v_actual,v_row.expected_amount);
    if v_actual>0 then
      insert into public.savings_transactions(participant_id,enrollment_id,transaction_type,component,direction,amount,effective_date,contribution_date,expected_amount,actual_amount,difference_amount,idempotency_key,data_classification)
      values(v_row.participant_id,v_row.enrollment_id,'CONTRIBUTION','CAPITAL','CREDIT',v_actual,v_row.contribution_date,v_row.contribution_date,v_row.expected_amount,v_actual,v_actual-v_row.expected_amount,
        'CONTRIBUTION:'||v_row.enrollment_id||':'||v_row.contribution_date,'SHADOW') on conflict(idempotency_key) do nothing;
      if found then
        v_inserted:=v_inserted+1;
        update public.savings_enrollments set first_actual_contribution_date=coalesce(first_actual_contribution_date,v_row.contribution_date) where id=v_row.enrollment_id;
      end if;
    end if;
  end loop;
  return jsonb_build_object('as_of',p_as_of,'inserted',v_inserted,'authority','SHADOW');
end $function$

CREATE OR REPLACE FUNCTION public.news_article_required_actions(p_old news_articles, p_new news_articles, p_operation text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_actions text[]:='{}'::text[];
begin
  if p_operation='INSERT' then
    v_actions:=array_append(v_actions,'create');
    if p_new.published or p_new.publish_from is not null or p_new.publish_until is not null then
      v_actions:=array_append(v_actions,'publish');
    end if;
    if p_new.image_asset_id is not null then v_actions:=array_append(v_actions,'assets'); end if;
  elsif p_operation='UPDATE' then
    if p_old.record_origin is distinct from p_new.record_origin then
      raise exception 'NEWS_RECORD_ORIGIN_IMMUTABLE' using errcode='42501';
    end if;
    if row(p_old.title,p_old.tag,p_old.body,p_old.accent_hue,p_old.display_date,p_old.reading_minutes)
       is distinct from row(p_new.title,p_new.tag,p_new.body,p_new.accent_hue,p_new.display_date,p_new.reading_minutes) then
      v_actions:=array_append(v_actions,'update');
    end if;
    if p_old.image_asset_id is distinct from p_new.image_asset_id then v_actions:=array_append(v_actions,'assets'); end if;
    if row(p_old.published,p_old.publish_from,p_old.publish_until)
       is distinct from row(p_new.published,p_new.publish_from,p_new.publish_until) then
      v_actions:=array_append(v_actions,'publish');
    end if;
    if p_old.sort_order is distinct from p_new.sort_order then v_actions:=array_append(v_actions,'order'); end if;
  elsif p_operation='DELETE' then
    v_actions:=array_append(v_actions,'delete');
  else
    raise exception 'INVALID_NEWS_OPERATION' using errcode='22023';
  end if;
  return v_actions;
end
$function$

