CREATE OR REPLACE FUNCTION public.protect_approved_financial_request_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if old.financial_approval_snapshot is not null and new.status is distinct from old.status then
    raise exception 'APPROVED_FINANCIAL_REQUEST_STATUS_IMMUTABLE' using errcode='P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_financial_request_snapshots()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.financial_processing_status is not null then
    select jsonb_build_object('affiliate_id',a.id,'numero_control',a.numero_control,'financial_union_code',a.financial_union_code,
      'financial_union',u.label,'financial_employee_category_code',a.financial_employee_category_code,
      'financial_employee_category',c.label,'financial_employee_type',a.financial_employee_type,
      'financial_affiliation_status',a.financial_affiliation_status,'financial_employment_status',a.financial_employment_status,
      'profile_version',a.financial_profile_version,'captured_at',now()) into new.financial_profile_snapshot
    from public.affiliates a
    left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
    left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
    where a.id=new.affiliate_id;
  elsif tg_op='UPDATE' then
    if new.financial_profile_snapshot is distinct from old.financial_profile_snapshot or old.financial_approval_snapshot is not null and new.financial_approval_snapshot is distinct from old.financial_approval_snapshot then
      raise exception 'FINANCIAL_SNAPSHOT_IMMUTABLE' using errcode='P0001';
    end if;
    if new.financial_processing_status is not null and new.status='approved' and old.status is distinct from 'approved' and new.financial_approval_snapshot is null then
      raise exception 'FINANCIAL_APPROVAL_SNAPSHOT_REQUIRED' using errcode='P0001';
    end if;
    if old.requested_amount is not null and (new.requested_amount is distinct from old.requested_amount or new.requested_term is distinct from old.requested_term or new.requested_term_semantics is distinct from old.requested_term_semantics) then
      raise exception 'FINANCIAL_REQUEST_TERMS_IMMUTABLE' using errcode='P0001';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.publish_financial_rule(p_rule_id uuid, p_reason text, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_draft public.financial_rules%rowtype; v_previous jsonb; v_published public.financial_rules%rowtype;
begin
  if not public.has_admin_permission('financial_rules.publish') then raise exception 'FINANCIAL_RULES_PUBLISH_REQUIRED' using errcode='42501'; end if;
  if p_confirmation<>'PUBLICAR' or length(btrim(coalesce(p_reason,'')))<8 then raise exception 'FINANCIAL_RULE_PUBLISH_INVALID' using errcode='22023'; end if;
  select * into v_draft from public.financial_rules where id=p_rule_id and lifecycle_status='DRAFT' for update;
  if v_draft.id is null then raise exception 'FINANCIAL_RULE_DRAFT_NOT_FOUND' using errcode='P0001'; end if;
  select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) into v_previous from public.financial_rules r
    where r.lineage_id=v_draft.lineage_id and r.lifecycle_status in('PUBLISHED','SCHEDULED');
  update public.financial_rules set lifecycle_status='EXPIRED' where lineage_id=v_draft.lineage_id and lifecycle_status in('PUBLISHED','SCHEDULED');
  update public.financial_rules set lifecycle_status=case when available_on is not null and available_on>current_date then 'SCHEDULED' else 'PUBLISHED' end,
    published_at=now(),published_by=auth.uid() where id=v_draft.id returning * into v_published;
  update public.financial_session_snapshots set invalidated_at=now(),invalidation_reason='FINANCIAL_RULE_PUBLISHED' where invalidated_at is null;
  insert into public.financial_configuration_audit(actor_auth_user_id,resource_type,resource_id,action,old_value,new_value,reason)
  values(auth.uid(),'RULE',v_published.id::text,'PUBLISH',jsonb_build_object('previous_live_versions',v_previous),to_jsonb(v_published),btrim(p_reason));
  return to_jsonb(v_published);
end $function$

CREATE OR REPLACE FUNCTION public.publish_program_terms(p_program_id text, p_membership_offering_id uuid, p_title text, p_body text)
 RETURNS program_terms_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.program_terms_versions%rowtype;v_version integer; begin
  if not public.has_admin_permission('documents.write') then raise exception 'TERMS_CONFIG_DENIED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_title,'')))<3 or length(btrim(coalesce(p_body,'')))<20 then raise exception 'TERMS_CONTENT_REQUIRED' using errcode='22023'; end if;
  update public.program_terms_versions set published=false,published_at=null where program_id=p_program_id and membership_offering_id is not distinct from p_membership_offering_id and published;
  select coalesce(max(version),0)+1 into v_version from public.program_terms_versions where program_id=p_program_id and membership_offering_id is not distinct from p_membership_offering_id;
  insert into public.program_terms_versions(program_id,membership_offering_id,version,title,body,published,published_at,created_by_auth_user_id) values(p_program_id,p_membership_offering_id,v_version,btrim(p_title),btrim(p_body),true,now(),auth.uid()) returning * into v_row;return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.record_program_request_admin_action(p_request_id uuid, p_action text, p_comment text, p_client_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.program_requests%rowtype;v_existing public.program_request_admin_events%rowtype;
  v_event public.program_request_admin_events%rowtype;v_action text:=upper(btrim(coalesce(p_action,'')));
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');v_to_status text;v_actor_label text;
  v_from_stage uuid;v_to_stage uuid;
begin
  if auth.uid() is null or not public.has_admin_permission('program_requests.write') then raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501'; end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_action not in('COMMENT','MARK_IN_REVIEW','REJECT','CANCEL') then raise exception 'PROGRAM_REQUEST_ACTION_INVALID' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023'; end if;
  if v_action in('COMMENT','REJECT','CANCEL') and v_comment is null then raise exception 'PROGRAM_REQUEST_COMMENT_REQUIRED' using errcode='22023'; end if;
  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or v_existing.action<>v_action then raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505'; end if;
    return to_jsonb(v_existing)-'actor_auth_user_id'-'client_action_id';
  end if;
  select * into v_request from public.program_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'PROGRAM_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_action<>'COMMENT' and (v_request.financial_approval_snapshot is not null or v_request.status='approved') then raise exception 'APPROVED_FINANCIAL_REQUEST_STATUS_IMMUTABLE' using errcode='P0001'; end if;
  v_from_stage:=nullif(public.resolve_program_request_workflow_state(v_request.id)->>'current_stage_id','')::uuid;
  v_to_status:=v_request.status;
  if v_action='MARK_IN_REVIEW' then
    if v_request.status not in('submitted','requires_financial_processing') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='in_review';
  elsif v_action='REJECT' then
    if v_request.status not in('submitted','requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='rejected';
  elsif v_action='CANCEL' then
    if v_request.status not in('submitted','requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='cancelled';
  end if;
  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),nullif(btrim(raw_user_meta_data->>'full_name'),''),nullif(btrim(raw_user_meta_data->>'name'),''),'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  if v_to_status is distinct from v_request.status then update public.program_requests set status=v_to_status,updated_at=now() where id=v_request.id; end if;
  v_to_stage:=nullif(public.resolve_program_request_workflow_state(v_request.id)->>'current_stage_id','')::uuid;
  insert into public.program_request_admin_events(request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,from_stage_id,to_stage_id)
  values(v_request.id,auth.uid(),left(coalesce(v_actor_label,'Personal autorizado'),160),v_action,v_request.status,v_to_status,v_comment,p_client_action_id,v_from_stage,v_to_stage)
  returning * into v_event;
  return to_jsonb(v_event)-'actor_auth_user_id'-'client_action_id';
end $function$

CREATE OR REPLACE FUNCTION public.recover_affiliate_csv_auth_link_repair(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.affiliate_csv_auth_link_repair_batches%rowtype;
  v_restored integer;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED' using errcode = '42501';
  end if;

  lock table public.affiliates in share row exclusive mode;
  select * into v_batch
  from public.affiliate_csv_auth_link_repair_batches
  where id = p_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'BATCH_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_batch.status = 'RECOVERED' then
    return jsonb_build_object('status', 'RECOVERED', 'idempotent', true);
  end if;
  if v_batch.status <> 'APPLIED'
    or v_batch.deterministic_cross_links_after <> 0
    or (select count(*) from public.affiliate_csv_auth_link_repairs where batch_id = p_batch_id and recovered_at is null) <> v_batch.repaired_count
    or (select count(*) from public.affiliate_csv_auth_link_repair_snapshot where batch_id = p_batch_id) <> v_batch.affected_affiliate_rows then
    raise exception 'RECOVERY_MANIFEST_MISMATCH' using errcode = 'P0001';
  end if;
  if exists(
    select 1
    from public.affiliate_csv_auth_link_repair_snapshot s
    join public.affiliates a on a.id = s.affiliate_id
    where s.batch_id = p_batch_id
      and (
        a.auth_user_id is distinct from s.expected_auth_user_id_after
        or a.updated_at is distinct from s.applied_updated_at
      )
  ) then
    raise exception 'RECOVERY_BLOCKED_AFFECTED_ROW_CHANGED' using errcode = 'P0001';
  end if;

  update public.affiliates a
  set auth_user_id = null
  from public.affiliate_csv_auth_link_repair_snapshot s
  where s.batch_id = p_batch_id
    and a.id = s.affiliate_id
    and a.auth_user_id is not null;

  update public.affiliates a
  set auth_user_id = s.old_auth_user_id
  from public.affiliate_csv_auth_link_repair_snapshot s
  where s.batch_id = p_batch_id
    and a.id = s.affiliate_id
    and s.old_auth_user_id is not null
    and a.auth_user_id is null;
  get diagnostics v_restored = row_count;

  if v_restored <> v_batch.repaired_count
    or exists(
      select 1
      from public.affiliate_csv_auth_link_repair_snapshot s
      join public.affiliates a on a.id = s.affiliate_id
      where s.batch_id = p_batch_id
        and a.auth_user_id is distinct from s.old_auth_user_id
    ) then
    raise exception 'RECOVERY_RESTORE_MISMATCH:%', v_restored using errcode = 'P0001';
  end if;

  update public.affiliate_csv_auth_link_repairs
  set recovered_at = now()
  where batch_id = p_batch_id
    and recovered_at is null;

  update public.affiliate_csv_auth_link_repair_snapshot s
  set recovered_updated_at = a.updated_at
  from public.affiliates a
  where s.batch_id = p_batch_id
    and a.id = s.affiliate_id;

  update public.affiliate_csv_auth_link_repair_batches
  set status = 'RECOVERED', recovered_at = now()
  where id = p_batch_id;

  return jsonb_build_object(
    'status', 'RECOVERED',
    'restored_auth_links', v_restored,
    'idempotent', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.recover_affiliate_csv_email_update(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.affiliate_csv_email_update_batches%rowtype;
  v_now timestamptz := clock_timestamp();
  v_identity_before jsonb;
  v_identity_after jsonb;
  v_restored integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  lock table public.affiliates in share row exclusive mode;
  select * into v_batch
  from public.affiliate_csv_email_update_batches
  where id = p_batch_id
  for update;
  if v_batch.id is null then
    raise exception 'CSV_UPDATE_BATCH_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_batch.status = 'RECOVERED' then
    return jsonb_build_object('batch_id', p_batch_id, 'status', 'RECOVERED', 'idempotent', true);
  end if;
  if (select count(*) from public.affiliate_csv_email_update_snapshot where batch_id = p_batch_id) <> 121
    or (select count(*) from public.affiliate_csv_email_update_snapshot where batch_id = p_batch_id and outcome = 'UPDATED_EMAIL') <> 1
  then
    raise exception 'CSV_UPDATE_RECOVERY_SNAPSHOT_INCOMPLETE' using errcode = 'P0001';
  end if;
  if exists (
    select 1
    from public.affiliate_csv_email_update_snapshot s
    join public.affiliates a on a.id = s.affiliate_id
    where s.batch_id = p_batch_id
      and s.outcome = 'UPDATED_EMAIL'
      and (
        a.auth_user_id is distinct from s.old_auth_user_id
        or a.historical_email_raw is distinct from s.proposed_email_raw
        or a.historical_email_normalized is distinct from s.proposed_email_normalized
        or a.auth_eligibility is distinct from s.applied_auth_eligibility
        or a.auth_ineligibility_reason is distinct from s.applied_auth_ineligibility_reason
      )
  ) then
    raise exception 'CSV_UPDATE_RECOVERY_BLOCKED_BY_LATER_EMAIL_OR_IDENTITY_CHANGE' using errcode = 'P0001';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object('affiliate_id', a.id, 'auth_user_id', a.auth_user_id)
    order by a.id
  ), '[]'::jsonb)
  into v_identity_before
  from public.affiliates a
  where a.auth_user_id is not null;

  update public.affiliates a
  set historical_email_raw = s.old_email_raw,
      historical_email_normalized = s.old_email_normalized,
      auth_eligibility = s.old_auth_eligibility,
      auth_ineligibility_reason = s.old_auth_ineligibility_reason,
      updated_at = v_now
  from public.affiliate_csv_email_update_snapshot s
  where s.batch_id = p_batch_id
    and s.outcome = 'UPDATED_EMAIL'
    and a.id = s.affiliate_id;
  get diagnostics v_restored = row_count;
  if v_restored <> 1 then
    raise exception 'CSV_UPDATE_RECOVERY_ROW_COUNT_MISMATCH:%', v_restored using errcode = 'P0001';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object('affiliate_id', a.id, 'auth_user_id', a.auth_user_id)
    order by a.id
  ), '[]'::jsonb)
  into v_identity_after
  from public.affiliates a
  where a.auth_user_id is not null;
  if v_identity_after is distinct from v_identity_before then
    raise exception 'AUTH_IDENTITY_MAPPING_CHANGED_DURING_RECOVERY' using errcode = 'P0001';
  end if;

  update public.affiliate_csv_email_update_batches
  set status = 'RECOVERED',
      recovered_at = v_now,
      result = result || jsonb_build_object('status', 'RECOVERED', 'recovered_at', v_now)
  where id = p_batch_id;

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'status', 'RECOVERED',
    'affiliates_restored', v_restored,
    'auth_identity_mapping_changed', false,
    'idempotent', false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.recover_affiliate_financial_profile_seed(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_batch public.affiliate_financial_profile_seed_batches%rowtype; v_now timestamptz:=clock_timestamp();
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  select * into v_batch from public.affiliate_financial_profile_seed_batches where id=p_batch_id for update;
  if v_batch.id is null then raise exception 'SEED_BATCH_NOT_FOUND' using errcode='P0001'; end if;
  if v_batch.status='RECOVERED' then return jsonb_build_object('batch_id',p_batch_id,'status','RECOVERED','idempotent',true); end if;
  if (select count(*) from public.affiliate_financial_profile_seed_snapshot where batch_id=p_batch_id)<>947 then raise exception 'RECOVERY_SNAPSHOT_INCOMPLETE' using errcode='P0001'; end if;
  if exists(
    select 1 from public.affiliate_financial_profile_seed_snapshot s join public.affiliates a on a.id=s.affiliate_id
    where s.batch_id=p_batch_id and (a.financial_union_code is distinct from s.new_financial_union_code
      or a.financial_employee_category_code is distinct from s.new_financial_employee_category_code
      or a.financial_profile_seed_source_hash<>v_batch.source_file_hash
      or a.financial_profile_seed_row_ordinal<>s.source_row_ordinal)
  ) then raise exception 'RECOVERY_BLOCKED_BY_CURRENT_PROFILE_DIFFERENCE' using errcode='P0001'; end if;

  insert into public.affiliate_profile_audit_log(affiliate_id,field_name,old_value,new_value,changed_by,reason,profile_version,batch_id,change_source,changed_at)
  select a.id,'financial_employee_category_code',to_jsonb(a.financial_employee_category_code),to_jsonb(s.old_financial_employee_category_code),null,
    'BULK_INITIAL_FINANCIAL_PROFILE_SEED_RECOVERY',a.financial_profile_version+1,p_batch_id,'BULK_INITIAL_FINANCIAL_PROFILE_SEED_RECOVERY',v_now
  from public.affiliates a join public.affiliate_financial_profile_seed_snapshot s on s.affiliate_id=a.id and s.batch_id=p_batch_id
  where a.financial_employee_category_code is distinct from s.old_financial_employee_category_code;
  insert into public.affiliate_profile_audit_log(affiliate_id,field_name,old_value,new_value,changed_by,reason,profile_version,batch_id,change_source,changed_at)
  select a.id,'financial_union_code',to_jsonb(a.financial_union_code),to_jsonb(s.old_financial_union_code),null,
    'BULK_INITIAL_FINANCIAL_PROFILE_SEED_RECOVERY',a.financial_profile_version+1,p_batch_id,'BULK_INITIAL_FINANCIAL_PROFILE_SEED_RECOVERY',v_now
  from public.affiliates a join public.affiliate_financial_profile_seed_snapshot s on s.affiliate_id=a.id and s.batch_id=p_batch_id
  where a.financial_union_code is distinct from s.old_financial_union_code;

  update public.affiliates a set
    financial_union_code=s.old_financial_union_code,
    financial_employee_category_code=s.old_financial_employee_category_code,
    financial_profile_version=a.financial_profile_version+1,
    financial_profile_updated_at=v_now,
    financial_profile_updated_by=null,
    financial_profile_seed_source_hash=s.old_seed_source_hash,
    financial_profile_seed_row_ordinal=s.old_seed_row_ordinal,
    financial_profile_seeded_at=s.old_seeded_at,
    updated_at=v_now
  from public.affiliate_financial_profile_seed_snapshot s where s.batch_id=p_batch_id and a.id=s.affiliate_id;
  update public.affiliate_financial_profile_seed_batches set status='RECOVERED',recovered_at=v_now,
    result=result||jsonb_build_object('status','RECOVERED','recovered_at',v_now) where id=p_batch_id;
  return jsonb_build_object('batch_id',p_batch_id,'status','RECOVERED','affiliates_restored',947,'idempotent',false);
end $function$

CREATE OR REPLACE FUNCTION public.register_admin_affiliate_document(p_affiliate_id uuid, p_document_type_id uuid, p_storage_path text, p_mime_type text, p_file_size bigint, p_sha256 text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_type public.document_types%rowtype;v_asset public.private_assets%rowtype;v_doc public.affiliate_documents%rowtype;v_replaced uuid;v_path text:=btrim(coalesce(p_storage_path,''));v_reason text:=btrim(coalesce(p_reason,''));v_cleanup_path text;
begin
  if not public.has_admin_permission('documents.write') then raise exception 'ADMIN_DOCUMENT_WRITE_DENIED' using errcode='42501'; end if;
  if auth.uid() is null or not exists(select 1 from public.affiliates where id=p_affiliate_id) then raise exception 'AFFILIATE_NOT_FOUND' using errcode='22023'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'DOCUMENT_REASON_REQUIRED' using errcode='22023'; end if;
  select * into v_type from public.document_types where id=p_document_type_id and enabled;
  if v_type.id is null then raise exception 'DOCUMENT_TYPE_UNAVAILABLE' using errcode='22023'; end if;
  if not v_type.file_upload_allowed or not(p_mime_type=any(v_type.accepted_mime_types)) or p_file_size<1 or p_file_size>v_type.max_file_size_bytes or upper(coalesce(p_sha256,''))!~'^[A-F0-9]{64}$' then raise exception 'INVALID_DOCUMENT_FILE' using errcode='22023'; end if;
  if v_path!~('^affiliate-documents/'||p_affiliate_id::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_STORAGE_PATH' using errcode='22023'; end if;
  if not exists(select 1 from storage.objects where bucket_id='private-assets' and name=v_path and owner_id=auth.uid()::text) then raise exception 'UPLOAD_NOT_FOUND' using errcode='22023'; end if;
  select d.id into v_replaced from public.affiliate_documents d where d.affiliate_id=p_affiliate_id and d.document_type_id=p_document_type_id order by d.created_at desc,d.id desc limit 1;
  select * into v_asset from public.private_assets where content_sha256=upper(p_sha256) for update;
  if v_asset.id is null then begin
    insert into public.private_assets(asset_key,asset_type,title,storage_bucket,storage_path,mime_type,file_size,content_sha256)
    values('affiliate_document_'||replace(extensions.gen_random_uuid()::text,'-',''),'AFFILIATE_DOCUMENT',v_type.label,'private-assets',v_path,p_mime_type,p_file_size,upper(p_sha256)) returning * into v_asset;
  exception when unique_violation then select * into v_asset from public.private_assets where content_sha256=upper(p_sha256) for update;end;end if;
  if v_asset.id is null then raise exception 'DOCUMENT_ASSET_REGISTRATION_FAILED'; end if;
  if v_asset.storage_path is distinct from v_path then v_cleanup_path:=v_path; end if;
  update public.affiliate_documents set status='REJECTED',review_observation='Reemplazado por una nueva carga administrativa.',reviewed_by_auth_user_id=auth.uid(),reviewed_at=now()
   where affiliate_id=p_affiliate_id and document_type_id=p_document_type_id and status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED');
  insert into public.affiliate_documents(affiliate_id,document_type_id,private_asset_id,status,created_by_auth_user_id,replaces_document_id)
   values(p_affiliate_id,p_document_type_id,v_asset.id,'PENDING_REVIEW',auth.uid(),v_replaced) returning * into v_doc;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
   values(auth.uid(),p_affiliate_id,'affiliate_documents',case when v_replaced is null then 'ADMIN_UPLOAD' else 'ADMIN_REPLACEMENT_UPLOAD' end,v_doc.id,jsonb_strip_nulls(jsonb_build_object('document_type_id',p_document_type_id,'mime_type',p_mime_type,'file_size',p_file_size,'reason',v_reason,'replaces_document_id',v_replaced)));
  return jsonb_build_object('document',to_jsonb(v_doc),'cleanup_storage_path',v_cleanup_path);
end $function$

CREATE OR REPLACE FUNCTION public.register_affiliate_document(p_document_type_id uuid, p_storage_path text, p_mime_type text, p_file_size bigint, p_sha256 text, p_source text)
 RETURNS affiliate_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_affiliate uuid;v_type public.document_types%rowtype;v_asset public.private_assets%rowtype;v_doc public.affiliate_documents%rowtype;v_replaced uuid;v_path text:=btrim(p_storage_path);
begin
  v_affiliate:=public.get_effective_affiliate_id();
  if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  select * into v_type from public.document_types where id=p_document_type_id and enabled;
  if v_type.id is null then raise exception 'DOCUMENT_TYPE_UNAVAILABLE' using errcode='22023'; end if;
  if upper(coalesce(p_source,'')) not in('CAMERA','FILE')
    or (upper(p_source)='CAMERA' and not v_type.camera_allowed)
    or (upper(p_source)='FILE' and not v_type.file_upload_allowed)
    or (upper(p_source)='CAMERA' and p_mime_type not like 'image/%')
    or not(p_mime_type=any(v_type.accepted_mime_types)) or p_file_size<1 or p_file_size>v_type.max_file_size_bytes or upper(p_sha256)!~'^[A-F0-9]{64}$' then raise exception 'INVALID_DOCUMENT_FILE' using errcode='22023'; end if;
  if v_path!~('^affiliate-documents/'||v_affiliate::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_STORAGE_PATH' using errcode='22023'; end if;
  if not exists(select 1 from storage.objects where bucket_id='private-assets' and name=v_path and owner_id=auth.uid()::text) then raise exception 'UPLOAD_NOT_FOUND' using errcode='22023'; end if;
  select d.id into v_replaced from public.affiliate_documents d where d.affiliate_id=v_affiliate and d.document_type_id=p_document_type_id order by d.created_at desc,d.id desc limit 1;
  select * into v_asset from public.private_assets where content_sha256=upper(p_sha256);
  if v_asset.id is null then insert into public.private_assets(asset_key,asset_type,title,storage_bucket,storage_path,mime_type,file_size,content_sha256)
    values('affiliate_document_'||replace(extensions.gen_random_uuid()::text,'-',''),'AFFILIATE_DOCUMENT',v_type.label,'private-assets',v_path,p_mime_type,p_file_size,upper(p_sha256)) returning * into v_asset; end if;
  update public.affiliate_documents set status='REJECTED',review_observation='Reemplazado por una nueva carga.',reviewed_by_auth_user_id=auth.uid(),reviewed_at=now()
    where affiliate_id=v_affiliate and document_type_id=p_document_type_id and status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED');
  insert into public.affiliate_documents(affiliate_id,document_type_id,private_asset_id,status,created_by_auth_user_id,replaces_document_id)
    values(v_affiliate,p_document_type_id,v_asset.id,'PENDING_REVIEW',auth.uid(),v_replaced) returning * into v_doc;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
    values(auth.uid(),v_affiliate,'affiliate_documents',case when v_replaced is null then 'UPLOAD' else 'REPLACEMENT_UPLOAD' end,v_doc.id,
      jsonb_strip_nulls(jsonb_build_object('document_type_id',p_document_type_id,'mime_type',p_mime_type,'file_size',p_file_size,'source',upper(p_source),'replaces_document_id',v_replaced)));
  return v_doc;
end $function$

CREATE OR REPLACE FUNCTION public.register_branding_assets(p_assets jsonb)
 RETURNS TABLE(asset_key text, asset_id uuid, previous_storage_bucket text, previous_storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_asset_key text;
  v_storage_path text;
  v_mime_type text;
  v_file_size bigint;
  v_content_sha256 text;
  v_extension text;
  v_expected_path text;
  v_asset_id uuid;
  v_previous_bucket text;
  v_previous_path text;
  v_count integer;
  v_keys text[] := array[]::text[];
begin
  if not public.has_admin_permission('assets.write') then
    raise exception 'ADMIN_DENIED' using errcode = '42501';
  end if;

  if jsonb_typeof(p_assets) <> 'array' then
    raise exception 'INVALID_ASSET_BATCH' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(p_assets);
  if v_count < 1 or v_count > 4 then
    raise exception 'INVALID_ASSET_BATCH' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_assets)
  loop
    v_asset_key := nullif(trim(v_item->>'asset_key'), '');
    v_storage_path := nullif(trim(v_item->>'storage_path'), '');
    v_mime_type := nullif(trim(v_item->>'mime_type'), '');
    v_content_sha256 := upper(nullif(trim(v_item->>'content_sha256'), ''));
    begin
      v_file_size := (v_item->>'file_size')::bigint;
    exception when others then
      raise exception 'INVALID_ASSET_FILE_SIZE' using errcode = '22023';
    end;

    if v_asset_key is null or not (v_asset_key = any(array[
      'brand.pwa.512',
      'brand.institutional-seal',
      'brand.favicon-pwa-192',
      'brand.pwa.apple-touch',
      'brand.pwa.maskable-512',
      'pwa.install-screen-1',
      'pwa.install-screen-2',
      'pwa.install-screen-3',
      'home.header.collapsed'
    ]::text[])) then
      raise exception 'UNKNOWN_BRANDING_ASSET' using errcode = '22023';
    end if;
    if v_asset_key = any(v_keys) then
      raise exception 'DUPLICATE_BRANDING_ASSET' using errcode = '22023';
    end if;
    v_keys := array_append(v_keys, v_asset_key);

    v_extension := case v_mime_type
      when 'image/png' then 'png'
      when 'image/jpeg' then 'jpg'
      when 'image/gif' then 'gif'
      when 'image/webp' then 'webp'
      when 'image/svg+xml' then 'svg'
      when 'image/x-icon' then 'ico'
      else null
    end;
    if v_extension is null or v_file_size < 1 or v_file_size > 10485760
       or v_content_sha256 !~ '^[A-F0-9]{64}$' then
      raise exception 'INVALID_BRANDING_ASSET' using errcode = '22023';
    end if;

    v_expected_path := 'branding/admin/' ||
      regexp_replace(v_asset_key, '[^a-zA-Z0-9._-]', '-', 'g') || '/' ||
      lower(v_content_sha256) || '.' || v_extension;
    if v_storage_path is distinct from v_expected_path then
      raise exception 'INVALID_BRANDING_STORAGE_PATH' using errcode = '22023';
    end if;
    if not exists(
      select 1 from storage.objects o
      where o.bucket_id = 'app-assets' and o.name = v_storage_path
    ) then
      raise exception 'BRANDING_UPLOAD_NOT_FOUND' using errcode = '22023';
    end if;

    select a.id, a.storage_bucket, a.storage_path
      into v_asset_id, v_previous_bucket, v_previous_path
    from public.app_assets a
    where a.asset_key = v_asset_key
    for update;

    if v_asset_id is null then
      insert into public.app_assets(
        asset_key, asset_type, title, alt_text, storage_bucket, storage_path,
        mime_type, file_size, content_sha256, status
      ) values (
        v_asset_key, 'BRANDING', v_asset_key, replace(v_asset_key, '.', ' '),
        'app-assets', v_storage_path, v_mime_type, v_file_size,
        v_content_sha256, 'READY'
      ) returning id into v_asset_id;
    else
      update public.app_assets set
        asset_type = 'BRANDING',
        title = v_asset_key,
        alt_text = replace(v_asset_key, '.', ' '),
        storage_bucket = 'app-assets',
        storage_path = v_storage_path,
        mime_type = v_mime_type,
        file_size = v_file_size,
        content_sha256 = v_content_sha256,
        status = 'READY'
      where id = v_asset_id;
    end if;

    insert into public.asset_sources(
      asset_id, source_sheet, source_column, source_snapshot_hash
    ) values (
      v_asset_id, 'ADMIN_H009', v_asset_key, v_content_sha256
    ) on conflict do nothing;

    case v_asset_key
      when 'brand.pwa.512' then
        update public.app_settings
          set app_icon_asset_id = v_asset_id, pwa_icon_512_asset_id = v_asset_id
        where id = 'primary';
      when 'brand.institutional-seal' then
        update public.app_settings set institutional_seal_asset_id = v_asset_id where id = 'primary';
      when 'brand.favicon-pwa-192' then
        update public.app_settings
          set favicon_asset_id = v_asset_id, pwa_icon_192_asset_id = v_asset_id
        where id = 'primary';
      when 'brand.pwa.apple-touch' then
        update public.app_settings set apple_touch_asset_id = v_asset_id where id = 'primary';
      when 'brand.pwa.maskable-512' then
        update public.app_settings set pwa_maskable_512_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-1' then
        update public.app_settings set install_screen_1_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-2' then
        update public.app_settings set install_screen_2_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-3' then
        update public.app_settings set install_screen_3_asset_id = v_asset_id where id = 'primary';
      when 'home.header.collapsed' then null;
    end case;

    asset_key := v_asset_key;
    asset_id := v_asset_id;
    previous_storage_bucket := v_previous_bucket;
    previous_storage_path := v_previous_path;
    return next;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_operational_workflow_stages(p_workflow_id uuid, p_stage_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_total integer;v_distinct integer;v_changed integer;
begin
  if not public.has_admin_permission('workflow.write') then raise exception 'WORKFLOW_WRITE_DENIED' using errcode='42501'; end if;
  select count(*) into v_total from public.operational_workflow_stages where workflow_id=p_workflow_id;
  select count(distinct id) into v_distinct from unnest(coalesce(p_stage_ids,array[]::uuid[])) id;
  if v_total=0 or cardinality(coalesce(p_stage_ids,array[]::uuid[]))<>v_total or v_distinct<>v_total or exists(
    select 1 from unnest(p_stage_ids) id where not exists(select 1 from public.operational_workflow_stages s where s.id=id and s.workflow_id=p_workflow_id)
  ) then raise exception 'WORKFLOW_STAGE_ORDER_INVALID' using errcode='22023'; end if;
  perform set_config('app.workflow_change_reason','Reordenamiento de etapas',true);
  update public.operational_workflow_stages s set sort_order=(ordered.ordinality*10)::integer
  from unnest(p_stage_ids) with ordinality ordered(id,ordinality)
  where s.id=ordered.id and s.workflow_id=p_workflow_id;
  get diagnostics v_changed=row_count;
  return v_changed;
end $function$

CREATE OR REPLACE FUNCTION public.reorder_program_catalog_items(p_program_key text, p_item_ids uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=(select auth.uid()); v_count integer; v_id uuid; v_position integer:=0;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501'; end if;
  if p_item_ids is null or cardinality(p_item_ids)=0 or cardinality(p_item_ids)>500 or cardinality(p_item_ids)<>(select count(distinct x) from unnest(p_item_ids) x) then
    raise exception 'PROGRAM_CATALOG_ORDER_INVALID' using errcode='22023';
  end if;
  select count(*) into v_count from public.program_catalog_items where program_key=p_program_key;
  if v_count<>cardinality(p_item_ids) or exists(select 1 from unnest(p_item_ids) x where not exists(select 1 from public.program_catalog_items i where i.id=x and i.program_key=p_program_key)) then
    raise exception 'PROGRAM_CATALOG_ORDER_SCOPE_MISMATCH' using errcode='22023';
  end if;
  update public.program_catalog_items set sort_order=sort_order+10000 where program_key=p_program_key;
  foreach v_id in array p_item_ids loop v_position:=v_position+1; update public.program_catalog_items set sort_order=v_position where id=v_id; end loop;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'program_catalog_items','REORDER',p_program_key,'SUCCESS',jsonb_build_object('item_count',v_count));
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.replace_company_asset(p_company_id uuid, p_asset_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_role not in ('logo','cover') then raise exception 'unsupported company asset role'; end if;
  if not public.has_admin_permission('companies.write') then raise exception 'admin permission denied'; end if;
  delete from public.company_assets where company_id = p_company_id and role = p_role;
  insert into public.company_assets(company_id, asset_id, role, sort_order)
  values (p_company_id, p_asset_id, p_role, 1);
  if p_role = 'logo' then
    update public.companies set logo_asset_id = p_asset_id where id = p_company_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_self_savings_beneficiaries(p_beneficiaries jsonb, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_affiliate uuid:=public.get_effective_affiliate_id();v_participant uuid;v_version integer;v_version_id uuid;v_total numeric;v_count integer;
begin
  if v_actor is null or v_affiliate is null then raise exception 'SAVINGS_AFFILIATE_REQUIRED' using errcode='42501'; end if;
  if p_idempotency_key is null or jsonb_typeof(p_beneficiaries)<>'array' then raise exception 'SAVINGS_BENEFICIARIES_INVALID' using errcode='22023'; end if;
  if exists(select 1 from public.savings_audit_events where client_action_id=p_idempotency_key) then
    return coalesce((select after_data from public.savings_audit_events where client_action_id=p_idempotency_key),'{}'::jsonb);
  end if;
  select id into v_participant from public.savings_participants where affiliate_id=v_affiliate and certification_status='CERTIFIED';
  if v_participant is null or not exists(select 1 from public.savings_enrollments where participant_id=v_participant and status in ('ACTIVE','TERMINATION_PENDING')) then raise exception 'SAVINGS_ACTIVE_ENROLLMENT_REQUIRED' using errcode='P0001'; end if;
  select count(*),coalesce(sum((x->>'percentage')::numeric),0) into v_count,v_total from jsonb_array_elements(p_beneficiaries)x;
  if v_count<1 or v_count>20 or v_total<>100 or exists(select 1 from jsonb_array_elements(p_beneficiaries)x where length(btrim(x->>'full_name'))<3 or length(btrim(x->>'relationship'))<2 or (x->>'percentage')::numeric<=0) then
    raise exception 'SAVINGS_BENEFICIARIES_MUST_TOTAL_100' using errcode='22023';
  end if;
  select coalesce(max(version_number),0)+1 into v_version from public.savings_beneficiary_versions where participant_id=v_participant;
  update public.savings_beneficiary_versions set status='SUPERSEDED',superseded_at=now() where participant_id=v_participant and status='ACTIVE';
  insert into public.savings_beneficiary_versions(participant_id,version_number,status,actor_real_auth_user_id) values(v_participant,v_version,'ACTIVE',v_actor) returning id into v_version_id;
  insert into public.savings_beneficiaries(version_id,full_name,relationship,percentage)
  select v_version_id,btrim(x->>'full_name'),btrim(x->>'relationship'),(x->>'percentage')::numeric from jsonb_array_elements(p_beneficiaries)x;
  insert into public.savings_audit_events(actor_real_auth_user_id,usuario_contexto_affiliate_id,participant_id,resource,action,target_id,after_data,client_action_id)
  values(v_actor,v_affiliate,v_participant,'savings_beneficiaries','REPLACE_VERSION',v_version_id::text,jsonb_build_object('version',v_version,'beneficiaries',p_beneficiaries),p_idempotency_key);
  return jsonb_build_object('version_id',v_version_id,'version_number',v_version,'beneficiaries',p_beneficiaries);
end $function$

CREATE OR REPLACE FUNCTION public.resolve_current_loan_snapshot_quote(p_snapshot_id uuid, p_program_id text, p_amount numeric, p_term integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_affiliate_id uuid;
  v_impersonation_id uuid;
  v_snapshot public.financial_session_snapshots%rowtype;
  v_affiliate record;
  v_policy public.loan_term_policy%rowtype;
  v_policy_json jsonb;
  v_profile_canonical text;
  v_policy_canonical text;
  v_profile_fingerprint text;
  v_policy_fingerprint text;
  v_quote jsonb;
  v_payroll jsonb;
begin
  if v_actor is null or coalesce(auth.role(),'') <> 'authenticated' then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;
  if p_snapshot_id is null or nullif(btrim(p_program_id),'') is null or p_amount is null or p_amount<=0 or p_term is null or p_term<=0 then
    raise exception 'INVALID_REQUEST' using errcode='22023';
  end if;

  v_affiliate_id := public.get_effective_affiliate_id();
  if v_affiliate_id is null then raise exception 'AFFILIATE_CONTEXT_UNAVAILABLE' using errcode='42501'; end if;
  select s.id into v_impersonation_id
  from public.impersonation_sessions s
  where s.actor_real_auth_user_id=v_actor and s.ended_at is null and s.expires_at>now()
    and public.has_admin_permission('affiliates.impersonate')
  limit 1;

  select a.*,u.label as current_financial_union,c.label as current_financial_category
    into v_affiliate
  from public.affiliates a
  left join public.segmentation_catalog_entries u
    on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
  left join public.segmentation_catalog_entries c
    on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
  where a.id=v_affiliate_id;
  if v_affiliate.id is null or v_affiliate.current_financial_union is null or v_affiliate.current_financial_category is null then
    raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001';
  end if;

  select * into v_snapshot from public.financial_session_snapshots where id=p_snapshot_id for key share;
  if v_snapshot.id is null
     or v_snapshot.actor_real_auth_user_id<>v_actor
     or v_snapshot.affiliate_id<>v_affiliate_id
     or v_snapshot.impersonation_session_id is distinct from v_impersonation_id
     or v_snapshot.invalidated_at is not null
     or v_snapshot.expires_at<=now()
     or v_snapshot.financial_profile_version<>v_affiliate.financial_profile_version
     or v_snapshot.calculation_contract_version<>'SUTI_LOAN_QUOTE_V1' then
    raise exception 'SNAPSHOT_INVALID' using errcode='P0001';
  end if;

  v_profile_canonical := '{'
    ||'"actor_real_auth_user_id":'||to_jsonb(v_actor::text)::text
    ||',"affiliate_id":'||to_jsonb(v_affiliate_id::text)::text
    ||',"financial_affiliation_status":'||coalesce(to_jsonb(v_affiliate.financial_affiliation_status)::text,'null')
    ||',"financial_employee_category":'||coalesce(to_jsonb(v_affiliate.current_financial_category)::text,'null')
    ||',"financial_employee_category_code":'||coalesce(to_jsonb(v_affiliate.financial_employee_category_code)::text,'null')
    ||',"financial_employee_type":'||coalesce(to_jsonb(v_affiliate.financial_employee_type)::text,'null')
    ||',"financial_employment_status":'||coalesce(to_jsonb(v_affiliate.financial_employment_status)::text,'null')
    ||',"financial_profile_version":'||to_jsonb(v_affiliate.financial_profile_version)::text
    ||',"financial_union":'||coalesce(to_jsonb(v_affiliate.current_financial_union)::text,'null')
    ||',"financial_union_code":'||coalesce(to_jsonb(v_affiliate.financial_union_code)::text,'null')
    ||',"impersonation_session_id":'||coalesce(to_jsonb(v_impersonation_id::text)::text,'null')||'}';
  v_profile_fingerprint := upper(encode(extensions.digest(convert_to(v_profile_canonical,'UTF8'),'sha256'),'hex'));
  if v_snapshot.profile_fingerprint<>v_profile_fingerprint then
    raise exception 'SNAPSHOT_INVALID' using errcode='P0001';
  end if;
  if exists(
    select 1 from jsonb_array_elements(v_snapshot.eligible_rules) as candidate(value)
    where public.normalize_suti_financial_key(value->>'union')<>public.normalize_suti_financial_key(v_affiliate.current_financial_union)
       or public.normalize_suti_financial_key(value->>'category')<>public.normalize_suti_financial_key(v_affiliate.current_financial_category)
  ) then raise exception 'SNAPSHOT_INVALID' using errcode='P0001'; end if;

  select * into v_policy from public.loan_term_policy where id='primary' and enabled;
  if v_policy.id is null then raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001'; end if;
  v_policy_json := jsonb_build_object(
    'source','SUPABASE_LOAN_TERM_POLICY','standardTerms',v_policy.standard_terms,
    'customMinTerm',v_policy.custom_min_term,'customStep',v_policy.custom_step,
    'decisionReference',v_policy.decision_reference
  );
  v_policy_canonical := '{'
    ||'"customMinTerm":'||v_policy.custom_min_term::text
    ||',"customStep":'||v_policy.custom_step::text
    ||',"decisionReference":'||to_jsonb(v_policy.decision_reference)::text
    ||',"source":"SUPABASE_LOAN_TERM_POLICY"'
    ||',"standardTerms":['||array_to_string(v_policy.standard_terms,',')||']}';
  v_policy_fingerprint := upper(encode(extensions.digest(convert_to(v_policy_canonical,'UTF8'),'sha256'),'hex'));
  if v_snapshot.term_policy_fingerprint<>v_policy_fingerprint then
    raise exception 'SNAPSHOT_INVALID' using errcode='P0001';
  end if;

  v_quote := public.resolve_suti_loan_quote_contract(
    v_snapshot.eligible_rules,v_affiliate.current_financial_union,v_affiliate.current_financial_category,
    p_program_id,p_amount,p_term,v_policy_json
  );
  begin
    v_payroll := public.get_current_declared_payroll_impact((v_quote->>'paymentPerPeriod')::numeric);
  exception when others then
    v_payroll := jsonb_build_object('status','ERROR','source','SUPABASE_DECLARED_PAYROLL','guidelinePercent',30);
  end;
  return v_quote || jsonb_build_object(
    'payrollImpact',v_payroll,
    'loanSession',jsonb_build_object('id',v_snapshot.id,'expires_at',v_snapshot.expires_at,
      'financial_profile_version',v_snapshot.financial_profile_version),
    'googleResolutionCount',0
  );
end $function$

CREATE OR REPLACE FUNCTION public.resolve_program_request_workflow_state(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.program_requests%rowtype;t public.operational_request_tracking%rowtype;v_stages jsonb;v_current text;v_current_order integer;v_current_stage jsonb;v_resolved jsonb;
begin
  select * into r from public.program_requests where id=p_request_id;
  if r.id is null then raise exception 'REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if auth.role()<>'service_role' and not(
    auth.uid() is not null and (r.affiliate_id=public.get_effective_affiliate_id() or public.has_admin_permission('workflow.read') or public.has_admin_permission('program_requests.read'))
  ) then raise exception 'REQUEST_WORKFLOW_DENIED' using errcode='42501'; end if;
  if r.workflow_snapshot is null then return jsonb_build_object('available',false,'reason','WORKFLOW_SNAPSHOT_MISSING','message','Seguimiento no disponible'); end if;
  select * into t from public.operational_request_tracking where request_id=r.id;
  select coalesce(jsonb_agg(stage order by (stage->>'sort_order')::integer,stage->>'id'),'[]'::jsonb) into v_stages
  from jsonb_array_elements(r.workflow_snapshot->'stages') stage
  where case when r.status in('rejected','cancelled') then stage->>'outcome'<>'success' else stage->>'outcome'<>'failure' end;
  if t.current_stage_id is not null and exists(select 1 from jsonb_array_elements(v_stages) stage where stage->>'id'=t.current_stage_id::text) then
    v_current:=t.current_stage_id::text;
  else
    select stage->>'id' into v_current from jsonb_array_elements(v_stages) stage
    where stage->'status_references'?r.status order by (stage->>'sort_order')::integer,stage->>'id' limit 1;
  end if;
  if v_current is null then return jsonb_build_object('available',false,'reason','WORKFLOW_STATUS_UNMAPPED','message','Seguimiento no disponible'); end if;
  select (stage->>'sort_order')::integer,stage into v_current_order,v_current_stage from jsonb_array_elements(v_stages) stage where stage->>'id'=v_current;
  select coalesce(jsonb_agg(
    stage||jsonb_build_object(
      'state',case when (stage->>'sort_order')::integer<v_current_order then 'done' when stage->>'id'=v_current then 'current' else 'upcoming' end,
      'date',t.stage_dates->>(stage->>'id')
    ) order by (stage->>'sort_order')::integer,stage->>'id'
  ),'[]'::jsonb) into v_resolved from jsonb_array_elements(v_stages) stage;
  return jsonb_strip_nulls(jsonb_build_object(
    'available',true,'workflow_id',r.workflow_id,'workflow_version',r.workflow_version,
    'workflow_name',r.workflow_snapshot->>'workflow_name','workflow_description',r.workflow_snapshot->>'workflow_description',
    'request_status',r.status,'current_stage_id',v_current,'current_stage',v_current_stage,
    'active_note',nullif(v_current_stage->>'description',''),'stages',v_resolved
  ));
end $function$

CREATE OR REPLACE FUNCTION public.resolve_section_responsibility_user(p_email text)
 RETURNS TABLE(auth_user_id uuid, email text, display_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
  if not public.has_admin_permission('authorization.write') then
    raise exception 'AUTHORIZATION_DENIED' using errcode='42501';
  end if;
  select count(*) into v_count from auth.users u
   where lower(u.email)=lower(btrim(p_email)) and u.email_confirmed_at is not null;
  if v_count=0 then raise exception 'CONFIRMED_AUTH_USER_NOT_FOUND' using errcode='P0001'; end if;
  if v_count<>1 then raise exception 'AUTH_USER_EMAIL_AMBIGUOUS' using errcode='P0001'; end if;
  return query select u.id,u.email::text,
    coalesce(nullif(btrim((u.raw_user_meta_data->>'name')::text),''),split_part(u.email::text,'@',1))::text
   from auth.users u where lower(u.email)=lower(btrim(p_email)) and u.email_confirmed_at is not null;
end
$function$

CREATE OR REPLACE FUNCTION public.resolve_suti_loan_quote_contract_v1_engine(p_eligible_rules jsonb, p_financial_union text, p_financial_employee_category text, p_program_id text, p_amount numeric, p_term integer, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule jsonb;
  v_match_count integer;
  v_max_amount numeric;
  v_rate_factor numeric;
  v_rate numeric;
  v_payment_count integer;
  v_payment_period text;
  v_custom_min integer;
  v_custom_step integer;
  v_standard_terms integer[];
  v_interest numeric;
  v_fee_per_payment numeric := 15;
  v_fee_total numeric;
  v_total numeric;
  v_payment numeric;
  v_term_options jsonb;
begin
  if jsonb_typeof(p_eligible_rules) <> 'array' or jsonb_array_length(p_eligible_rules) < 1 then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end if;
  if nullif(btrim(p_financial_union),'') is null or nullif(btrim(p_financial_employee_category),'') is null then
    raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001';
  end if;
  if nullif(btrim(p_program_id),'') is null or p_amount is null or p_amount::text='NaN' or p_term is null then
    raise exception 'FINANCIAL_REQUEST_OUT_OF_RANGE' using errcode='22023';
  end if;
  if jsonb_typeof(p_policy) <> 'object'
     or p_policy->>'source' <> 'SUPABASE_LOAN_TERM_POLICY'
     or jsonb_typeof(p_policy->'standardTerms') <> 'array' then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end if;

  begin
    v_custom_min := (p_policy->>'customMinTerm')::integer;
    v_custom_step := (p_policy->>'customStep')::integer;
    select coalesce(array_agg(value::integer order by ordinal),array[]::integer[])
      into v_standard_terms
      from jsonb_array_elements_text(p_policy->'standardTerms') with ordinality as terms(value,ordinal);
  exception when others then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end;
  if v_custom_min <= 0 or v_custom_step <= 0 or cardinality(v_standard_terms) < 1 then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end if;

  select count(*) into v_match_count
  from jsonb_array_elements(p_eligible_rules) as candidate(value)
  where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
    and value->>'status'='AVAILABLE'
    and value->>'id'=p_program_id;

  if v_match_count > 0 then
    select value into v_rule
    from jsonb_array_elements(p_eligible_rules) as candidate(value)
    where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
      and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
      and value->>'status'='AVAILABLE'
      and value->>'id'=p_program_id
    limit 1;
  else
    select count(*) into v_match_count
    from jsonb_array_elements(p_eligible_rules) as candidate(value)
    where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
      and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
      and value->>'status'='AVAILABLE'
      and value->>'program_id'=p_program_id;
    if v_match_count = 1 then
      select value into v_rule
      from jsonb_array_elements(p_eligible_rules) as candidate(value)
      where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
        and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
        and value->>'status'='AVAILABLE'
        and value->>'program_id'=p_program_id
      limit 1;
    else
      v_rule := null;
    end if;
  end if;

  if v_rule is null then raise exception 'FINANCIAL_PROGRAM_NOT_ELIGIBLE' using errcode='P0001'; end if;
  if jsonb_typeof(v_rule->'max_amount') <> 'number'
     or jsonb_typeof(v_rule->'rate_factor') <> 'number'
     or jsonb_typeof(v_rule->'rate') <> 'number'
     or jsonb_typeof(v_rule->'payment_count') <> 'number'
     or nullif(btrim(v_rule->>'fund'),'') is null
     or nullif(btrim(v_rule->>'program_id'),'') is null
     or nullif(btrim(v_rule->>'payment_period'),'') is null then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end if;

  begin
    v_max_amount := (v_rule->>'max_amount')::numeric;
    v_rate_factor := (v_rule->>'rate_factor')::numeric;
    v_rate := (v_rule->>'rate')::numeric;
    v_payment_count := (v_rule->>'payment_count')::integer;
    v_payment_period := v_rule->>'payment_period';
  exception when others then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end;
  if p_amount <= 0 or p_amount > v_max_amount or p_term < v_custom_min or p_term > v_payment_count
     or mod(p_term-v_custom_min,v_custom_step) <> 0 then
    raise exception 'FINANCIAL_REQUEST_OUT_OF_RANGE' using errcode='22023';
  end if;

  -- Exact current contract: positive currency values rounded half-up to cents.
  v_interest := round(p_amount*v_rate_factor*p_term,2);
  v_fee_total := round(v_fee_per_payment*p_term,2);
  v_total := round(p_amount+v_interest+v_fee_total,2);
  v_payment := round(v_total/p_term,2);

  select coalesce(jsonb_agg(jsonb_build_object(
    'term',candidate_term,
    'paymentCount',candidate_term,
    'interest',round(p_amount*v_rate_factor*candidate_term,2),
    'administrativeFeePerPayment',v_fee_per_payment,
    'administrativeFeeTotal',round(v_fee_per_payment*candidate_term,2),
    'total',round(p_amount+round(p_amount*v_rate_factor*candidate_term,2)+round(v_fee_per_payment*candidate_term,2),2),
    'paymentPerPeriod',round(round(p_amount+round(p_amount*v_rate_factor*candidate_term,2)+round(v_fee_per_payment*candidate_term,2),2)/candidate_term,2)
  ) order by ordinal),'[]'::jsonb)
  into v_term_options
  from unnest(v_standard_terms) with ordinality as terms(candidate_term,ordinal)
  where candidate_term >= v_custom_min and candidate_term <= v_payment_count;

  return jsonb_build_object(
    'source','GOOGLE_LEGACY','action','quote','amount',p_amount,
    'paymentCount',p_term,'paymentPeriod',v_payment_period,
    'rate',v_rate,'ratePeriod',v_payment_period,
    'interest',v_interest,'administrativeFeePerPayment',v_fee_per_payment,
    'administrativeFeeTotal',v_fee_total,'total',v_total,
    'paymentPerPeriod',v_payment,'fund',v_rule->>'fund',
    'program',v_rule->>'program_id','maxAmount',v_max_amount,'maxTerm',v_payment_count,
    'termOptions',v_term_options,
    'customTerm',jsonb_build_object('min',v_custom_min,'max',v_payment_count,'step',v_custom_step),
    'eligibility',jsonb_build_object('status','AVAILABLE','eligible',true),
    'administrativeFeeRule','$15 por pago',
    'administrativeFeeVersion','LEGACY_EQUIVALENCE_2026-08-23',
    'criteria',jsonb_build_object('termLabel',v_rule->>'term_label'),
    'resolved_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
end $function$

CREATE OR REPLACE FUNCTION public.respond_marketplace_quote(p_quote_id uuid, p_amount numeric, p_note text, p_valid_until date)
 RETURNS marketplace_quote_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.marketplace_quote_requests%rowtype;
begin
  select * into v_row from public.marketplace_quote_requests where id=p_quote_id;
  if v_row.id is null or not (public.is_marketplace_company_member(v_row.company_id,'quotes') or public.has_admin_permission('marketplace.quotes.write')) then raise exception 'QUOTE_DENIED' using errcode='P0001'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'QUOTE_AMOUNT_INVALID' using errcode='22023'; end if;
  update public.marketplace_quote_requests set status='quoted',quoted_amount=p_amount,quote_note=nullif(btrim(coalesce(p_note,'')),''),valid_until=p_valid_until,quoted_by_auth_user_id=(select auth.uid()),quoted_at=now(),updated_at=now() where id=p_quote_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.respond_program_request_quote(p_request_id uuid, p_amount numeric, p_note text, p_valid_until date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.program_requests%rowtype;
begin
  select * into v_row from public.program_requests where id=p_request_id;
  if v_row.id is null or v_row.request_type<>'quote' then raise exception 'QUOTE_NOT_FOUND' using errcode='P0001'; end if;
  if not (public.has_admin_permission('program_requests.write') or (v_row.company_id is not null and public.is_marketplace_company_member(v_row.company_id,'quotes'))) then
    raise exception 'QUOTE_DENIED' using errcode='42501';
  end if;
  if p_amount is null or p_amount<=0 then raise exception 'QUOTE_AMOUNT_INVALID' using errcode='22023'; end if;
  update public.program_requests set status='approved',quoted_amount=p_amount,quote_note=left(nullif(btrim(coalesce(p_note,'')),''),2000),
    valid_until=p_valid_until,responded_by_auth_user_id=(select auth.uid()),responded_at=now(),seen_at=null,updated_at=now()
  where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.restore_admin_affiliate(p_affiliate_id uuid, p_expected_updated_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.affiliates%rowtype;v_new public.affiliates%rowtype;v_reason text:=btrim(coalesce(p_reason,''));v_email text;v_eligibility text;
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'AFFILIATE_RESTORE_REASON_REQUIRED' using errcode='22023'; end if;
  select * into v_old from public.affiliates where id=p_affiliate_id for update;
  if v_old.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.updated_at is distinct from p_expected_updated_at then raise exception 'AFFILIATE_VERSION_CONFLICT' using errcode='PT409'; end if;
  if not v_old.is_archived then raise exception 'AFFILIATE_NOT_ARCHIVED' using errcode='22023'; end if;
  v_email:=v_old.historical_email_normalized;
  v_eligibility:=case when v_email is null then 'missing_email'
    when v_email!~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then 'invalid_email'
    when exists(select 1 from public.affiliates a where a.id<>p_affiliate_id and a.historical_email_normalized=v_email) then 'duplicate_email'
    else 'eligible' end;
  update public.affiliates set is_archived=false,archived_at=null,archived_by_auth_user_id=null,
    archive_reason=null,archive_previous_status_raw=null,restored_at=now(),
    restored_by_auth_user_id=auth.uid(),restore_reason=v_reason,auth_eligibility=v_eligibility,
    auth_ineligibility_reason=case when v_eligibility='eligible' then null else v_eligibility end
  where id=p_affiliate_id returning * into v_new;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(p_affiliate_id,auth.uid(),'RESTORE',
    jsonb_build_object('is_archived',true,'archived_at',v_old.archived_at,'archive_previous_status_raw',v_old.archive_previous_status_raw),
    jsonb_build_object('is_archived',false,'restored_at',v_new.restored_at,'affiliate_status_raw',v_new.affiliate_status_raw,'auth_eligibility',v_new.auth_eligibility),
    array['is_archived','restored_at','restored_by_auth_user_id','restore_reason','auth_eligibility'],v_reason);
  return public.get_admin_affiliate_workbench(p_affiliate_id);
end $function$

CREATE OR REPLACE FUNCTION public.restore_document_requirement_rule(p_scope_type text, p_scope_key text, p_document_type_id uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_scope jsonb;v_before jsonb;v_id uuid;v_type text;v_key text;
begin
  if not public.has_admin_permission('documents.write') then raise exception 'DOCUMENT_CONFIG_DENIED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_reason,'')))<8 then raise exception 'DOCUMENT_CONFIG_REASON_REQUIRED' using errcode='22023'; end if;
  v_scope:=public.assert_document_requirement_scope(p_scope_type,p_scope_key);v_type:=v_scope->>'scope_type';v_key:=v_scope->>'scope_key';
  select r.id,to_jsonb(r) into v_id,v_before from public.program_document_requirements r where r.scope_type=v_type and r.scope_key=v_key and r.document_type_id=p_document_type_id;
  if v_id is null then raise exception 'DOCUMENT_RULE_NOT_FOUND' using errcode='P0001'; end if;
  delete from public.program_document_requirements where id=v_id;
  insert into public.document_configuration_audit_log(actor_auth_user_id,resource_type,resource_id,scope_type,scope_key,document_type_id,action,reason,before_state)
  values(auth.uid(),'REQUIREMENT',v_id,v_type,v_key,p_document_type_id,'RESTORE',btrim(p_reason),v_before);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.review_affiliate_document(p_document_id uuid, p_status text, p_observation text DEFAULT NULL::text)
 RETURNS affiliate_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_doc public.affiliate_documents%rowtype; begin
  if not public.has_admin_permission('documents.write') then raise exception 'DOCUMENT_REVIEW_DENIED' using errcode='42501'; end if;
  if p_status not in('VERIFIED','REJECTED','REUPLOAD_REQUIRED') then raise exception 'INVALID_REVIEW_STATUS' using errcode='22023'; end if;
  update public.affiliate_documents set status=p_status,review_observation=nullif(left(btrim(coalesce(p_observation,'')),1000),''),reviewed_by_auth_user_id=auth.uid(),reviewed_at=now()
  where id=p_document_id and status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED') returning * into v_doc;
  if v_doc.id is null then raise exception 'DOCUMENT_NOT_REVIEWABLE' using errcode='P0001'; end if;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_doc.affiliate_id,'affiliate_documents','REVIEW',v_doc.id,jsonb_build_object('status',p_status,'has_observation',p_observation is not null));
  return v_doc;
end $function$

CREATE OR REPLACE FUNCTION public.review_company_popup_proposal(p_proposal_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS company_popup_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_proposal public.company_popup_proposals%rowtype; v_popup_id uuid;
begin
  if not public.has_admin_permission('popups.write') then raise exception 'ADMIN_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_proposal from public.company_popup_proposals where id=p_proposal_id for update;
  if v_proposal.id is null then raise exception 'POPUP_PROPOSAL_NOT_FOUND' using errcode='P0002'; end if;
  if v_proposal.status<>'pending' then raise exception 'POPUP_PROPOSAL_ALREADY_REVIEWED' using errcode='P0001'; end if;
  if p_approve then
    insert into public.popups(title,body,image_asset_id,action_label,action_url,audience_raw,enabled,start_at,end_at,sort_order,record_origin)
    values(v_proposal.title,v_proposal.body,v_proposal.image_asset_id,v_proposal.action_label,
      case when v_proposal.action_type='url' then v_proposal.action_target else null end,
      v_proposal.audience_raw,false,v_proposal.start_at,v_proposal.end_at,
      coalesce((select max(sort_order)+1 from public.popups),1),'ADMIN_H009') returning id into v_popup_id;
    update public.company_popup_proposals set status='approved',popup_id=v_popup_id,reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=null where id=p_proposal_id returning * into v_proposal;
  else
    if nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception 'REJECTION_REASON_REQUIRED' using errcode='22023'; end if;
    update public.company_popup_proposals set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=btrim(p_reason) where id=p_proposal_id returning * into v_proposal;
  end if;
  return v_proposal;
end $function$

CREATE OR REPLACE FUNCTION public.revoke_admin_assignment(p_auth_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role uuid;
begin
  if not public.has_admin_permission('authorization.write') then raise exception 'AUTHORIZATION_DENIED' using errcode='42501'; end if;
  select role_id into v_role from public.admin_assignments where auth_user_id=p_auth_user_id;
  if v_role is null then raise exception 'ADMIN_ASSIGNMENT_NOT_FOUND' using errcode='P0001'; end if;
  perform public.assign_admin_role(p_auth_user_id,v_role,false);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.revoke_section_responsibilities(p_auth_user_id uuid, p_section_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_count integer;
begin
  if v_actor is null or not public.has_admin_permission('authorization.write') then
    raise exception 'AUTHORIZATION_DENIED' using errcode='42501';
  end if;
  if p_auth_user_id=v_actor then raise exception 'SELF_ASSIGNMENT_DENIED' using errcode='42501'; end if;
  update public.admin_section_responsibilities
     set enabled=false,updated_at=now(),revoked_at=now(),revoked_by_auth_user_id=v_actor
   where auth_user_id=p_auth_user_id and section_key=p_section_key and enabled;
  get diagnostics v_count=row_count;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'admin_section_responsibilities','REVOKE',p_auth_user_id::text,'SUCCESS',
    jsonb_build_object('section_key',p_section_key,'disabled_actions',v_count));
end
$function$

CREATE OR REPLACE FUNCTION public.save_admin_role(p_role_id uuid, p_name text, p_description text, p_permissions text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_id uuid;v_allowed text[];v_before jsonb;v_after jsonb;
begin
  if v_actor is null or not public.has_admin_permission('authorization.write') then raise exception 'AUTHORIZATION_DENIED' using errcode='42501'; end if;
  select array_agg(rp.permission order by rp.permission) into v_allowed
  from public.admin_role_permissions rp join public.admin_roles r on r.id=rp.role_id where r.code='principal_admin';
  if p_permissions is null or exists(select 1 from unnest(p_permissions) p where not(p=any(coalesce(v_allowed,'{}')))) then
    raise exception 'INVALID_PERMISSION' using errcode='22023';
  end if;
  if p_role_id is null then
    insert into public.admin_roles(code,name,description)
    values('role_'||replace(extensions.gen_random_uuid()::text,'-',''),btrim(p_name),coalesce(p_description,'')) returning id into v_id;
  else
    select to_jsonb(r) into v_before from public.admin_roles r where r.id=p_role_id for update;
    if coalesce((v_before->>'system_role')::boolean,false) then raise exception 'SYSTEM_ROLE_IMMUTABLE' using errcode='P0001'; end if;
    update public.admin_roles set name=btrim(p_name),description=coalesce(p_description,''),updated_at=now()
    where id=p_role_id returning id into v_id;
    if v_id is null then raise exception 'ROLE_NOT_FOUND' using errcode='P0001'; end if;
    delete from public.admin_role_permissions where role_id=v_id;
  end if;
  insert into public.admin_role_permissions(role_id,permission)
  select v_id,p from(select distinct unnest(p_permissions) p) q;
  update public.admin_assignments a set
    permissions=(select coalesce(array_agg(permission order by permission),'{}') from public.admin_role_permissions where role_id=v_id),updated_at=now()
  where role_id=v_id;
  if not ('affiliates.impersonate'=any(coalesce(p_permissions,'{}'))) then
    with closed as (
      update public.impersonation_sessions s set ended_at=now(),ended_by_auth_user_id=v_actor
      where s.ended_at is null and exists(select 1 from public.admin_assignments a where a.auth_user_id=s.actor_real_auth_user_id and a.role_id=v_id)
      returning s.*
    ) insert into public.identity_audit_log(actor_real_auth_user_id,usuario_contexto_affiliate_id,action,result,details)
      select v_actor,c.usuario_contexto_affiliate_id,'IMPERSONATION_STOPPED','SUCCESS',jsonb_build_object(
        'session_id',c.id,'reason',c.reason,'automatic',true,'cause','ROLE_PERMISSION_REVOKED','session_actor_auth_user_id',c.actor_real_auth_user_id)
      from closed c;
  end if;
  select to_jsonb(r) into v_after from public.admin_roles r where r.id=v_id;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'admin_roles',case when p_role_id is null then 'INSERT' else 'UPDATE' end,v_id::text,'SUCCESS',
    jsonb_build_object('before',v_before,'after',v_after,'permissions',to_jsonb(p_permissions)));
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_affiliate_bank_account(p_id uuid, p_holder text, p_bank text, p_clabe text, p_account text, p_primary boolean)
 RETURNS affiliate_bank_accounts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_affiliate uuid;v_row public.affiliate_bank_accounts%rowtype;v_action text; begin
  v_affiliate:=public.get_effective_affiliate_id();
  if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_holder,''))) not between 2 and 160 or length(btrim(coalesce(p_bank,''))) not between 2 and 100
    or coalesce(p_account,'') !~ '^[0-9]{4,20}$' or (p_clabe is not null and p_clabe<>'' and p_clabe !~ '^[0-9]{18}$')
  then raise exception 'INVALID_BANK_ACCOUNT' using errcode='22023'; end if;
  if p_id is null then
    insert into public.affiliate_bank_accounts(affiliate_id,account_holder,bank_name,clabe,account_number,is_primary,data_status,incomplete_fields,source_kind,user_maintained_at)
    values(v_affiliate,btrim(p_holder),btrim(p_bank),nullif(p_clabe,''),p_account,false,'COMPLETE','{}','USER_MAINTAINED',now()) returning * into v_row;
    v_action:='BANK_ACCOUNT_CREATED';
  else
    update public.affiliate_bank_accounts set account_holder=btrim(p_holder),bank_name=btrim(p_bank),clabe=nullif(p_clabe,''),account_number=p_account,
      data_status='COMPLETE',incomplete_fields='{}',user_maintained_at=now(),updated_at=now()
    where id=p_id and affiliate_id=v_affiliate returning * into v_row;
    v_action:='BANK_ACCOUNT_UPDATED';
  end if;
  if v_row.id is null then raise exception 'BANK_ACCOUNT_NOT_FOUND' using errcode='P0001'; end if;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_affiliate,'affiliate_bank_accounts',v_action,v_row.id,jsonb_build_object('has_clabe',v_row.clabe is not null,'has_account',true,'completed',true));
  if p_primary then
    update public.affiliate_bank_accounts set is_primary=false,updated_at=now() where affiliate_id=v_affiliate and is_primary and id<>v_row.id;
    update public.affiliate_bank_accounts set is_primary=true,updated_at=now() where id=v_row.id returning * into v_row;
    insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id) values(auth.uid(),v_affiliate,'affiliate_bank_accounts','BANK_ACCOUNT_SET_PRIMARY',v_row.id);
  end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.save_affiliate_deposit_account(p_id uuid, p_bank text, p_card text, p_clabe text)
 RETURNS affiliate_bank_accounts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_row public.affiliate_bank_accounts%rowtype;
  v_action text;
  v_bank text:=btrim(coalesce(p_bank,''));
  v_card text:=nullif(btrim(coalesce(p_card,'')),'');
  v_clabe text:=nullif(btrim(coalesce(p_clabe,'')),'');
begin
  select * into v_affiliate from public.affiliates where id=public.get_effective_affiliate_id();
  if auth.uid() is null or v_affiliate.id is null then
    raise exception 'AFFILIATE_REQUIRED' using errcode='42501';
  end if;
  if length(v_bank) not between 2 and 100 then
    raise exception 'INVALID_DEPOSIT_BANK' using errcode='22023';
  end if;
  if v_card is null and v_clabe is null then
    raise exception 'DEPOSIT_INSTRUMENT_REQUIRED' using errcode='22023';
  end if;
  if v_card is not null and v_card !~ '^[0-9]{16}$' then
    raise exception 'INVALID_DEPOSIT_CARD' using errcode='22023';
  end if;
  if v_clabe is not null and not public.is_valid_clabe(v_clabe) then
    raise exception 'INVALID_DEPOSIT_CLABE' using errcode='22023';
  end if;
  if length(btrim(coalesce(v_affiliate.full_name,''))) not between 2 and 160 then
    raise exception 'ACCOUNT_HOLDER_REQUIRED' using errcode='22023';
  end if;

  if p_id is null then
    insert into public.affiliate_bank_accounts(
      affiliate_id,account_holder,bank_name,clabe,account_number,card_number,is_primary,
      data_status,incomplete_fields,source_kind,user_maintained_at
    ) values(
      v_affiliate.id,btrim(v_affiliate.full_name),v_bank,v_clabe,null,v_card,false,
      'COMPLETE','{}','USER_MAINTAINED',now()
    ) returning * into v_row;
    v_action:='BANK_ACCOUNT_CREATED';
  else
    update public.affiliate_bank_accounts set
      account_holder=btrim(v_affiliate.full_name),bank_name=v_bank,clabe=v_clabe,card_number=v_card,
      data_status='COMPLETE',incomplete_fields='{}',user_maintained_at=now(),updated_at=now()
    where id=p_id and affiliate_id=v_affiliate.id returning * into v_row;
    v_action:='BANK_ACCOUNT_UPDATED';
  end if;
  if v_row.id is null then
    raise exception 'BANK_ACCOUNT_NOT_FOUND' using errcode='P0001';
  end if;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_affiliate.id,'affiliate_bank_accounts',v_action,v_row.id,
    jsonb_build_object(
      'has_clabe',v_clabe is not null,
      'has_card',v_card is not null,
      'completed_for_deposit',true
    ));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.save_current_declared_payroll(p_gross_pay_per_fortnight numeric, p_deductions_per_fortnight numeric, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid(); v_affiliate_id uuid:=public.get_effective_affiliate_id();
  v_existing public.affiliate_payroll_declarations%rowtype; v_saved public.affiliate_payroll_declarations%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_affiliate_id is null then raise exception 'AFFILIATE_IDENTITY_REQUIRED' using errcode='42501'; end if;
  select * into v_ctx from public.impersonation_sessions where actor_real_auth_user_id=v_actor and ended_at is null and expires_at>now() limit 1;
  if v_ctx.id is not null and (not public.is_active_admin() or v_ctx.usuario_contexto_affiliate_id is distinct from v_affiliate_id) then
    raise exception 'PAYROLL_DECLARATION_IMPERSONATION_DENIED' using errcode='42501';
  end if;
  if p_gross_pay_per_fortnight is null or p_gross_pay_per_fortnight<=0 or p_gross_pay_per_fortnight>1000000 or
     p_deductions_per_fortnight is null or p_deductions_per_fortnight<0 or p_deductions_per_fortnight>=p_gross_pay_per_fortnight then
    raise exception 'PAYROLL_DECLARATION_INVALID' using errcode='22023';
  end if;
  select * into v_existing from public.affiliate_payroll_declarations where affiliate_id=v_affiliate_id for update;
  if v_existing.affiliate_id is null then
    if coalesce(p_expected_version,0)<>0 then raise exception 'PAYROLL_DECLARATION_VERSION_CONFLICT' using errcode='PT409'; end if;
    insert into public.affiliate_payroll_declarations(affiliate_id,gross_pay_per_fortnight,deductions_per_fortnight,updated_by_auth_user_id)
    values(v_affiliate_id,round(p_gross_pay_per_fortnight,2),round(p_deductions_per_fortnight,2),v_actor) returning * into v_saved;
  else
    if p_expected_version is null or p_expected_version<>v_existing.version then raise exception 'PAYROLL_DECLARATION_VERSION_CONFLICT' using errcode='PT409'; end if;
    update public.affiliate_payroll_declarations set gross_pay_per_fortnight=round(p_gross_pay_per_fortnight,2),
      deductions_per_fortnight=round(p_deductions_per_fortnight,2),version=version+1,updated_at=now(),updated_by_auth_user_id=v_actor
      where affiliate_id=v_affiliate_id returning * into v_saved;
  end if;
  insert into public.affiliate_payroll_declaration_audit(
    affiliate_id,actor_real_auth_user_id,action,old_gross_pay_per_fortnight,old_deductions_per_fortnight,
    new_gross_pay_per_fortnight,new_deductions_per_fortnight,declaration_version,
    usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason
  ) values(v_affiliate_id,v_actor,case when v_existing.affiliate_id is null then 'INSERT' else 'UPDATE' end,
    v_existing.gross_pay_per_fortnight,v_existing.deductions_per_fortnight,v_saved.gross_pay_per_fortnight,
    v_saved.deductions_per_fortnight,v_saved.version,case when v_ctx.id is null then null else v_affiliate_id end,v_ctx.id,v_ctx.reason);
  return public.get_current_declared_payroll();
end $function$

CREATE OR REPLACE FUNCTION public.save_current_notification_phone(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_affiliate uuid; v_phone text;
begin
  v_affiliate:=public.get_effective_affiliate_id();
  v_phone:=regexp_replace(coalesce(p_phone,''),'\D','','g');
  if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  if v_phone !~ '^[0-9]{10}$' then raise exception 'INVALID_NOTIFICATION_PHONE' using errcode='22023'; end if;
  update public.affiliates set notification_phone=v_phone where id=v_affiliate;
  if not found then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,metadata)
  values(auth.uid(),v_affiliate,'affiliate_notification_phone','NOTIFICATION_PHONE_CONFIRMED',jsonb_build_object('phone_last4',right(v_phone,4)));
  return v_phone;
end $function$

CREATE OR REPLACE FUNCTION public.save_document_requirement_rule(p_scope_type text, p_scope_key text, p_document_type_id uuid, p_effect text, p_required boolean, p_allow_verified_reuse boolean, p_sort_order integer, p_reason text)
 RETURNS program_document_requirements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_scope jsonb;v_before jsonb;v_row public.program_document_requirements%rowtype;v_type text;v_key text;v_program text;v_membership uuid;
begin
  if not public.has_admin_permission('documents.write') then raise exception 'DOCUMENT_CONFIG_DENIED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_reason,'')))<8 then raise exception 'DOCUMENT_CONFIG_REASON_REQUIRED' using errcode='22023'; end if;
  if upper(p_effect) not in('INCLUDE','EXCLUDE') or p_sort_order<1 or not exists(select 1 from public.document_types where id=p_document_type_id) then raise exception 'INVALID_DOCUMENT_RULE' using errcode='22023'; end if;
  v_scope:=public.assert_document_requirement_scope(p_scope_type,p_scope_key);v_type:=v_scope->>'scope_type';v_key:=v_scope->>'scope_key';
  select to_jsonb(r) into v_before from public.program_document_requirements r where r.scope_type=v_type and r.scope_key=v_key and r.document_type_id=p_document_type_id;
  v_program:=case when v_type='MEMBERSHIP' then 'membership' when v_type='PROGRAM' and v_key='prestamo' then 'prestamo' else lower(v_type)||':'||v_key end;
  v_membership:=case when v_type='MEMBERSHIP' then v_key::uuid else null end;
  insert into public.program_document_requirements(program_id,membership_offering_id,document_type_id,required,allow_verified_reuse,sort_order,enabled,scope_type,scope_key,effect)
  values(v_program,v_membership,p_document_type_id,case when upper(p_effect)='EXCLUDE' then false else coalesce(p_required,true) end,coalesce(p_allow_verified_reuse,true),p_sort_order,true,v_type,v_key,upper(p_effect))
  on conflict(scope_type,scope_key,document_type_id) do update set required=excluded.required,allow_verified_reuse=excluded.allow_verified_reuse,sort_order=excluded.sort_order,enabled=true,effect=excluded.effect
  returning * into v_row;
  insert into public.document_configuration_audit_log(actor_auth_user_id,resource_type,resource_id,scope_type,scope_key,document_type_id,action,reason,before_state,after_state)
  values(auth.uid(),'REQUIREMENT',v_row.id,v_type,v_key,p_document_type_id,upper(p_effect),btrim(p_reason),v_before,to_jsonb(v_row));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.save_document_type_configuration(p_value jsonb, p_reason text)
 RETURNS document_types
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;v_before jsonb;v_row public.document_types%rowtype;v_code text:=lower(btrim(coalesce(p_value->>'code','')));v_label text:=btrim(coalesce(p_value->>'label',''));
begin
  if not public.has_admin_permission('documents.write') then raise exception 'DOCUMENT_CONFIG_DENIED' using errcode='42501'; end if;
  if length(btrim(coalesce(p_reason,'')))<8 then raise exception 'DOCUMENT_CONFIG_REASON_REQUIRED' using errcode='22023'; end if;
  if nullif(p_value->>'id','') is not null then v_id:=(p_value->>'id')::uuid; end if;
  if v_code!~'^[a-z][a-z0-9_]{1,63}$' or length(v_label) not between 1 and 100 then raise exception 'INVALID_DOCUMENT_TYPE' using errcode='22023'; end if;
  if v_id is not null then select to_jsonb(d) into v_before from public.document_types d where d.id=v_id; end if;
  if v_id is null then
    insert into public.document_types(code,label,description,icon,required_by_default,accepted_mime_types,enabled,sort_order,system_type,camera_allowed,file_upload_allowed,max_file_size_bytes)
    values(v_code,v_label,coalesce(p_value->>'description',''),coalesce(nullif(p_value->>'icon',''),'doc'),coalesce((p_value->>'required_by_default')::boolean,false),
      array(select jsonb_array_elements_text(p_value->'accepted_mime_types')),coalesce((p_value->>'enabled')::boolean,true),coalesce((p_value->>'sort_order')::integer,1),false,
      coalesce((p_value->>'camera_allowed')::boolean,true),coalesce((p_value->>'file_upload_allowed')::boolean,true),coalesce((p_value->>'max_file_size_bytes')::bigint,10485760)) returning * into v_row;
  else
    update public.document_types set code=v_code,label=v_label,description=coalesce(p_value->>'description',''),icon=coalesce(nullif(p_value->>'icon',''),'doc'),
      required_by_default=coalesce((p_value->>'required_by_default')::boolean,false),accepted_mime_types=array(select jsonb_array_elements_text(p_value->'accepted_mime_types')),
      enabled=coalesce((p_value->>'enabled')::boolean,true),sort_order=coalesce((p_value->>'sort_order')::integer,sort_order),
      camera_allowed=coalesce((p_value->>'camera_allowed')::boolean,camera_allowed),file_upload_allowed=coalesce((p_value->>'file_upload_allowed')::boolean,file_upload_allowed),
      max_file_size_bytes=coalesce((p_value->>'max_file_size_bytes')::bigint,max_file_size_bytes)
    where id=v_id returning * into v_row;
  end if;
  if v_row.id is null then raise exception 'DOCUMENT_TYPE_NOT_FOUND' using errcode='P0001'; end if;
  insert into public.document_configuration_audit_log(actor_auth_user_id,resource_type,resource_id,action,reason,before_state,after_state)
  values(auth.uid(),'DOCUMENT_TYPE',v_row.id,case when v_before is null then 'CREATE' when v_row.enabled then 'UPDATE' else 'DEACTIVATE' end,btrim(p_reason),v_before,to_jsonb(v_row));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.save_financial_fund(p_id uuid, p_program_id text, p_code text, p_name text, p_enabled boolean, p_publication_status text, p_sort_order integer, p_reason text, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_old public.financial_funds%rowtype; v_new public.financial_funds%rowtype; v_batch uuid;
begin
  if not public.has_admin_permission('financial_programs.write') then raise exception 'FINANCIAL_PROGRAMS_WRITE_REQUIRED' using errcode='42501'; end if;
  if p_confirmation<>'CONFIRMAR' or length(btrim(coalesce(p_reason,'')))<8 or coalesce(p_code,'')!~'^[a-z0-9][a-z0-9_-]{1,99}$'
     or length(btrim(coalesce(p_name,'')))<2 or p_publication_status not in('DRAFT','PUBLISHED','UNPUBLISHED') or p_sort_order not between 0 and 10000
     or not exists(select 1 from public.financial_programs where id=p_program_id) then
    raise exception 'FINANCIAL_FUND_CHANGE_INVALID' using errcode='22023';
  end if;
  select active_import_batch_id into v_batch from public.financial_criteria_authority where id='primary' and authority='SUPABASE';
  if v_batch is null then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  if p_id is not null then select * into v_old from public.financial_funds where id=p_id for update; end if;
  if p_id is not null and v_old.id is null then raise exception 'FINANCIAL_FUND_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.id is not null and v_old.program_id<>p_program_id and exists(select 1 from public.financial_rules where fund_id=v_old.id) then
    raise exception 'FINANCIAL_FUND_REASSOCIATION_BLOCKED' using errcode='P0001';
  end if;
  if p_id is null then
    insert into public.financial_funds(program_id,code,name,enabled,publication_status,sort_order,imported_batch_id,updated_by)
    values(p_program_id,p_code,btrim(p_name),p_enabled,p_publication_status,p_sort_order,v_batch,auth.uid()) returning * into v_new;
  else
    update public.financial_funds set program_id=p_program_id,code=p_code,name=btrim(p_name),enabled=p_enabled,
      publication_status=p_publication_status,sort_order=p_sort_order,version=version+1,updated_at=now(),updated_by=auth.uid()
    where id=p_id returning * into v_new;
  end if;
  insert into public.financial_configuration_audit(actor_auth_user_id,resource_type,resource_id,action,old_value,new_value,reason)
  values(auth.uid(),'FUND',v_new.id::text,case when v_old.id is null then 'CREATE' else 'UPDATE' end,
    case when v_old.id is null then null else to_jsonb(v_old) end,to_jsonb(v_new),btrim(p_reason));
  update public.financial_session_snapshots set invalidated_at=now(),invalidation_reason='FINANCIAL_FUND_CHANGED' where invalidated_at is null;
  return to_jsonb(v_new);
end $function$

CREATE OR REPLACE FUNCTION public.save_financial_program(p_id text, p_name text, p_description text, p_enabled boolean, p_publication_status text, p_sort_order integer, p_reason text, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_old public.financial_programs%rowtype; v_new public.financial_programs%rowtype;
begin
  if not public.has_admin_permission('financial_programs.write') then raise exception 'FINANCIAL_PROGRAMS_WRITE_REQUIRED' using errcode='42501'; end if;
  if p_confirmation<>'CONFIRMAR' or length(btrim(coalesce(p_reason,'')))<8 or coalesce(p_id,'')!~'^[a-z][a-z0-9_-]{1,49}$'
     or length(btrim(coalesce(p_name,'')))<2 or p_publication_status not in('DRAFT','PUBLISHED','UNPUBLISHED') or p_sort_order not between 0 and 10000 then
    raise exception 'FINANCIAL_PROGRAM_CHANGE_INVALID' using errcode='22023';
  end if;
  select * into v_old from public.financial_programs where id=p_id for update;
  insert into public.financial_programs(id,name,description,enabled,publication_status,sort_order,updated_by)
  values(p_id,btrim(p_name),coalesce(p_description,''),p_enabled,p_publication_status,p_sort_order,auth.uid())
  on conflict(id) do update set name=excluded.name,description=excluded.description,enabled=excluded.enabled,
    publication_status=excluded.publication_status,sort_order=excluded.sort_order,version=public.financial_programs.version+1,
    updated_at=now(),updated_by=auth.uid() returning * into v_new;
  insert into public.financial_configuration_audit(actor_auth_user_id,resource_type,resource_id,action,old_value,new_value,reason)
  values(auth.uid(),'PROGRAM',v_new.id,case when v_old.id is null then 'CREATE' else 'UPDATE' end,
    case when v_old.id is null then null else to_jsonb(v_old) end,to_jsonb(v_new),btrim(p_reason));
  update public.financial_session_snapshots set invalidated_at=now(),invalidation_reason='FINANCIAL_PROGRAM_CHANGED' where invalidated_at is null;
  return to_jsonb(v_new);
end $function$

CREATE OR REPLACE FUNCTION public.save_financial_rule_draft(p_existing_rule_id uuid, p_fund_id uuid, p_union_code text, p_category_code text, p_max_amount numeric, p_raw_rate numeric, p_term_label text, p_payment_count integer, p_max_term integer, p_available_on date, p_visibility_mode text, p_reason text, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.financial_rules%rowtype; v_new public.financial_rules%rowtype; v_fund public.financial_funds%rowtype;
  v_union_label text; v_category_label text; v_lineage uuid; v_version integer; v_batch uuid;
begin
  if not public.has_admin_permission('financial_rules.write') then raise exception 'FINANCIAL_RULES_WRITE_REQUIRED' using errcode='42501'; end if;
  if not public.has_admin_permission('financial_rates.write') then raise exception 'FINANCIAL_RATES_WRITE_REQUIRED' using errcode='42501'; end if;
  if p_confirmation<>'CONFIRMAR' or length(btrim(coalesce(p_reason,'')))<8 or p_max_amount<=0 or p_raw_rate<0
     or p_payment_count<=0 or p_max_term<=0 or length(btrim(coalesce(p_term_label,'')))<1
     or p_visibility_mode not in('AUTO','MOSTRAR','OCULTAR') then raise exception 'FINANCIAL_RULE_CHANGE_INVALID' using errcode='22023'; end if;
  select * into v_fund from public.financial_funds where id=p_fund_id and enabled;
  if v_fund.id is null then raise exception 'FINANCIAL_FUND_NOT_FOUND' using errcode='P0001'; end if;
  select label into v_union_label from public.segmentation_catalog_entries where catalog_type='union' and code=p_union_code and enabled;
  select label into v_category_label from public.segmentation_catalog_entries where catalog_type='employment_category' and code=p_category_code and enabled;
  if v_union_label is null or v_category_label is null then raise exception 'FINANCIAL_SEGMENTATION_INVALID' using errcode='22023'; end if;
  select active_import_batch_id into v_batch from public.financial_criteria_authority where id='primary' and authority='SUPABASE';
  if v_batch is null then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  if p_existing_rule_id is not null then
    select * into v_old from public.financial_rules where id=p_existing_rule_id;
    if v_old.id is null then raise exception 'FINANCIAL_RULE_NOT_FOUND' using errcode='P0001'; end if;
    v_lineage:=v_old.lineage_id; select coalesce(max(version),0)+1 into v_version from public.financial_rules where lineage_id=v_lineage;
  else v_lineage:=extensions.gen_random_uuid();v_version:=1; end if;
  insert into public.financial_rules(lineage_id,version,supersedes_rule_id,program_id,fund_id,financial_union_code,financial_union_label,
    financial_employee_category_code,financial_employee_category_label,max_amount,raw_rate,term_label,payment_count,max_term,
    available_on,visibility_mode,lifecycle_status,imported_batch_id,created_by)
  values(v_lineage,v_version,v_old.id,v_fund.program_id,v_fund.id,p_union_code,v_union_label,p_category_code,v_category_label,
    p_max_amount,p_raw_rate,btrim(p_term_label),p_payment_count,p_max_term,p_available_on,p_visibility_mode,'DRAFT',v_batch,auth.uid()) returning * into v_new;
  insert into public.financial_configuration_audit(actor_auth_user_id,resource_type,resource_id,action,old_value,new_value,reason)
  values(auth.uid(),'RULE',v_new.id::text,'DRAFT_CREATE',case when v_old.id is null then null else to_jsonb(v_old) end,to_jsonb(v_new),btrim(p_reason));
  return to_jsonb(v_new);
end $function$

CREATE OR REPLACE FUNCTION public.save_program_catalog_item(p_item_id uuid, p_payload jsonb, p_asset_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=(select auth.uid());
  v_before public.program_catalog_items%rowtype;
  v_after public.program_catalog_items%rowtype;
  v_id uuid;
  v_program text:=btrim(coalesce(p_payload->>'program_key',''));
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_description text:=nullif(btrim(coalesce(p_payload->>'description','')),'');
  v_category text:=nullif(btrim(coalesce(p_payload->>'category_raw','')),'');
  v_price numeric;
  v_quote boolean;
  v_mode text;
  v_sold boolean;
  v_enabled boolean;
  v_sort integer;
  v_existing_asset_count integer:=0;
  v_requested_asset_count integer:=0;
  v_allowed_asset_count integer:=8;
  v_link jsonb;
  v_link_id uuid;
  v_public_asset_id uuid;
  v_kept uuid[]:='{}'::uuid[];
  v_position integer:=0;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then
    raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object'
     or p_asset_links is null or jsonb_typeof(p_asset_links)<>'array' then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_payload) k
    where k not in('program_key','name','description','category_raw','price_cash','requires_quote','commercial_mode','sold','enabled','sort_order')
  ) then
    raise exception 'PROGRAM_CATALOG_FIELD_NOT_EDITABLE' using errcode='22023';
  end if;

  if p_item_id is not null then
    select * into v_before from public.program_catalog_items where id=p_item_id for update;
    if v_before.id is null then raise exception 'PROGRAM_CATALOG_ITEM_NOT_FOUND' using errcode='P0001'; end if;
    select count(*)::integer into v_existing_asset_count
    from public.program_catalog_item_assets where item_id=p_item_id and enabled;
    v_allowed_asset_count:=greatest(8,v_existing_asset_count);
  end if;

  begin
    v_price:=nullif(p_payload->>'price_cash','')::numeric;
    v_quote:=(p_payload->>'requires_quote')::boolean;
    v_enabled:=(p_payload->>'enabled')::boolean;
    v_sort:=(p_payload->>'sort_order')::integer;
    v_mode:=nullif(btrim(coalesce(p_payload->>'commercial_mode','')),'');
    v_sold:=case when p_payload ? 'sold' then (p_payload->>'sold')::boolean
      when v_before.id is not null then v_before.sold else false end;
    v_requested_asset_count:=jsonb_array_length(p_asset_links);
  exception when others then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end;
  if v_quote is null or v_enabled is null or v_sold is null or v_sort is null then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_mode is null then
    v_mode:=case when v_before.id is not null then v_before.commercial_mode when v_quote then 'PAYROLL_QUOTE' else 'PAYROLL_FIXED' end;
  end if;

  if length(v_name) not between 2 and 180
     and (v_before.id is null or v_name is distinct from v_before.name) then
    raise exception 'PROGRAM_CATALOG_NAME_INVALID' using errcode='22023';
  end if;
  if length(coalesce(v_description,''))>12000
     and (v_before.id is null or v_description is distinct from v_before.description) then
    raise exception 'PROGRAM_CATALOG_DESCRIPTION_TOO_LONG' using errcode='22023';
  end if;
  if length(coalesce(v_category,''))>240
     and (v_before.id is null or v_category is distinct from v_before.category_raw) then
    raise exception 'PROGRAM_CATALOG_CATEGORY_TOO_LONG' using errcode='22023';
  end if;
  if v_sort not between 1 and 10000
     and (v_before.id is null or v_sort is distinct from v_before.sort_order) then
    raise exception 'PROGRAM_CATALOG_ORDER_INVALID' using errcode='22023';
  end if;
  if v_price<0 and (v_before.id is null or v_price is distinct from v_before.price_cash) then
    raise exception 'PROGRAM_CATALOG_PRICE_INVALID' using errcode='22023';
  end if;
  if v_mode not in('PAYROLL_FIXED','PAYROLL_QUOTE','DIRECT_CONTACT') then
    raise exception 'PROGRAM_CATALOG_MODE_INVALID' using errcode='22023';
  end if;
  if (v_mode='PAYROLL_QUOTE')<>v_quote then
    raise exception 'PROGRAM_CATALOG_MODE_QUOTE_MISMATCH' using errcode='22023';
  end if;
  if v_mode='PAYROLL_FIXED' and (v_price is null or v_price<=0)
     and (
       v_before.id is null
       or v_before.commercial_mode<>'PAYROLL_FIXED'
       or (v_before.price_cash is not null and v_before.price_cash>0)
       or v_price is distinct from v_before.price_cash
     ) then
    raise exception 'PROGRAM_CATALOG_PRICE_REQUIRED' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_catalog_items where program_key=v_program)
     and (v_before.id is null or v_program is distinct from v_before.program_key) then
    raise exception 'PROGRAM_CATALOG_PROGRAM_INVALID' using errcode='22023';
  end if;
  if v_requested_asset_count>v_allowed_asset_count then
    raise exception 'PROGRAM_CATALOG_IMAGE_LIMIT_EXCEEDED' using errcode='22023',
      detail='allowed='||v_allowed_asset_count::text||',requested='||v_requested_asset_count::text;
  end if;

  if p_item_id is null then
    insert into public.program_catalog_items(
      program_key,name,description,category_raw,price_cash,requires_quote,commercial_mode,sold,sold_at,sold_by,
      request_mode,legacy_boundary,enabled,sort_order,record_origin,source_sheet,source_row_ordinal,source_snapshot_hash,source_payload
    ) values(
      v_program,v_name,v_description,v_category,v_price,v_quote,v_mode,v_sold,
      case when v_sold then now() else null end,case when v_sold then v_actor else null end,
      'supabase',false,v_enabled,v_sort,'ADMIN_PROGRAM_CATALOG',null,null,null,'{}'::jsonb
    ) returning * into v_after;
    v_id:=v_after.id;
  else
    update public.program_catalog_items set
      program_key=v_program,name=v_name,description=v_description,category_raw=v_category,
      price_cash=v_price,requires_quote=v_quote,commercial_mode=v_mode,sold=v_sold,
      sold_at=case when v_sold then coalesce(v_before.sold_at,now()) else null end,
      sold_by=case when v_sold then coalesce(v_before.sold_by,v_actor) else null end,
      enabled=v_enabled,sort_order=v_sort
    where id=p_item_id returning * into v_after;
    v_id:=v_after.id;
  end if;

  update public.program_catalog_item_assets set sort_order=sort_order+10000 where item_id=v_id and enabled;
  for v_link in select value from jsonb_array_elements(p_asset_links) loop
    v_position:=v_position+1;
    begin
      v_link_id:=nullif(v_link->>'link_id','')::uuid;
      v_public_asset_id:=nullif(v_link->>'public_asset_id','')::uuid;
    exception when others then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end;
    if (v_link_id is null)=(v_public_asset_id is null) then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end if;
    if v_link_id is not null then
      if not exists(select 1 from public.program_catalog_item_assets where id=v_link_id and item_id=v_id) then
        raise exception 'PROGRAM_CATALOG_ASSET_LINK_NOT_FOUND' using errcode='P0001';
      end if;
      update public.program_catalog_item_assets set
        enabled=true,role=case when v_position=1 then 'cover' else 'gallery' end,sort_order=v_position
      where id=v_link_id;
    else
      if not exists(
        select 1 from public.app_assets
        where id=v_public_asset_id and status='READY' and storage_bucket='app-assets'
          and storage_path like 'program-products/%'
      ) then
        raise exception 'PROGRAM_CATALOG_PUBLIC_ASSET_INVALID' using errcode='22023';
      end if;
      select id into v_link_id from public.program_catalog_item_assets
      where item_id=v_id and public_asset_id=v_public_asset_id order by enabled desc limit 1;
      if v_link_id is null then
        v_link_id:=extensions.gen_random_uuid();
        insert into public.program_catalog_item_assets(
          id,item_id,public_asset_id,private_asset_id,role,sort_order,source_column,source_column_letter,enabled
        ) values(
          v_link_id,v_id,v_public_asset_id,null,case when v_position=1 then 'cover' else 'gallery' end,
          v_position,'ADMIN_UPLOAD','ADMIN_'||replace(v_link_id::text,'-',''),true
        );
      else
        update public.program_catalog_item_assets set
          enabled=true,role=case when v_position=1 then 'cover' else 'gallery' end,sort_order=v_position
        where id=v_link_id;
      end if;
    end if;
    if v_link_id=any(v_kept) then
      raise exception 'PROGRAM_CATALOG_ASSET_DUPLICATE' using errcode='22023';
    end if;
    v_kept:=array_append(v_kept,v_link_id);
  end loop;
  update public.program_catalog_item_assets set enabled=false
  where item_id=v_id and enabled and not(id=any(v_kept));

  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'program_catalog_items',case when p_item_id is null then 'INSERT' else 'UPDATE' end,v_id::text,'SUCCESS',
    jsonb_build_object(
      'program_key',v_after.program_key,
      'before',case when v_before.id is null then null else jsonb_build_object(
        'name',v_before.name,'price_cash',v_before.price_cash,'requires_quote',v_before.requires_quote,
        'commercial_mode',v_before.commercial_mode,'sold',v_before.sold,'sold_at',v_before.sold_at,
        'sold_by',v_before.sold_by,'enabled',v_before.enabled,'sort_order',v_before.sort_order
      ) end,
      'after',jsonb_build_object(
        'name',v_after.name,'price_cash',v_after.price_cash,'requires_quote',v_after.requires_quote,
        'commercial_mode',v_after.commercial_mode,'sold',v_after.sold,'sold_at',v_after.sold_at,
        'sold_by',v_after.sold_by,'enabled',v_after.enabled,'sort_order',v_after.sort_order
      ),
      'asset_count',v_position,'asset_limit',v_allowed_asset_count,'delta_aware',true
    ));
  return (to_jsonb(v_after)-'source_payload'-'sold_by');
end $function$

CREATE OR REPLACE FUNCTION public.save_program_document_requirement(p_program_id text, p_membership_offering_id uuid, p_document_type_id uuid, p_required boolean, p_allow_reuse boolean, p_sort_order integer, p_enabled boolean)
