CREATE OR REPLACE FUNCTION public.set_financial_program_request_terms(p_request_id uuid, p_amount numeric, p_term numeric, p_term_semantics text)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.program_requests%rowtype;
begin
  select * into v_row from public.program_requests where id=p_request_id for update;
  if v_row.id is null or v_row.affiliate_id<>public.get_effective_affiliate_id() or v_row.financial_processing_status is null then raise exception 'FINANCIAL_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023'; end if;
  if upper(btrim(p_term_semantics)) like '%UNKNOWN%' then raise exception 'FINANCIAL_TERM_SEMANTICS_UNRESOLVED' using errcode='22023'; end if;
  if v_row.requested_amount is not null then
    if v_row.requested_amount=p_amount and v_row.requested_term=p_term and v_row.requested_term_semantics=btrim(p_term_semantics) then return v_row; end if;
    raise exception 'FINANCIAL_REQUEST_TERMS_IMMUTABLE' using errcode='P0001';
  end if;
  update public.program_requests set requested_amount=p_amount,requested_term=p_term,requested_term_semantics=btrim(p_term_semantics),updated_at=now()
  where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.set_financial_rule_visibility(p_criterion_identity text, p_visibility_mode text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_old public.financial_rules%rowtype; v_new public.financial_rules%rowtype;
begin
  if not public.has_admin_permission('financial_criteria.visibility.write') then raise exception 'VISIBILITY_WRITE_REQUIRED' using errcode='42501'; end if;
  if p_visibility_mode not in('AUTO','MOSTRAR','OCULTAR') or length(btrim(coalesce(p_reason,'')))<8 then raise exception 'VISIBILITY_CHANGE_INVALID' using errcode='22023'; end if;
  select r.* into v_old from public.financial_rules r join public.financial_criteria_authority a on a.id='primary' and a.authority='SUPABASE' and a.active_import_batch_id=r.imported_batch_id
  where r.legacy_criterion_identity=p_criterion_identity and r.lifecycle_status in('PUBLISHED','SCHEDULED') for update of r;
  if v_old.id is null then raise exception 'CRITERION_FINGERPRINT_MISMATCH' using errcode='P0001'; end if;
  update public.financial_rules set visibility_mode=p_visibility_mode where id=v_old.id returning * into v_new;
  update public.financial_session_snapshots set invalidated_at=now(),invalidation_reason='FINANCIAL_VISIBILITY_CHANGED' where invalidated_at is null;
  insert into public.financial_configuration_audit(actor_auth_user_id,resource_type,resource_id,action,old_value,new_value,reason)
  values(auth.uid(),'RULE',v_old.id::text,'VISIBILITY_CHANGE',jsonb_build_object('visibility_mode',v_old.visibility_mode),jsonb_build_object('visibility_mode',v_new.visibility_mode),btrim(p_reason));
  return jsonb_build_object('criterion_identity',v_new.legacy_criterion_identity,'sheet_row',v_new.legacy_sheet_row,
    'previous_visibility',v_old.visibility_mode,'visibility_mode',v_new.visibility_mode,'changed_at',now(),'source','SUPABASE_FINANCIAL_CRITERIA');
end $function$

