CREATE OR REPLACE FUNCTION public.set_savings_admin_access_mode(p_mode text, p_version integer, p_client_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior public.savings_admin_access_events; current_mode public.savings_admin_access_mode;
begin
 if auth.uid() is null or not public.has_admin_permission('authorization.write') then raise exception 'SAVINGS_ACCESS_DENIED' using errcode='42501'; end if;
 if p_mode is null or p_mode not in ('OPEN','RESTRICTED') or p_version is null or p_client_action_id is null then raise exception 'SAVINGS_ACCESS_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_client_action_id::text,607));
 select * into prior from public.savings_admin_access_events where client_action_id=p_client_action_id;
 if found then
  if prior.actor_auth_user_id<>auth.uid() or prior.after_mode<>p_mode or prior.before_version<>p_version then raise exception 'SAVINGS_ACCESS_RETRY_CONFLICT'; end if;
  return jsonb_build_object('mode',prior.after_mode,'version',prior.after_version);
 end if;
 select * into current_mode from public.savings_admin_access_mode where id for update;
 if current_mode.version<>p_version then raise exception 'SAVINGS_ACCESS_CHANGED'; end if;
 update public.savings_admin_access_mode set mode=p_mode,version=version+1,updated_at=clock_timestamp() where id;
 insert into public.savings_admin_access_events(actor_auth_user_id,before_mode,after_mode,before_version,after_version,client_action_id)
 values(auth.uid(),current_mode.mode,p_mode,p_version,p_version+1,p_client_action_id);
 return jsonb_build_object('mode',p_mode,'version',p_version+1);
end $function$

CREATE OR REPLACE FUNCTION public.set_section_responsibilities(p_email text, p_section_key text, p_actions text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_subject uuid;
  v_subjects uuid[];
  v_allowed text[];
begin
  if v_actor is null or not public.has_admin_permission('authorization.write') then
    raise exception 'AUTHORIZATION_DENIED' using errcode='42501';
  end if;
  if nullif(btrim(coalesce(p_email,'')),'') is null then
    raise exception 'EMAIL_REQUIRED' using errcode='22023';
  end if;
  select array_agg(id order by id) into v_subjects from auth.users
   where lower(email)=lower(btrim(p_email)) and email_confirmed_at is not null;
  if coalesce(cardinality(v_subjects),0)=0 then
    raise exception 'CONFIRMED_AUTH_USER_NOT_FOUND' using errcode='P0001';
  end if;
  if cardinality(v_subjects)<>1 then
    raise exception 'AUTH_USER_EMAIL_AMBIGUOUS' using errcode='P0001';
  end if;
  v_subject:=v_subjects[1];
  if v_subject=v_actor then raise exception 'SELF_ASSIGNMENT_DENIED' using errcode='42501'; end if;

  select allowed_actions into v_allowed from public.admin_section_definitions
   where section_key=p_section_key and enforcement_status='ENFORCED';
  if v_allowed is null then raise exception 'SECTION_NOT_ENFORCED' using errcode='P0001'; end if;
  if p_actions is null or cardinality(p_actions)=0
     or exists(select 1 from unnest(p_actions) a where not(a=any(v_allowed))) then
    raise exception 'INVALID_SECTION_ACTION' using errcode='22023';
  end if;

  update public.admin_section_responsibilities
     set enabled=false, updated_at=now(), revoked_at=now(), revoked_by_auth_user_id=v_actor
   where auth_user_id=v_subject and section_key=p_section_key and enabled;
  insert into public.admin_section_responsibilities
    (auth_user_id,section_key,action,enabled,granted_by_auth_user_id)
  select v_subject,p_section_key,a,true,v_actor from (select distinct unnest(p_actions) a) q
  on conflict(auth_user_id,section_key,action) do update
    set enabled=true, assigned_at=now(), updated_at=now(),
        granted_by_auth_user_id=excluded.granted_by_auth_user_id,
        revoked_at=null, revoked_by_auth_user_id=null;

  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'admin_section_responsibilities','SET',v_subject::text,'SUCCESS',
    jsonb_build_object('section_key',p_section_key,'actions',to_jsonb(p_actions)));
  return v_subject;
end
$function$

CREATE OR REPLACE FUNCTION public.set_total_admin_by_email(p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ids uuid[];v_role uuid;
begin
  if not public.has_admin_permission('authorization.write') then raise exception 'AUTHORIZATION_DENIED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_email,'')),'') is null then raise exception 'EMAIL_REQUIRED' using errcode='22023'; end if;
  select array_agg(id order by id) into v_ids from auth.users
  where lower(email)=lower(btrim(p_email)) and email_confirmed_at is not null;
  if coalesce(cardinality(v_ids),0)=0 then raise exception 'CONFIRMED_AUTH_USER_NOT_FOUND' using errcode='P0001'; end if;
  if cardinality(v_ids)<>1 then raise exception 'AUTH_USER_EMAIL_AMBIGUOUS' using errcode='P0001'; end if;
