  if v_role is null then raise exception 'PRINCIPAL_ADMIN_ROLE_REQUIRED' using errcode='P0001'; end if;
  return public.assign_admin_role(v_ids[1],v_role,true);
end $function$

CREATE OR REPLACE FUNCTION public.stage_financial_criteria_import(p_rules jsonb, p_source_snapshot_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch uuid;
  v_rule_count integer;
  v_fund_count integer;
  v_duplicates integer;
  v_conflicts integer;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'IMPORT_DENIED' using errcode='42501'; end if;
  if jsonb_typeof(p_rules)<>'array' or jsonb_array_length(p_rules)<>146 or coalesce(p_source_snapshot_hash,'')!~'^[A-F0-9]{64}$' then
    raise exception 'FINANCIAL_IMPORT_CONTRACT_INVALID' using errcode='22023';
  end if;
  if (select authority from public.financial_criteria_authority where id='primary')<>'GOOGLE_SHADOW' then
    raise exception 'FINANCIAL_AUTHORITY_ALREADY_CUT_OVER' using errcode='P0001';
  end if;
  insert into public.financial_criteria_import_batches(source,source_snapshot_hash,rule_count,fund_count,duplicate_group_count,conflict_group_count,status,metadata)
  values('GOOGLE_CRITERIA_DE_FONDOS',upper(p_source_snapshot_hash),146,1,2,1,'STAGED',jsonb_build_object('columns',jsonb_build_array('A','B','C','D','E','F','H','N','P'),'excluded_columns',jsonb_build_array('G','I','J','K','L','M','O')))
  returning id into v_batch;

  insert into public.financial_funds(program_id,code,name,sort_order,imported_batch_id)
  select x.program_id,x.fund_code,x.fund,min(x.fund_order),v_batch
  from jsonb_to_recordset(p_rules) as x(program_id text,fund_code text,fund text,fund_order integer)
  group by x.program_id,x.fund_code,x.fund
  on conflict(program_id,code) do update set name=excluded.name,sort_order=excluded.sort_order,imported_batch_id=excluded.imported_batch_id,updated_at=now();

  insert into public.financial_rules(
    lineage_id,program_id,fund_id,financial_union_code,financial_union_label,
    financial_employee_category_code,financial_employee_category_label,max_amount,raw_rate,
    term_label,payment_count,max_term,source_date_h,source_date_n,available_on,visibility_mode,
    lifecycle_status,legacy_sheet_row,legacy_criterion_identity,source_snapshot_hash,imported_batch_id,
    review_required,review_signals,published_at
  )
  select extensions.gen_random_uuid(),x.program_id,f.id,x.union_code,x.union_label,x.category_code,x.category_label,
    x.max_amount,x.raw_rate,x.term_label,x.payment_count,x.max_term,nullif(x.source_date_h,''),nullif(x.source_date_n,''),x.available_on,
    x.visibility_mode,'PUBLISHED',x.legacy_sheet_row,x.legacy_criterion_identity,upper(x.source_snapshot_hash),v_batch,
    coalesce(cardinality(x.review_signals),0)>0,coalesce(x.review_signals,'{}'::text[]),now()
  from jsonb_to_recordset(p_rules) as x(
    program_id text,fund_code text,union_code text,union_label text,category_code text,category_label text,
    max_amount numeric,raw_rate numeric,term_label text,payment_count integer,max_term integer,
    source_date_h text,source_date_n text,available_on date,visibility_mode text,legacy_sheet_row integer,
    legacy_criterion_identity text,source_snapshot_hash text,review_signals text[]
  )
  join public.financial_funds f on f.program_id=x.program_id and f.code=x.fund_code;

  select count(*),count(distinct fund_id) into v_rule_count,v_fund_count from public.financial_rules where imported_batch_id=v_batch;
  select count(*) into v_duplicates from (
    select 1 from public.financial_rules r where r.imported_batch_id=v_batch
    group by r.program_id,r.fund_id,public.normalize_suti_financial_key(r.financial_union_label),
      public.normalize_suti_financial_key(r.financial_employee_category_label),r.max_amount,r.rate_percent,r.term_label,
      r.payment_count,r.available_on,r.visibility_mode having count(*)>1
  ) groups;
  select count(*) into v_conflicts from (
    select 1 from public.financial_rules r where r.imported_batch_id=v_batch
    group by r.program_id,r.fund_id,public.normalize_suti_financial_key(r.financial_union_label),
      public.normalize_suti_financial_key(r.financial_employee_category_label),r.available_on
    having count(distinct concat_ws('|',r.max_amount,r.rate_percent,r.term_label,r.payment_count,r.visibility_mode))>1
  ) groups;
  if v_rule_count<>146 or v_fund_count<>35 or v_duplicates<>2 or v_conflicts<>1 then
    raise exception 'FINANCIAL_IMPORT_EQUIVALENCE_FAILED rules=% funds=% duplicates=% conflicts=%',v_rule_count,v_fund_count,v_duplicates,v_conflicts using errcode='P0001';
  end if;
  update public.financial_criteria_import_batches set fund_count=v_fund_count where id=v_batch;
  insert into public.financial_configuration_audit(resource_type,resource_id,action,new_value,reason)
  values('IMPORT',v_batch::text,'STAGE',jsonb_build_object('rules',v_rule_count,'funds',v_fund_count,'duplicates',v_duplicates,'conflicts',v_conflicts,'source_snapshot_hash',upper(p_source_snapshot_hash)),'Certified shadow import of consumed Google criteria fields');
  return jsonb_build_object('batch_id',v_batch,'rules',v_rule_count,'funds',v_fund_count,'duplicates',v_duplicates,'conflicts',v_conflicts,'source_snapshot_hash',upper(p_source_snapshot_hash));
end $function$

CREATE OR REPLACE FUNCTION public.start_affiliate_impersonation(p_affiliate_id uuid, p_reason text)
 RETURNS TABLE(session_id uuid, affiliate_id uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();v_auth_session text:=nullif(auth.jwt()->>'session_id','');v_created public.impersonation_sessions%rowtype;v_archived boolean;
begin
  if v_actor is null or not public.has_admin_permission('affiliates.impersonate') then raise exception 'IMPERSONATION_DENIED' using errcode='42501'; end if;
  if v_auth_session is null then raise exception 'AUTH_SESSION_REQUIRED' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_reason,'')))<8 then raise exception 'REASON_REQUIRED' using errcode='22023'; end if;
  select a.is_archived into v_archived from public.affiliates a where a.id=p_affiliate_id;
  if v_archived is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_archived then raise exception 'AFFILIATE_ARCHIVED' using errcode='42501'; end if;
  with closed as (
    update public.impersonation_sessions s set ended_at=now(),ended_by_auth_user_id=v_actor
    where s.actor_real_auth_user_id=v_actor and s.ended_at is null
      and (s.expires_at<=now() or s.actor_auth_session_id is distinct from v_auth_session)
    returning s.*
  ) insert into public.identity_audit_log(actor_real_auth_user_id,usuario_contexto_affiliate_id,action,result,details)
    select v_actor,c.usuario_contexto_affiliate_id,'IMPERSONATION_STOPPED','SUCCESS',jsonb_build_object(
      'session_id',c.id,'reason',c.reason,'automatic',true,'cause','AUTH_SESSION_REPLACED_OR_EXPIRED') from closed c;
  if exists(select 1 from public.impersonation_sessions s where s.actor_real_auth_user_id=v_actor and s.ended_at is null) then
    raise exception 'IMPERSONATION_ALREADY_ACTIVE' using errcode='P0001';
  end if;
  insert into public.impersonation_sessions(actor_real_auth_user_id,usuario_contexto_affiliate_id,reason,expires_at,actor_auth_session_id)
  values(v_actor,p_affiliate_id,btrim(p_reason),now()+interval '30 minutes',v_auth_session) returning * into v_created;
  insert into public.identity_audit_log(actor_real_auth_user_id,usuario_contexto_affiliate_id,action,result,details)
  values(v_actor,p_affiliate_id,'IMPERSONATION_STARTED','SUCCESS',jsonb_build_object(
    'session_id',v_created.id,'expires_at',v_created.expires_at,'reason',v_created.reason,
    'actor_auth_session_id',v_auth_session,'scope','ASSISTED_AFFILIATE_SERVICE'));
  return query select v_created.id,v_created.usuario_contexto_affiliate_id,v_created.expires_at;
end $function$

CREATE OR REPLACE FUNCTION public.stop_affiliate_impersonation()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_active public.impersonation_sessions%rowtype;
begin
  if v_actor is null or not public.has_admin_permission('affiliates.impersonate') then
    raise exception 'IMPERSONATION_DENIED' using errcode='42501';
  end if;
  if nullif(auth.jwt()->>'session_id','') is null then raise exception 'AUTH_SESSION_REQUIRED' using errcode='42501'; end if;
  select * into v_active from public.impersonation_sessions
  where actor_real_auth_user_id=v_actor and ended_at is null
    and actor_auth_session_id=nullif(auth.jwt()->>'session_id','')
  order by started_at desc limit 1 for update;
  if v_active.id is null then return false; end if;
  update public.impersonation_sessions set ended_at=now(),ended_by_auth_user_id=v_actor where id=v_active.id;
  insert into public.identity_audit_log(actor_real_auth_user_id,usuario_contexto_affiliate_id,action,result,details)
  values(v_actor,v_active.usuario_contexto_affiliate_id,'IMPERSONATION_STOPPED','SUCCESS',jsonb_build_object(
    'session_id',v_active.id,'reason',v_active.reason,'manual',true,'actor_auth_session_id',v_active.actor_auth_session_id));
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.submit_self_savings_request(p_request_type text, p_amount numeric, p_component text, p_withdrawal_kind text, p_new_contribution_amount numeric, p_continue_saving boolean, p_effective_from date, p_reason text, p_supporting_document_id uuid, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();v_affiliate uuid:=public.get_effective_affiliate_id();
  v_participant record;v_enrollment record;v_request record;v_balance record;v_enrollment_id uuid;v_has_enrollment boolean:=false;
  v_type text:=upper(coalesce(p_request_type,''));v_component text:=upper(coalesce(p_component,''));v_kind text:=upper(coalesce(p_withdrawal_kind,'PARTIAL'));v_total_available numeric;
begin
  if v_actor is null or v_affiliate is null then raise exception 'SAVINGS_AFFILIATE_REQUIRED' using errcode='42501'; end if;
  if p_idempotency_key is null then raise exception 'SAVINGS_IDEMPOTENCY_REQUIRED' using errcode='22023'; end if;
  select * into v_request from public.savings_requests where actor_real_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then return to_jsonb(v_request); end if;
  if v_type not in ('JOIN','CHANGE_AMOUNT','WITHDRAW','TERMINATE','EXTRAORDINARY_WITHDRAWAL') then raise exception 'SAVINGS_REQUEST_TYPE_INVALID' using errcode='22023'; end if;
  select * into v_participant from public.savings_participants where affiliate_id=v_affiliate;
  if not found then
    if v_type<>'JOIN' then raise exception 'SAVINGS_PARTICIPANT_REQUIRED' using errcode='P0001'; end if;
    insert into public.savings_participants(participant_type,affiliate_id,legacy_folio,display_name,identity_status,certification_status,process_source,data_classification)
    select 'AFFILIATE',a.id,a.numero_control,coalesce(a.display_name,a.full_name),'RESOLVED','CERTIFIED','SHADOW','SHADOW' from public.affiliates a where a.id=v_affiliate
    returning * into v_participant;
  end if;
  if not public.savings_effective_action(case when v_type='EXTRAORDINARY_WITHDRAWAL' then 'WITHDRAW' else v_type end,v_participant.id) then
    raise exception 'SAVINGS_ACTION_DISABLED' using errcode='42501';
  end if;
  select * into v_enrollment from public.savings_enrollments where participant_id=v_participant.id order by sequence_number desc limit 1;
  v_has_enrollment:=found;
  if v_has_enrollment then v_enrollment_id:=v_enrollment.id; end if;
  if v_type='JOIN' then
    if v_has_enrollment and v_enrollment.status in ('REQUESTED','ACTIVE','TERMINATION_PENDING') then raise exception 'SAVINGS_ENROLLMENT_ALREADY_OPEN' using errcode='23505'; end if;
    if coalesce(p_new_contribution_amount,0)<=0 then raise exception 'SAVINGS_CONTRIBUTION_AMOUNT_REQUIRED' using errcode='22023'; end if;
  elsif not v_has_enrollment or v_enrollment.status<>'ACTIVE' then
    raise exception 'SAVINGS_ACTIVE_ENROLLMENT_REQUIRED' using errcode='P0001';
  end if;
  if v_type='CHANGE_AMOUNT' and (coalesce(p_new_contribution_amount,0)<=0 or p_effective_from is null or p_effective_from<=current_date) then
    raise exception 'SAVINGS_FUTURE_AMOUNT_CHANGE_REQUIRED' using errcode='22023';
  end if;
  if v_type in ('WITHDRAW','EXTRAORDINARY_WITHDRAWAL') and (coalesce(p_amount,0)<=0 or v_component not in ('CAPITAL','YIELD','BOTH')) then
    raise exception 'SAVINGS_WITHDRAWAL_AMOUNT_INVALID' using errcode='22023';
  end if;
  if v_type='WITHDRAW' and v_kind not in ('PARTIAL','TOTAL') then raise exception 'SAVINGS_WITHDRAWAL_KIND_INVALID' using errcode='22023'; end if;
  if v_type='WITHDRAW' and v_kind='TOTAL' then
    select * into v_balance from public.savings_participant_balance(v_participant.id);
    v_total_available:=case v_component when 'CAPITAL' then greatest(v_balance.capital-v_balance.held_capital,0)
      when 'YIELD' then greatest(v_balance.yield_amount-v_balance.held_yield,0) else v_balance.available end;
    if p_amount is distinct from v_total_available or v_total_available<=0 then raise exception 'SAVINGS_TOTAL_WITHDRAWAL_AMOUNT_MISMATCH' using errcode='22023'; end if;
  end if;
  if v_type='EXTRAORDINARY_WITHDRAWAL' then
    if length(btrim(coalesce(p_reason,'')))<3 or p_supporting_document_id is null then raise exception 'SAVINGS_EXTRAORDINARY_DOCUMENT_REQUIRED' using errcode='22023'; end if;
    if v_component<>'CAPITAL' then raise exception 'SAVINGS_EXTRAORDINARY_CAPITAL_ONLY' using errcode='22023'; end if;
    if not exists(select 1 from public.affiliate_documents d where d.id=p_supporting_document_id and d.affiliate_id=v_affiliate) then raise exception 'SAVINGS_DOCUMENT_ACCESS_DENIED' using errcode='42501'; end if;
  end if;
  insert into public.savings_requests(
    folio,participant_id,enrollment_id,request_type,withdrawal_kind,component,requested_amount,new_contribution_amount,
    continue_saving,supporting_document_id,effective_from,reason,actor_real_auth_user_id,usuario_contexto_affiliate_id,idempotency_key
  ) values(
    'AHO-'||to_char(clock_timestamp(),'YYYY')||'-'||upper(substr(replace(extensions.gen_random_uuid()::text,'-',''),1,8)),
    v_participant.id,v_enrollment_id,v_type,
    case when v_type='EXTRAORDINARY_WITHDRAWAL' then 'EXTRAORDINARY' when v_type='WITHDRAW' then v_kind else null end,
    nullif(v_component,''),p_amount,p_new_contribution_amount,case when v_type='TERMINATE' then false else p_continue_saving end,
    p_supporting_document_id,p_effective_from,btrim(coalesce(p_reason,'')),v_actor,v_affiliate,p_idempotency_key
  ) returning * into v_request;
  insert into public.savings_audit_events(actor_real_auth_user_id,usuario_contexto_affiliate_id,participant_id,resource,action,target_id,after_data,reason,client_action_id)
  values(v_actor,v_affiliate,v_participant.id,'savings_requests','SUBMIT',v_request.id::text,to_jsonb(v_request),v_request.reason,p_idempotency_key);
  return to_jsonb(v_request);
end $function$

CREATE OR REPLACE FUNCTION public.sync_affiliate_expediente_classification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op <> 'INSERT' and old.affiliate_id is not null then
    perform public.refresh_affiliate_expediente_classification(old.affiliate_id);
  end if;
  if tg_op <> 'DELETE' and new.affiliate_id is not null
     and (tg_op = 'INSERT' or old.affiliate_id is distinct from new.affiliate_id) then
    perform public.refresh_affiliate_expediente_classification(new.affiliate_id);
  elsif tg_op = 'UPDATE' and new.affiliate_id is not null then
    perform public.refresh_affiliate_expediente_classification(new.affiliate_id);
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_program_request_tracking_from_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_stage jsonb;v_first jsonb;v_dates jsonb;v_at timestamptz;
begin
  select s into v_stage from jsonb_array_elements(new.workflow_snapshot->'stages') s
  where s->'status_references'?new.status
    and (case when new.status in('rejected','cancelled') then s->>'outcome'<>'success' else s->>'outcome'<>'failure' end)
  order by (s->>'sort_order')::integer,s->>'id' limit 1;
  if v_stage is null then raise exception 'REQUEST_WORKFLOW_STATUS_UNMAPPED' using errcode='22023'; end if;
  select s into v_first from jsonb_array_elements(new.workflow_snapshot->'stages') s
    order by (s->>'sort_order')::integer,s->>'id' limit 1;
  select coalesce(stage_dates,'{}'::jsonb) into v_dates from public.operational_request_tracking where request_id=new.id;
  v_dates:=coalesce(v_dates,'{}'::jsonb);
  if coalesce((v_first->>'captures_date')::boolean,false) and not(v_dates?(v_first->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_first->>'id',new.created_at);
  end if;
  v_at:=case when tg_op='INSERT' then new.created_at else now() end;
  if coalesce((v_stage->>'captures_date')::boolean,false) and not(v_dates?(v_stage->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_stage->>'id',v_at);
  end if;
  perform set_config('app.workflow_change_reason',case when tg_op='INSERT' then 'Alta de solicitud' else 'Estado de solicitud: '||old.status||' -> '||new.status end,true);
  insert into public.operational_request_tracking(request_id,workflow_id,current_stage_id,stage_dates)
  values(new.id,new.workflow_id,(v_stage->>'id')::uuid,v_dates)
  on conflict(request_id) do update set workflow_id=excluded.workflow_id,current_stage_id=excluded.current_stage_id,stage_dates=excluded.stage_dates;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.transition_program_request_workflow(p_request_id uuid, p_action text, p_comment text, p_client_action_id uuid, p_quote_amount numeric DEFAULT NULL::numeric, p_quote_valid_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.program_requests%rowtype;v_existing public.program_request_admin_events%rowtype;
  v_event public.program_request_admin_events%rowtype;v_state jsonb;v_current jsonb;v_target jsonb;v_first jsonb;
  v_action text:=upper(btrim(coalesce(p_action,'')));v_event_action text;v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_to_status text;v_actor_label text;v_dates jsonb;v_expected_existing text[];
begin
  if auth.uid() is null or not public.has_admin_permission('program_requests.write') then
    raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501';
  end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_action not in('ADVANCE','REJECT') then raise exception 'PROGRAM_REQUEST_WORKFLOW_ACTION_INVALID' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023'; end if;
  if v_action='REJECT' and v_comment is null then raise exception 'PROGRAM_REQUEST_COMMENT_REQUIRED' using errcode='22023'; end if;

  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    v_expected_existing:=case when v_action='REJECT' then array['REJECT'] else array['APPROVE','ADVANCE_STAGE'] end;
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or not(v_existing.action=any(v_expected_existing)) then
      raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505';
    end if;
    return jsonb_build_object('idempotent',true,'event',to_jsonb(v_existing)-'actor_auth_user_id'-'client_action_id',
      'workflow_state',public.resolve_program_request_workflow_state(p_request_id));
  end if;

  select * into v_request from public.program_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'PROGRAM_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  v_state:=public.resolve_program_request_workflow_state(v_request.id);
  if not coalesce((v_state->>'available')::boolean,false) then raise exception 'REQUEST_WORKFLOW_UNAVAILABLE' using errcode='P0001'; end if;
  v_current:=v_state->'current_stage';
  if v_current is null then raise exception 'REQUEST_WORKFLOW_CURRENT_STAGE_MISSING' using errcode='P0001'; end if;

  if v_action='REJECT' then
    if v_request.status in('approved','rejected','cancelled') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    select s into v_target from jsonb_array_elements(v_request.workflow_snapshot->'stages') s
      where s->>'outcome'='failure' and s->'status_references'?'rejected'
      order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if v_target is null then raise exception 'REQUEST_WORKFLOW_REJECT_STAGE_MISSING' using errcode='P0001'; end if;
    v_to_status:='rejected';v_event_action:='REJECT';
  else
    if v_request.status in('rejected','cancelled') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    select s into v_target from jsonb_array_elements(v_state->'stages') s
      where (s->>'sort_order')::integer>(v_current->>'sort_order')::integer and s->>'outcome'<>'failure'
      order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if v_target is null then raise exception 'REQUEST_WORKFLOW_ALREADY_COMPLETE' using errcode='P0001'; end if;
    v_to_status:=v_request.status;
    if v_target->'status_references'?'approved' then
      if v_request.financial_processing_status is not null then
        raise exception 'SPECIALIZED_FINANCIAL_APPROVAL_REQUIRED' using errcode='P0001';
      elsif v_request.request_type='quote' then
        if p_quote_amount is null or p_quote_amount<=0 then raise exception 'QUOTE_AMOUNT_REQUIRED' using errcode='22023'; end if;
      end if;
      v_to_status:='approved';v_event_action:='APPROVE';
    elsif v_target->'status_references'?'in_review' and v_request.status in('submitted','requires_financial_processing') then
      v_to_status:='in_review';v_event_action:='ADVANCE_STAGE';
    else v_event_action:='ADVANCE_STAGE'; end if;
  end if;

  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),nullif(btrim(raw_user_meta_data->>'full_name'),''),
    nullif(btrim(raw_user_meta_data->>'name'),''),'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  perform set_config('app.workflow_change_reason',coalesce(v_comment,case when v_action='REJECT' then 'Rechazo de etapa' else 'Avance de etapa' end),true);

  if v_to_status is distinct from v_request.status then
    if v_request.request_type='quote' and v_to_status='approved' then
      update public.program_requests set status='approved',quoted_amount=round(p_quote_amount,2),quote_note=v_comment,
        valid_until=coalesce(p_quote_valid_until,current_date+15),responded_by_auth_user_id=auth.uid(),responded_at=now(),seen_at=null,updated_at=now()
      where id=v_request.id;
    else
      update public.program_requests set status=v_to_status,updated_at=now() where id=v_request.id;
    end if;
  else
    select coalesce(stage_dates,'{}'::jsonb) into v_dates from public.operational_request_tracking where request_id=v_request.id;
    v_dates:=coalesce(v_dates,'{}'::jsonb);
    select s into v_first from jsonb_array_elements(v_request.workflow_snapshot->'stages') s order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if coalesce((v_first->>'captures_date')::boolean,false) and not(v_dates?(v_first->>'id')) then v_dates:=v_dates||jsonb_build_object(v_first->>'id',v_request.created_at); end if;
    if coalesce((v_target->>'captures_date')::boolean,false) and not(v_dates?(v_target->>'id')) then v_dates:=v_dates||jsonb_build_object(v_target->>'id',now()); end if;
    insert into public.operational_request_tracking(request_id,workflow_id,current_stage_id,stage_dates)
      values(v_request.id,v_request.workflow_id,(v_target->>'id')::uuid,v_dates)
      on conflict(request_id) do update set workflow_id=excluded.workflow_id,current_stage_id=excluded.current_stage_id,stage_dates=excluded.stage_dates;
  end if;

  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,from_stage_id,to_stage_id
  ) values(v_request.id,auth.uid(),left(coalesce(v_actor_label,'Personal autorizado'),160),v_event_action,v_request.status,v_to_status,
    v_comment,p_client_action_id,(v_current->>'id')::uuid,(v_target->>'id')::uuid) returning * into v_event;
  return jsonb_build_object('idempotent',false,'event',to_jsonb(v_event)-'actor_auth_user_id'-'client_action_id',
    'workflow_state',public.resolve_program_request_workflow_state(v_request.id));
end $function$

CREATE OR REPLACE FUNCTION public.update_admin_affiliate(p_affiliate_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.affiliates%rowtype;v_new public.affiliates%rowtype;v_key text;v_value text;v_reason text:=btrim(coalesce(p_reason,''));
  v_allowed constant text[]:=array['full_name','display_name','historical_email_raw','phone_raw','address_raw','birth_date_raw','gender_raw','marital_status_raw','children_count_raw','rfc_raw','curp_raw','unit_raw','city_raw','employment_position_raw','employment_entry_date_raw','occupation_raw','institute_entry_date_raw','employment_area_raw','employment_level_raw','pension_raw','subdirectorate_raw','union_enrollment_date_raw','capture_date_raw','affiliation_raw','union_position_raw','termination_date_raw','financial_union_code','financial_employee_category_code','financial_employee_type','financial_affiliation_status','financial_employment_status'];
  v_profile_fields constant text[]:=array['full_name','display_name','phone_raw','unit_raw','city_raw','employment_position_raw','employment_area_raw','financial_union_code','financial_employee_category_code','financial_employee_type','financial_affiliation_status','financial_employment_status'];
  v_changed text[]:=array[]::text[];v_before jsonb:='{}'::jsonb;v_after jsonb:='{}'::jsonb;v_profile_change boolean:=false;v_email text;v_eligibility text;
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if jsonb_typeof(p_patch)<>'object' or p_patch='{}'::jsonb then raise exception 'AFFILIATE_PATCH_REQUIRED' using errcode='22023'; end if;
  if length(v_reason) not between 8 and 500 then raise exception 'AFFILIATE_REASON_REQUIRED' using errcode='22023'; end if;
  select * into v_old from public.affiliates where id=p_affiliate_id for update;
  if v_old.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.updated_at is distinct from p_expected_updated_at then raise exception 'AFFILIATE_VERSION_CONFLICT' using errcode='PT409'; end if;
  for v_key in select jsonb_object_keys(p_patch) loop
    if not(v_key=any(v_allowed)) then raise exception 'AFFILIATE_FIELD_DENIED: %',v_key using errcode='22023'; end if;
    v_value:=nullif(btrim(p_patch->>v_key),'');
    if v_key in ('rfc_raw','curp_raw') then v_value:=upper(v_value); end if;
    if to_jsonb(v_old)->>v_key is distinct from v_value then
      v_changed:=array_append(v_changed,v_key);v_before:=v_before||jsonb_build_object(v_key,to_jsonb(v_old)->v_key);v_after:=v_after||jsonb_build_object(v_key,to_jsonb(v_value));
      if v_key=any(v_profile_fields) then v_profile_change:=true; end if;
    end if;
  end loop;
  if cardinality(v_changed)=0 then raise exception 'AFFILIATE_NO_CHANGE' using errcode='22023'; end if;
  if p_patch?'rfc_raw' and nullif(upper(btrim(p_patch->>'rfc_raw')),'') is not null and exists(select 1 from public.affiliates where id<>p_affiliate_id and upper(btrim(rfc_raw))=upper(btrim(p_patch->>'rfc_raw'))) then raise exception 'AFFILIATE_RFC_DUPLICATE' using errcode='23505'; end if;
  if p_patch?'curp_raw' and nullif(upper(btrim(p_patch->>'curp_raw')),'') is not null and exists(select 1 from public.affiliates where id<>p_affiliate_id and upper(btrim(curp_raw))=upper(btrim(p_patch->>'curp_raw'))) then raise exception 'AFFILIATE_CURP_DUPLICATE' using errcode='23505'; end if;
  if p_patch?'financial_union_code' and nullif(btrim(p_patch->>'financial_union_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='union' and code=p_patch->>'financial_union_code' and enabled) then raise exception 'AFFILIATE_UNION_INVALID' using errcode='22023'; end if;
  if p_patch?'financial_employee_category_code' and nullif(btrim(p_patch->>'financial_employee_category_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='employment_category' and code=p_patch->>'financial_employee_category_code' and enabled) then raise exception 'AFFILIATE_CATEGORY_INVALID' using errcode='22023'; end if;
  v_email:=case when p_patch?'historical_email_raw' then nullif(lower(btrim(p_patch->>'historical_email_raw')),'') else v_old.historical_email_normalized end;
  v_eligibility:=case when v_old.auth_user_id is not null then v_old.auth_eligibility when v_email is null then 'missing_email'
    when v_email!~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then 'invalid_email'
    when exists(select 1 from public.affiliates where id<>p_affiliate_id and historical_email_normalized=v_email) then 'duplicate_email' else 'eligible' end;
  update public.affiliates set
    full_name=case when p_patch?'full_name' then nullif(btrim(p_patch->>'full_name'),'') else full_name end,
    display_name=case when p_patch?'display_name' then nullif(btrim(p_patch->>'display_name'),'') else display_name end,
    historical_email_raw=case when p_patch?'historical_email_raw' then nullif(btrim(p_patch->>'historical_email_raw'),'') else historical_email_raw end,
    historical_email_normalized=case when p_patch?'historical_email_raw' then v_email else historical_email_normalized end,
    phone_raw=case when p_patch?'phone_raw' then nullif(btrim(p_patch->>'phone_raw'),'') else phone_raw end,
    address_raw=case when p_patch?'address_raw' then nullif(btrim(p_patch->>'address_raw'),'') else address_raw end,
    birth_date_raw=case when p_patch?'birth_date_raw' then nullif(btrim(p_patch->>'birth_date_raw'),'') else birth_date_raw end,
    gender_raw=case when p_patch?'gender_raw' then nullif(btrim(p_patch->>'gender_raw'),'') else gender_raw end,
    marital_status_raw=case when p_patch?'marital_status_raw' then nullif(btrim(p_patch->>'marital_status_raw'),'') else marital_status_raw end,
    children_count_raw=case when p_patch?'children_count_raw' then nullif(btrim(p_patch->>'children_count_raw'),'') else children_count_raw end,
    rfc_raw=case when p_patch?'rfc_raw' then nullif(upper(btrim(p_patch->>'rfc_raw')),'') else rfc_raw end,
    curp_raw=case when p_patch?'curp_raw' then nullif(upper(btrim(p_patch->>'curp_raw')),'') else curp_raw end,
    unit_raw=case when p_patch?'unit_raw' then nullif(btrim(p_patch->>'unit_raw'),'') else unit_raw end,
    city_raw=case when p_patch?'city_raw' then nullif(btrim(p_patch->>'city_raw'),'') else city_raw end,
    employment_position_raw=case when p_patch?'employment_position_raw' then nullif(btrim(p_patch->>'employment_position_raw'),'') else employment_position_raw end,
    employment_entry_date_raw=case when p_patch?'employment_entry_date_raw' then nullif(btrim(p_patch->>'employment_entry_date_raw'),'') else employment_entry_date_raw end,
    occupation_raw=case when p_patch?'occupation_raw' then nullif(btrim(p_patch->>'occupation_raw'),'') else occupation_raw end,
    institute_entry_date_raw=case when p_patch?'institute_entry_date_raw' then nullif(btrim(p_patch->>'institute_entry_date_raw'),'') else institute_entry_date_raw end,
    employment_area_raw=case when p_patch?'employment_area_raw' then nullif(btrim(p_patch->>'employment_area_raw'),'') else employment_area_raw end,
    employment_level_raw=case when p_patch?'employment_level_raw' then nullif(btrim(p_patch->>'employment_level_raw'),'') else employment_level_raw end,
    pension_raw=case when p_patch?'pension_raw' then nullif(btrim(p_patch->>'pension_raw'),'') else pension_raw end,
    subdirectorate_raw=case when p_patch?'subdirectorate_raw' then nullif(btrim(p_patch->>'subdirectorate_raw'),'') else subdirectorate_raw end,
    union_enrollment_date_raw=case when p_patch?'union_enrollment_date_raw' then nullif(btrim(p_patch->>'union_enrollment_date_raw'),'') else union_enrollment_date_raw end,
    capture_date_raw=case when p_patch?'capture_date_raw' then nullif(btrim(p_patch->>'capture_date_raw'),'') else capture_date_raw end,
    affiliation_raw=case when p_patch?'affiliation_raw' then nullif(btrim(p_patch->>'affiliation_raw'),'') else affiliation_raw end,
    union_position_raw=case when p_patch?'union_position_raw' then nullif(btrim(p_patch->>'union_position_raw'),'') else union_position_raw end,
    termination_date_raw=case when p_patch?'termination_date_raw' then nullif(btrim(p_patch->>'termination_date_raw'),'') else termination_date_raw end,
    financial_union_code=case when p_patch?'financial_union_code' then nullif(btrim(p_patch->>'financial_union_code'),'') else financial_union_code end,
    financial_employee_category_code=case when p_patch?'financial_employee_category_code' then nullif(btrim(p_patch->>'financial_employee_category_code'),'') else financial_employee_category_code end,
    financial_employee_type=case when p_patch?'financial_employee_type' then nullif(btrim(p_patch->>'financial_employee_type'),'') else financial_employee_type end,
    financial_affiliation_status=case when p_patch?'financial_affiliation_status' then nullif(btrim(p_patch->>'financial_affiliation_status'),'') else financial_affiliation_status end,
    financial_employment_status=case when p_patch?'financial_employment_status' then nullif(btrim(p_patch->>'financial_employment_status'),'') else financial_employment_status end,
    auth_eligibility=case when p_patch?'historical_email_raw' and auth_user_id is null then v_eligibility else auth_eligibility end,
    auth_ineligibility_reason=case when p_patch?'historical_email_raw' and auth_user_id is null then case when v_eligibility='eligible' then null else v_eligibility end else auth_ineligibility_reason end,
    financial_profile_version=financial_profile_version+case when v_profile_change then 1 else 0 end,
    financial_profile_updated_at=case when v_profile_change then now() else financial_profile_updated_at end,
    financial_profile_updated_by=case when v_profile_change then auth.uid() else financial_profile_updated_by end
  where id=p_affiliate_id returning * into v_new;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(p_affiliate_id,auth.uid(),'UPDATE',v_before,v_after,v_changed,v_reason);
  for v_key in select unnest(v_changed) loop
    if v_key=any(v_profile_fields) then
      insert into public.affiliate_profile_audit_log(affiliate_id,field_name,old_value,new_value,changed_by,reason,profile_version)
      values(p_affiliate_id,v_key,v_before->v_key,v_after->v_key,auth.uid(),v_reason,v_new.financial_profile_version);
    end if;
  end loop;
  return public.get_admin_affiliate_workbench(p_affiliate_id);
end $function$

CREATE OR REPLACE FUNCTION public.update_affiliate_admin_profile(p_affiliate_id uuid, p_expected_version integer, p_patch jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.affiliates%rowtype; v_new public.affiliates%rowtype; v_key text; v_changed boolean:=false; v_allowed constant text[]:=array[
  'full_name','display_name','phone_raw','unit_raw','city_raw','employment_position_raw','employment_area_raw',
  'financial_union_code','financial_employee_category_code','financial_employee_type','financial_affiliation_status','financial_employment_status'];
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if jsonb_typeof(p_patch)<>'object' or p_patch='{}'::jsonb then raise exception 'PROFILE_PATCH_REQUIRED' using errcode='22023'; end if;
  if length(btrim(coalesce(p_reason,''))) not between 8 and 500 then raise exception 'PROFILE_REASON_REQUIRED' using errcode='22023'; end if;
  for v_key in select jsonb_object_keys(p_patch) loop if not(v_key=any(v_allowed)) then raise exception 'PROFILE_FIELD_DENIED: %',v_key using errcode='22023'; end if; end loop;
  select * into v_old from public.affiliates where id=p_affiliate_id for update;
  if v_old.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  if v_old.financial_profile_version<>coalesce(p_expected_version,-1) then raise exception 'PROFILE_VERSION_CONFLICT' using errcode='PT409'; end if;
  if p_patch ? 'financial_union_code' and nullif(btrim(p_patch->>'financial_union_code'),'') is not null and not exists(
    select 1 from public.segmentation_catalog_entries where catalog_type='union' and code=p_patch->>'financial_union_code' and enabled
  ) then raise exception 'FINANCIAL_UNION_INVALID' using errcode='22023'; end if;
  if p_patch ? 'financial_employee_category_code' and nullif(btrim(p_patch->>'financial_employee_category_code'),'') is not null and not exists(
    select 1 from public.segmentation_catalog_entries where catalog_type='employment_category' and code=p_patch->>'financial_employee_category_code' and enabled
  ) then raise exception 'FINANCIAL_CATEGORY_INVALID' using errcode='22023'; end if;
  update public.affiliates set
    full_name=case when p_patch?'full_name' then nullif(btrim(p_patch->>'full_name'),'') else full_name end,
    display_name=case when p_patch?'display_name' then nullif(btrim(p_patch->>'display_name'),'') else display_name end,
    phone_raw=case when p_patch?'phone_raw' then nullif(btrim(p_patch->>'phone_raw'),'') else phone_raw end,
    unit_raw=case when p_patch?'unit_raw' then nullif(btrim(p_patch->>'unit_raw'),'') else unit_raw end,
    city_raw=case when p_patch?'city_raw' then nullif(btrim(p_patch->>'city_raw'),'') else city_raw end,
    employment_position_raw=case when p_patch?'employment_position_raw' then nullif(btrim(p_patch->>'employment_position_raw'),'') else employment_position_raw end,
    employment_area_raw=case when p_patch?'employment_area_raw' then nullif(btrim(p_patch->>'employment_area_raw'),'') else employment_area_raw end,
    financial_union_code=case when p_patch?'financial_union_code' then nullif(btrim(p_patch->>'financial_union_code'),'') else financial_union_code end,
    financial_employee_category_code=case when p_patch?'financial_employee_category_code' then nullif(btrim(p_patch->>'financial_employee_category_code'),'') else financial_employee_category_code end,
    financial_employee_type=case when p_patch?'financial_employee_type' then nullif(btrim(p_patch->>'financial_employee_type'),'') else financial_employee_type end,
    financial_affiliation_status=case when p_patch?'financial_affiliation_status' then nullif(btrim(p_patch->>'financial_affiliation_status'),'') else financial_affiliation_status end,
    financial_employment_status=case when p_patch?'financial_employment_status' then nullif(btrim(p_patch->>'financial_employment_status'),'') else financial_employment_status end,
    financial_profile_version=financial_profile_version+1,financial_profile_updated_at=now(),financial_profile_updated_by=auth.uid(),updated_at=now()
  where id=p_affiliate_id returning * into v_new;
  for v_key in select unnest(v_allowed) loop
    if to_jsonb(v_old)->v_key is distinct from to_jsonb(v_new)->v_key then
      v_changed:=true;
      insert into public.affiliate_profile_audit_log(affiliate_id,field_name,old_value,new_value,changed_by,reason,profile_version)
      values(p_affiliate_id,v_key,to_jsonb(v_old)->v_key,to_jsonb(v_new)->v_key,auth.uid(),btrim(p_reason),v_new.financial_profile_version);
    end if;
  end loop;
  if not v_changed then raise exception 'PROFILE_NO_CHANGE' using errcode='22023'; end if;
  return public.get_affiliate_admin_profile(p_affiliate_id);
end $function$

CREATE OR REPLACE FUNCTION public.update_program_request(p_request_id uuid, p_status text, p_notes text)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.program_requests%rowtype;
begin
  select * into v_row from public.program_requests where id=p_request_id;
  if v_row.id is null then raise exception 'REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if not (public.has_admin_permission('program_requests.write') or (v_row.company_id is not null and public.is_marketplace_company_member(v_row.company_id,'write'))) then
    raise exception 'REQUEST_DENIED' using errcode='42501';
  end if;
  if p_status not in ('submitted','in_review','approved','rejected','cancelled','requires_financial_processing') then
    raise exception 'REQUEST_STATUS_INVALID' using errcode='22023';
  end if;
  update public.program_requests set status=p_status,notes=coalesce(left(nullif(btrim(coalesce(p_notes,'')),''),2000),notes),updated_at=now()
  where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.validate_operational_request_tracking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_snapshot jsonb;v_status text;v_stage jsonb;
begin
  select workflow_snapshot,status into v_snapshot,v_status from public.program_requests where id=new.request_id;
  if v_snapshot is null or (v_snapshot->>'workflow_id')::uuid is distinct from new.workflow_id then
    raise exception 'REQUEST_TRACKING_WORKFLOW_MISMATCH' using errcode='22023';
  end if;
  if new.current_stage_id is not null then
    select s into v_stage from jsonb_array_elements(v_snapshot->'stages') s where (s->>'id')::uuid=new.current_stage_id;
    if v_stage is null then raise exception 'REQUEST_TRACKING_STAGE_MISMATCH' using errcode='22023'; end if;
    if not (
      coalesce(v_stage->>'outcome','process')='process' and v_status in('submitted','in_review','requires_financial_processing') or
      coalesce(v_stage->>'outcome','process')='success' and v_status='approved' or
      coalesce(v_stage->>'outcome','process')='failure' and v_status in('rejected','cancelled')
    ) then raise exception 'REQUEST_TRACKING_STATUS_MISMATCH' using errcode='22023'; end if;
  end if;
  if exists(select 1 from jsonb_object_keys(coalesce(new.stage_dates,'{}'::jsonb)) key where not exists(select 1 from jsonb_array_elements(v_snapshot->'stages') s where s->>'id'=key)) then
    raise exception 'REQUEST_TRACKING_DATE_STAGE_MISMATCH' using errcode='22023';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_operational_workflow_configuration(p_workflow_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_enabled boolean;v_keys text[];
begin
  select enabled,service_keys into v_enabled,v_keys from public.operational_workflows where id=p_workflow_id;
  if not found or not v_enabled then return; end if;
  if cardinality(v_keys)=0 then raise exception 'WORKFLOW_SERVICE_REQUIRED' using errcode='22023'; end if;
  if exists(
    select 1 from public.operational_workflows other
    where other.id<>p_workflow_id and other.enabled and other.workflow_type='request' and other.service_keys&&v_keys
  ) then raise exception 'WORKFLOW_SERVICE_CONFLICT' using errcode='22023'; end if;
  if not exists(select 1 from public.operational_workflow_stages where workflow_id=p_workflow_id and enabled) then
    raise exception 'WORKFLOW_STAGE_REQUIRED' using errcode='22023';
  end if;
  if exists(
    select 1 from public.operational_workflow_stages s cross join lateral regexp_split_to_table(coalesce(s.status_reference,''),'\s*,\s*') token
    where s.workflow_id=p_workflow_id and s.enabled and token<>'' and token not in('submitted','in_review','approved','rejected','cancelled','requires_financial_processing')
  ) then raise exception 'WORKFLOW_STATUS_REFERENCE_INVALID' using errcode='22023'; end if;
  if exists(
    select 1 from public.operational_workflow_stages a join public.operational_workflow_stages b
      on b.workflow_id=a.workflow_id and b.id>a.id and b.enabled and a.enabled and b.sort_order=a.sort_order
      and (cardinality(a.service_keys)=0 or cardinality(b.service_keys)=0 or a.service_keys&&b.service_keys)
    where a.workflow_id=p_workflow_id
  ) then raise exception 'WORKFLOW_STAGE_ORDER_CONFLICT' using errcode='22023'; end if;
  if exists(
    select 1 from public.operational_workflow_stages a join public.operational_workflow_stages b
      on b.workflow_id=a.workflow_id and b.id>a.id and b.enabled and a.enabled
      and (cardinality(a.service_keys)=0 or cardinality(b.service_keys)=0 or a.service_keys&&b.service_keys)
      and string_to_array(replace(coalesce(a.status_reference,''),' ',''),',')&&string_to_array(replace(coalesce(b.status_reference,''),' ',''),',')
    where a.workflow_id=p_workflow_id and coalesce(a.status_reference,'')<>'' and coalesce(b.status_reference,'')<>''
  ) then raise exception 'WORKFLOW_STATUS_REFERENCE_CONFLICT' using errcode='22023'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.validate_operational_workflow_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_new jsonb:=case when tg_op='DELETE' then '{}'::jsonb else to_jsonb(new) end;v_old jsonb:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;v_id uuid;
begin
  v_id:=nullif(coalesce(v_new->>'workflow_id',v_new->>'id',v_old->>'workflow_id',v_old->>'id'),'')::uuid;
  perform public.validate_operational_workflow_configuration(v_id);
  return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text)
 RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix, 1) = delimiter_param THEN
        v_upper_bound := left(v_prefix, -1) || chr(ascii(delimiter_param) + 1);
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'AND o.name COLLATE "C" < $3 ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'AND o.name COLLATE "C" >= $3 ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor: find the last item in range
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Cursor provided: determine if it refers to a folder or leaf
        IF EXISTS (
            SELECT 1 FROM storage.objects o
            WHERE o.bucket_id = _bucket_id
              AND o.name COLLATE "C" LIKE v_start || delimiter_param || '%'
            LIMIT 1
        ) THEN
            -- Cursor refers to a folder
            IF v_is_asc THEN
                v_next_seek := v_start || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_start || delimiter_param;
            END IF;
        ELSE
            -- Cursor refers to a leaf object
            IF v_is_asc THEN
                v_next_seek := v_start || delimiter_param;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := rtrim(v_common_prefix, delimiter_param);
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1) || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := v_current.name;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                RETURN NEXT;
                v_count := v_count + 1;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := v_current.name || delimiter_param;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text)
 RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text)
 RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_prefix_len INT;
    v_prefix_start INT;
    v_combined_levels INT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_prefix_len := length(coalesce(prefix, ''));
    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);
    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $3 || '%%'
                  AND bucket_id = $4
                  AND array_length(objects.path_tokens, 1) <> $2
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT array_to_string(path_tokens[$1:$2], '/') AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $3 || '%%'
               AND bucket_id = $4
               AND array_length(objects.path_tokens, 1) = $2
             ORDER BY %I %s)
            LIMIT $5 OFFSET $6
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := substring(v_current.name from v_prefix_len + 1);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$function$
